#[async_trait]
impl ToolHandler for AnalysisDataflowComputeReachingDefsTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let cfg = parse_liveness_cfg(&args)?;
        let sets = rustre_analysis_dataflow::compute_reaching_defs(&cfg);
        let mut blocks: Vec<Value> = sets.into_iter().map(|(id, (ri, ro))| {
            json!({ "bb_id": id, "rd_in": ri, "rd_out": ro })
        }).collect();
        blocks.sort_by_key(|v| v.get("bb_id").and_then(Value::as_u64).unwrap_or(0));
        Ok(ToolResult::text(json!({
            "blocks": blocks,
            "source": "rustre_analysis_dataflow::compute_reaching_defs",
        }).to_string()))
    }
}

