// Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ rustre-adb: filter_by_level / filter_by_tag / group_by_tag wrappers Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬

fn parse_log_level(s: &str) -> Option<rustre_adb::LogLevel> {
    match s.to_ascii_lowercase().as_str() {
        "v" | "verbose" => Some(rustre_adb::LogLevel::Verbose),
        "d" | "debug" => Some(rustre_adb::LogLevel::Debug),
        "i" | "info" => Some(rustre_adb::LogLevel::Info),
        "w" | "warning" | "warn" => Some(rustre_adb::LogLevel::Warning),
        "e" | "error" => Some(rustre_adb::LogLevel::Error),
        "f" | "fatal" => Some(rustre_adb::LogLevel::Fatal),
        "s" | "silent" => Some(rustre_adb::LogLevel::Silent),
        _ => None,
    }
}

