        let dll = args.get("dll").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'dll'".into()))?
            .to_string();
        let name = args.get("name").and_then(Value::as_str).unwrap_or("").to_string();
        let hint = args.get("hint").and_then(Value::as_u64).unwrap_or(0) as u16;
