/// Merge N empty trace sessions and report the resulting record count.

impl TraceMergeEmptySessionsTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "trace_merge_empty_sessions".to_string(),
            description:
                "Merge N empty TraceSessions (same arch) via rustre_trace::merge_sessions \
                 and return the merged record count. Useful as a smoke-test entry point."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "count": { "type": "integer" },
                    "arch":  { "type": "string" }
                },
                "required": ["count"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for TraceMergeEmptySessionsTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let count = args
            .get("count")
            .and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'count'".into()))?
            as usize;
        let arch = args
            .get("arch")
            .and_then(Value::as_str)
            .unwrap_or("x86_64");
        let sessions: Vec<rustre_trace::TraceSession> = (0..count)
            .map(|i| rustre_trace::TraceSession::new(format!("s{i}"), arch))
            .collect();
        let merged = rustre_trace::merge_sessions(&sessions)
            .map_err(|e| McpError::InternalError(e.to_string()))?;
        Ok(ToolResult::text(
            json!({
                "input_sessions": count,
                "arch": arch,
                "merged_records": merged.records.len(),
                "merged_name": merged.name,
                "source": "rustre_trace::merge_sessions",
            })
            .to_string(),
        ))
    }
}

