// Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ rustre-trace-navigate Ã¢â‚¬â€ TraceEntry::insn Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬

/// Build a basic instruction `TraceEntry` via `TraceEntry::insn` and return
/// its `Display` form plus key fields.

impl TraceNavigateInsnEntryTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "trace_navigate_insn_entry".to_string(),
            description:
                "Construct a basic instruction TraceEntry via \
                 rustre_trace_navigate::TraceEntry::insn and return its \
                 rendered form."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "idx":    { "type": "integer" },
                    "pc":     { "type": "integer" },
                    "tid":    { "type": "integer" },
                    "disasm": { "type": "string"  }
                },
                "required": ["idx", "pc", "tid", "disasm"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for TraceNavigateInsnEntryTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let idx = args.get("idx").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'idx'".into()))?
            as usize;
        let pc = args.get("pc").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'pc'".into()))?;
        let tid = args.get("tid").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'tid'".into()))?;
        let tid_u32 = u32::try_from(tid)
            .map_err(|_| McpError::InvalidParams("tid exceeds u32".into()))?;
        let disasm = args.get("disasm").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'disasm'".into()))?
            .to_string();
        let entry = rustre_trace_navigate::TraceEntry::insn(idx, pc, tid_u32, disasm);
        Ok(ToolResult::text(
            json!({
                "display": format!("{entry}"),
                "idx": entry.idx,
                "pc": entry.pc,
                "tid": entry.tid,
                "disasm": entry.disasm,
                "is_call": entry.is_call(),
                "is_ret": entry.is_ret(),
                "source": "rustre_trace_navigate::TraceEntry::insn",
            })
            .to_string(),
        ))
    }
}

