/// Parse an LCOV info file text and report record/line/function totals.

impl TraceCovParseLcovTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "trace_cov_parse_lcov".to_string(),
            description:
                "Parse an LCOV info file via rustre_trace_coverage::parse_lcov and report \
                 the number of records plus aggregated lines_found/lines_hit/functions_found/\
                 functions_hit across all records."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "text": {
                        "type": "string",
                        "description": "LCOV info file contents"
                    }
                },
                "required": ["text"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for TraceCovParseLcovTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let text = args
            .get("text")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'text' string".into()))?;
        let records = rustre_trace_coverage::parse_lcov(text);
        let lines_found: u64 = records.iter().map(|r| r.lines_found).sum();
        let lines_hit: u64 = records.iter().map(|r| r.lines_hit).sum();
        let functions_found: u64 = records.iter().map(|r| r.functions_found).sum();
        let functions_hit: u64 = records.iter().map(|r| r.functions_hit).sum();
        Ok(ToolResult::text(
            json!({
                "records": records.len(),
                "lines_found": lines_found,
                "lines_hit": lines_hit,
                "functions_found": functions_found,
                "functions_hit": functions_hit,
                "source": "rustre_trace_coverage::parse_lcov",
            })
            .to_string(),
        ))
    }
}

