impl AgentBumpPriorityTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "agent_bump_priority".to_string(),
            description: "Bump the priority of an AgentTask via \
                          rustre_agent::agent_task_queue::bump_priority. \
                          Inputs: current priority (0..=3) and new priority (0..=3).".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "current": {"type": "integer", "description": "Current priority 0..=3"},
                    "new": {"type": "integer", "description": "New priority 0..=3"}
                },
                "required": ["current", "new"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for AgentBumpPriorityTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        use rustre_agent::agent_task_queue::{AgentTask as QTask, TaskPriority as QPrio};
        fn to_prio(n: u64) -> Result<QPrio, McpError> {
            match n {
                0 => Ok(QPrio::Low),
                1 => Ok(QPrio::Normal),
                2 => Ok(QPrio::High),
                3 => Ok(QPrio::Critical),
                _ => Err(McpError::InvalidParams("priority must be 0..=3".into())),
            }
        }
        let cur = args.get("current").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'current'".into()))?;
        let new = args.get("new").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'new'".into()))?;
        let cur_p = to_prio(cur)?;
        let new_p = to_prio(new)?;
        let task = QTask::new("wire_bump_priority", "analyze", cur_p, Value::Null);
        let bumped = rustre_agent::agent_task_queue::bump_priority(task, new_p);
        Ok(ToolResult::text(
            json!({
                "resulting_priority": format!("{:?}", bumped.priority),
                "source": "rustre_agent::agent_task_queue::bump_priority",
            })
            .to_string(),
        ))
    }
}

