/// Expose `rustre_emu_unicorn::Mode::ptr_size` as an MCP tool.

#[cfg(any())] // [DISABLED 2026-07-12]
impl EmuUnicornModePtrSizeTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "emu_unicorn_mode_ptr_size".to_string(),
            description: "Return the pointer size in bytes for a Unicorn emulator Mode identifier.".to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["mode"],
                "properties": {
                    "mode": { "type": "string", "description": "Mode name (e.g. 'X86_64', 'ArmMode', 'Mips32BE')" }
                }
            }),
            parameters: Value::Null,
        }
    }

    fn parse_mode(name: &str) -> Option<rustre_emu_unicorn::Mode> {
        use rustre_emu_unicorn::Mode;
        Some(match name {
            "X86_16" => Mode::X86_16,
            "X86_32" => Mode::X86_32,
            "X86_64" => Mode::X86_64,
            "ArmMode" => Mode::ArmMode,
            "ThumbMode" => Mode::ThumbMode,
            "Arm64Mode" => Mode::Arm64Mode,
            "Mips32LE" => Mode::Mips32LE,
            "Mips32BE" => Mode::Mips32BE,
            "Mips64LE" => Mode::Mips64LE,
            "Mips64BE" => Mode::Mips64BE,
            "Sparc32" => Mode::Sparc32,
            "Sparc64" => Mode::Sparc64,
            "RiscV32" => Mode::RiscV32,
            "RiscV64" => Mode::RiscV64,
            "M68K" => Mode::M68K,
            "Ppc32" => Mode::Ppc32,
            "Ppc64" => Mode::Ppc64,
            "S390X" => Mode::S390X,
            _ => return None,
        })
    }
}

#[cfg(any())] // [DISABLED 2026-07-12]
#[async_trait]
impl ToolHandler for EmuUnicornModePtrSizeTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let mode_str = args.get("mode").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'mode'".into()))?;
        let mode = Self::parse_mode(mode_str)
            .ok_or_else(|| McpError::InvalidParams(format!("unknown mode '{mode_str}'")))?;
        let ptr_size = mode.ptr_size();
        Ok(ToolResult::text(
            json!({ "mode": mode_str, "ptr_size": ptr_size }).to_string(),
        ))
    }
}

