impl DotnetEditNopFillRangeTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "dotnet_edit_nop_fill_range".to_string(),
            description: "Replace a byte-offset range of CIL instructions with nops via \
                          rustre_dotnet_edit::nop_fill_range."
                .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "opcodes": {
                        "type": "array",
                        "items": {"type": "string"},
                        "description": "Ordered list of CIL opcode mnemonics"
                    },
                    "start_offset": {"type": "integer", "minimum": 0},
                    "end_offset": {"type": "integer", "minimum": 0}
                },
                "required": ["opcodes", "start_offset", "end_offset"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for DotnetEditNopFillRangeTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let arr = args.get("opcodes").and_then(Value::as_array)
            .ok_or_else(|| McpError::InvalidParams("missing 'opcodes'".into()))?;
        let start = args.get("start_offset").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'start_offset'".into()))? as u32;
        let end = args.get("end_offset").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'end_offset'".into()))? as u32;
        let mut instrs: Vec<rustre_dotnet::CilInstruction> = arr
            .iter()
            .filter_map(|v| v.as_str())
            .enumerate()
            .map(|(i, op)| rustre_dotnet::CilInstruction::simple(i as u32, op))
            .collect();
        rustre_dotnet_edit::nop_fill_range(&mut instrs, start, end)
            .map_err(|e| McpError::InternalError(e.to_string()))?;
        let opcodes: Vec<String> = instrs.iter().map(|i| i.opcode.clone()).collect();
        Ok(ToolResult::text(
            json!({
                "count": opcodes.len(),
                "opcodes": opcodes,
                "source": "rustre_dotnet_edit::nop_fill_range",
            })
            .to_string(),
        ))
    }
}

