impl FuzzRankSeedsByPriorityTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "fuzz_rank_seeds_by_priority".to_string(),
            description: "Rank seeds by priority score using \
                          rustre_fuzz::smart_seed_scheduler::rank_seeds_by_priority. \
                          Input is an array of [score, id] pairs; returns ids sorted \
                          high-priority first.".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "scores": {
                        "type": "array",
                        "description": "Array of [score:f64, id:u64] pairs",
                        "items": {"type": "array"}
                    }
                },
                "required": ["scores"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for FuzzRankSeedsByPriorityTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let arr = args.get("scores").and_then(Value::as_array)
            .ok_or_else(|| McpError::InvalidParams("missing 'scores' array".into()))?;
        let mut scores: Vec<(f64, u64)> = Vec::with_capacity(arr.len());
        for entry in arr {
            let pair = entry.as_array()
                .ok_or_else(|| McpError::InvalidParams("scores entry must be [score, id]".into()))?;
            if pair.len() != 2 {
                return Err(McpError::InvalidParams("scores entry must have exactly 2 elements".into()));
            }
            let score = pair[0].as_f64()
                .ok_or_else(|| McpError::InvalidParams("score must be a number".into()))?;
            let id = pair[1].as_u64()
                .ok_or_else(|| McpError::InvalidParams("id must be an unsigned integer".into()))?;
            scores.push((score, id));
        }
        let ranked = rustre_fuzz::smart_seed_scheduler::rank_seeds_by_priority(&scores);
        Ok(ToolResult::text(
            json!({
                "count": ranked.len(),
                "ranked_ids": ranked,
                "source": "rustre_fuzz::smart_seed_scheduler::rank_seeds_by_priority",
            })
            .to_string(),
        ))
    }
}

