impl SymbEngineWidenSequenceCheckTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "symb_engine_widen_sequence_check".to_string(),
            description: "Check whether a numeric sequence is widenable to a \
                          symbolic recurrence via \
                          rustre_symb_engine::loop_summarizer::widen_sequence. \
                          Returns whether a uniform step was found.".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "values": {
                        "type": "array",
                        "description": "Sequence of u64 values",
                        "items": {"type": "integer"}
                    }
                },
                "required": ["values"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for SymbEngineWidenSequenceCheckTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let arr = args.get("values").and_then(Value::as_array)
            .ok_or_else(|| McpError::InvalidParams("missing 'values' array".into()))?;
        let mut values: Vec<u64> = Vec::with_capacity(arr.len());
        for v in arr {
            let n = v.as_u64()
                .ok_or_else(|| McpError::InvalidParams("values entries must be u64".into()))?;
            values.push(n);
        }
        let result = rustre_symb_engine::loop_summarizer::widen_sequence(&values);
        Ok(ToolResult::text(
            json!({
                "widenable": result.is_some(),
                "count": values.len(),
                "source": "rustre_symb_engine::loop_summarizer::widen_sequence",
            })
            .to_string(),
        ))
    }
}

