/// Fold `lhs + rhs` on two constant bitvectors via `rustre_symb::sym_add`.

impl SymbSymAddConstTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "symb_sym_add_const".to_string(),
            description:
                "Constant-fold `lhs + rhs` (bitvector add) via rustre_symb::sym_add. \
                 Both operands must be constant bitvectors of the same width."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["lhs", "rhs", "width"],
                "properties": {
                    "lhs":   { "type": "integer" },
                    "rhs":   { "type": "integer" },
                    "width": { "type": "integer", "minimum": 1, "maximum": 64 }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for SymbSymAddConstTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let lhs = args.get("lhs").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'lhs'".into()))?;
        let rhs = args.get("rhs").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'rhs'".into()))?;
        let width = args.get("width").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'width'".into()))? as u32;
        let expr = rustre_symb::sym_add(
            rustre_symb::SymExpr::bv(lhs, width),
            rustre_symb::SymExpr::bv(rhs, width),
        );
        let folded = expr.as_const_u64();
        Ok(ToolResult::text(
            json!({
                "lhs": lhs,
                "rhs": rhs,
                "width": width,
                "result": folded,
                "source": "rustre_symb::sym_add",
            })
            .to_string(),
        ))
    }
}

