/// Brute-force all 256 single-byte XOR keys and return the top-3 candidates.

impl DeobfStringXorBruteforceTop3Tool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "deobf_string_xor_bruteforce_top3".to_string(),
            description:
                "Brute-force all 256 single-byte XOR keys against the input bytes, \
                 scored by printable-ratio, returning the top-3 candidates \
                 (rustre_deobf_string::xor_brute_force_top3)."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "bytes": { "type": "array", "items": { "type": "integer" } },
                    "hex":   { "type": "string" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for DeobfStringXorBruteforceTop3Tool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let data = args_to_bytes(&args)?;
        let candidates = rustre_deobf_string::xor_brute_force_top3(&data);
        let json_candidates: Vec<Value> = candidates
            .iter()
            .map(|c| {
                json!({
                    "key": c.key,
                    "decrypted_hex": hex_encode(&c.decrypted),
                    "printable_ratio": c.printable_ratio,
                    "confidence": c.confidence,
                    "decoded_utf8": c.decoded_utf8,
                    "decoded_utf8_lossy": c.decoded_utf8_lossy,
                })
            })
            .collect();
        Ok(ToolResult::text(
            json!({
                "input_len": data.len(),
                "candidates": json_candidates,
                "source": "rustre_deobf_string::xor_brute_force_top3",
            })
            .to_string(),
        ))
    }
}

