impl TtdReplayBuildCallGraphTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "ttd_replay_build_call_graph".to_string(),
            description: "Build a call-count edge table from a synthetic TTD trace of n events via rustre_ttd_replay::build_call_graph.".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "n": {"type": "integer", "description": "Number of events (u64)"}
                },
                "required": ["n"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for TtdReplayBuildCallGraphTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let n = args.get("n").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'n'".into()))?;
        let trace = rustre_ttd::build_test_trace(n);
        let edges = rustre_ttd_replay::build_call_graph(&trace);
        let total: u64 = edges.iter().map(|e| e.count).sum();
        Ok(ToolResult::text(
            json!({
                "n": n,
                "edge_count": edges.len(),
                "total_calls": total,
                "source": "rustre_ttd_replay::build_call_graph",
            })
            .to_string(),
        ))
    }
}

impl TtdReplaySplitByThreadTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "ttd_replay_split_by_thread".to_string(),
            description: "Split a synthetic multi-thread TTD trace of n events into per-thread timelines via rustre_ttd_replay::split_by_thread.".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "n": {"type": "integer", "description": "Number of events (u64)"}
                },
                "required": ["n"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for TtdReplaySplitByThreadTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let n = args.get("n").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'n'".into()))?;
        let trace = rustre_ttd::build_multi_thread_trace(n);
        let timelines = rustre_ttd_replay::split_by_thread(&trace);
        let mut tids: Vec<u32> = timelines.keys().copied().collect();
        tids.sort_unstable();
        let per_thread_counts: Vec<(u32, usize)> =
            tids.iter().map(|t| (*t, timelines[t].event_count())).collect();
        Ok(ToolResult::text(
            json!({
                "n": n,
                "thread_count": timelines.len(),
                "thread_ids": tids,
                "per_thread_event_counts": per_thread_counts,
                "source": "rustre_ttd_replay::split_by_thread",
            })
            .to_string(),
        ))
    }
}

