/// Parse an AFL-format dictionary file text via `rustre_fuzz_afl::Dictionary::load_afl_format`.

impl FuzzAflDictLoadTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "fuzz_afl_dict_load".to_string(),
            description:
                "Parse an AFL-format dictionary (one token per line, quoted strings and x\"hex\" \
                 supported) via rustre_fuzz_afl::Dictionary::load_afl_format. Returns token count \
                 and the parsed entries."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["text"],
                "properties": {
                    "text": { "type": "string" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for FuzzAflDictLoadTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let text = args.get("text").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'text'".into()))?;
        let mut dict = rustre_fuzz_afl::Dictionary::new();
        let count = dict.load_afl_format(text)
            .map_err(|e| McpError::InternalError(format!("dict parse: {e}")))?;
        let entries: Vec<String> = dict.entries.iter()
            .map(|t| String::from_utf8_lossy(t).into_owned())
            .collect();
        Ok(ToolResult::text(
            json!({
                "count": count,
                "entries": entries,
                "source": "rustre_fuzz_afl::Dictionary::load_afl_format",
            })
            .to_string(),
        ))
    }
}

