/// Build a canonical `ApktoolConfig` JSON blob from an apktool path and output dir.

impl MobileApktoolConfigNewTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "mobile_apktool_config_new".to_string(),
            description:
                "Construct an ApktoolConfig with optional no_src/no_res/force flags."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "apktool_path": { "type": "string" },
                    "output_dir":   { "type": "string" },
                    "no_src":       { "type": "boolean" },
                    "no_res":       { "type": "boolean" },
                    "force":        { "type": "boolean" }
                },
                "required": ["apktool_path", "output_dir"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for MobileApktoolConfigNewTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let path = args.get("apktool_path").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'apktool_path'".into()))?;
        let out = args.get("output_dir").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'output_dir'".into()))?;
        let mut cfg = rustre_mobile_apktool::ApktoolConfig::new(path, out);
        if args.get("no_src").and_then(Value::as_bool).unwrap_or(false) {
            cfg = cfg.with_no_src();
        }
        if args.get("no_res").and_then(Value::as_bool).unwrap_or(false) {
            cfg = cfg.with_no_res();
        }
        if args.get("force").and_then(Value::as_bool).unwrap_or(false) {
            cfg = cfg.with_force();
        }
        Ok(ToolResult::text(
            json!({
                "config": cfg,
                "source": "rustre_mobile_apktool::ApktoolConfig::new",
            })
            .to_string(),
        ))
    }
}

