/// Detect whether raw bytes look like an Apple binary plist (`bplist00` magic).

impl MobileIpaIsBinaryPlistTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "mobile_ipa_is_binary_plist".to_string(),
            description:
                "Return true when the provided bytes (hex-encoded) start with the bplist00 magic."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "hex": { "type": "string", "description": "Hex-encoded bytes to test." }
                },
                "required": ["hex"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for MobileIpaIsBinaryPlistTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let hex_str = args.get("hex").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'hex'".into()))?;
        let cleaned: String = hex_str.chars().filter(|c| !c.is_whitespace()).collect();
        let mut bytes = Vec::with_capacity(cleaned.len() / 2);
        let cbytes = cleaned.as_bytes();
        let mut i = 0;
        while i + 1 < cbytes.len() {
            let hi = (cbytes[i] as char).to_digit(16)
                .ok_or_else(|| McpError::InvalidParams("invalid hex".into()))?;
            let lo = (cbytes[i + 1] as char).to_digit(16)
                .ok_or_else(|| McpError::InvalidParams("invalid hex".into()))?;
            bytes.push(((hi << 4) | lo) as u8);
            i += 2;
        }
        let is_bplist = rustre_mobile_ipa::SimplePlistReader::is_binary_plist(&bytes);
        Ok(ToolResult::text(
            json!({
                "is_binary_plist": is_bplist,
                "byte_len": bytes.len(),
                "source": "rustre_mobile_ipa::SimplePlistReader::is_binary_plist",
            })
            .to_string(),
        ))
    }
}

