/// Compute FLIRT CRC-16 (poly 0x8408, reflected) over hex-encoded bytes.

impl FlirtCrc16Tool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "flirt_crc16".to_string(),
            description:
                "Compute the FLIRT CRC-16 (MCRF4XX, poly 0x8408 reflected) over \
                 the given hex-encoded bytes. Uses \
                 rustre_flirt_apply::crc16_flirt."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "hex": { "type": "string", "description": "Hex bytes, e.g. 'AA BB CC' or 'AABBCC'." }
                },
                "required": ["hex"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for FlirtCrc16Tool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let hex_str = args
            .get("hex")
            .and_then(|v| v.as_str())
            .ok_or_else(|| McpError::InvalidParams("missing 'hex'".into()))?;
        let cleaned: String = hex_str.chars().filter(|c| !c.is_whitespace()).collect();
        if cleaned.len() % 2 != 0 {
            return Err(McpError::InvalidParams("hex must have even length".into()));
        }
        let mut bytes = Vec::with_capacity(cleaned.len() / 2);
        let cb = cleaned.as_bytes();
        for i in (0..cb.len()).step_by(2) {
            let s = std::str::from_utf8(&cb[i..i + 2])
                .map_err(|e| McpError::InvalidParams(e.to_string()))?;
            let b = u8::from_str_radix(s, 16)
                .map_err(|e| McpError::InvalidParams(e.to_string()))?;
            bytes.push(b);
        }
        let crc = rustre_flirt_apply::crc16_flirt(&bytes);
        Ok(ToolResult::text(
            json!({
                "crc": crc,
                "crc_hex": format!("{:04x}", crc),
                "bytes_len": bytes.len(),
                "source": "rustre_flirt_apply::crc16_flirt",
            })
            .to_string(),
        ))
    }
}

