/// Parse a FLIRT hex pattern string via
/// `rustre_flirt_apply::FlirtPattern::from_pattern_str`.

impl FlirtParsePatternTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "flirt_parse_pattern".to_string(),
            description:
                "Parse a FLIRT hex pattern (e.g. '55 8B EC ?? 8B') via \
                 rustre_flirt_apply::FlirtPattern::from_pattern_str and report \
                 length + wildcard count."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "pattern": { "type": "string" },
                    "name": { "type": "string" },
                    "lib": { "type": "string" }
                },
                "required": ["pattern"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for FlirtParsePatternTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let pattern = args
            .get("pattern")
            .and_then(|v| v.as_str())
            .ok_or_else(|| McpError::InvalidParams("missing 'pattern'".into()))?;
        let name = args
            .get("name")
            .and_then(|v| v.as_str())
            .unwrap_or("unnamed")
            .to_string();
        let lib = args
            .get("lib")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let pat = rustre_flirt_apply::FlirtPattern::from_pattern_str(pattern, name, lib)
            .map_err(|e| McpError::InvalidParams(e.to_string()))?;
        let wildcards = pat.bytes.iter().filter(|b| b.is_none()).count();
        Ok(ToolResult::text(
            json!({
                "length": pat.pattern_len(),
                "wildcards": wildcards,
                "name": pat.name,
                "lib_name": pat.lib_name,
                "source": "rustre_flirt_apply::FlirtPattern::from_pattern_str",
            })
            .to_string(),
        ))
    }
}

