/// Weisfeiler-Lehman graph hash for a general CFG adjacency list.

impl DiffBindiffWlHashTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "diff_bindiff_wl_hash".to_string(),
            description:
                "Weisfeiler-Lehman structural hash of a CFG adjacency list via rustre_diff_bindiff::CfgHasher::wl_hash."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "adjacency": { "type": "array" },
                    "iterations": { "type": "integer" }
                },
                "required": ["adjacency"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for DiffBindiffWlHashTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let adj_val = args
            .get("adjacency")
            .and_then(Value::as_array)
            .ok_or_else(|| McpError::InvalidParams("missing 'adjacency'".into()))?;
        let mut adjacency: Vec<(u32, Vec<u32>)> = Vec::with_capacity(adj_val.len());
        for entry in adj_val {
            let id = entry
                .get("id")
                .and_then(Value::as_u64)
                .ok_or_else(|| McpError::InvalidParams("adjacency entry missing 'id'".into()))?;
            let id_u32 = u32::try_from(id)
                .map_err(|_| McpError::InvalidParams("id out of u32 range".into()))?;
            let succs = entry
                .get("successors")
                .and_then(Value::as_array)
                .cloned()
                .unwrap_or_default();
            let mut succ_vec: Vec<u32> = Vec::with_capacity(succs.len());
            for s in succs {
                let n = s
                    .as_u64()
                    .ok_or_else(|| McpError::InvalidParams("successor not integer".into()))?;
                succ_vec.push(
                    u32::try_from(n)
                        .map_err(|_| McpError::InvalidParams("successor out of u32 range".into()))?,
                );
            }
            adjacency.push((id_u32, succ_vec));
        }
        let iterations = args
            .get("iterations")
            .and_then(Value::as_u64)
            .and_then(|n| u32::try_from(n).ok())
            .unwrap_or(3);
        let hash = rustre_diff_bindiff::CfgHasher::wl_hash(&adjacency, iterations);
        Ok(ToolResult::text(
            json!({
                "hash": hash,
                "nodes": adjacency.len(),
                "iterations": iterations,
                "source": "rustre_diff_bindiff::CfgHasher::wl_hash",
            })
            .to_string(),
        ))
    }
}

pub(crate) fn parse_bindiff_function_info(v: &Value) -> rustre_diff_bindiff::FunctionInfo {
    let address = v.get("address").and_then(Value::as_u64).unwrap_or(0);
    let mut fi = rustre_diff_bindiff::FunctionInfo::new(address);
    fi.name = v
        .get("name")
        .and_then(Value::as_str)
        .map(std::string::ToString::to_string);
    fi.bytes_crc32 = v
        .get("bytes_crc32")
        .and_then(Value::as_u64)
        .and_then(|n| u32::try_from(n).ok())
        .unwrap_or(0);
    fi.in_edges = v
        .get("in_edges")
        .and_then(Value::as_u64)
        .and_then(|n| u32::try_from(n).ok())
        .unwrap_or(0);
    fi.out_edges = v
        .get("out_edges")
        .and_then(Value::as_u64)
        .and_then(|n| u32::try_from(n).ok())
        .unwrap_or(0);
    fi.bb_count = v
        .get("bb_count")
        .and_then(Value::as_u64)
        .and_then(|n| u32::try_from(n).ok())
        .unwrap_or(0);
    fi.md_index = v.get("md_index").and_then(Value::as_u64).unwrap_or(0);
    fi
}

