/// Structural CFG hash for an arbitrary adjacency list via `CfgHasher::hash_cfg` (WL-3).

impl DiffBindiffCfgHashTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "diff_bindiff_cfg_hash".to_string(),
            description:
                "Address-invariant structural hash of a CFG adjacency list via rustre_diff_bindiff::CfgHasher::hash_cfg (Weisfeiler-Lehman, 3 iterations)."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": { "adjacency": { "type": "array" } },
                "required": ["adjacency"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for DiffBindiffCfgHashTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let adj_val = args
            .get("adjacency")
            .and_then(Value::as_array)
            .ok_or_else(|| McpError::InvalidParams("missing 'adjacency'".into()))?;
        let mut adjacency: Vec<(u32, Vec<u32>)> = Vec::with_capacity(adj_val.len());
        for entry in adj_val {
            let id = entry
                .get("id")
                .and_then(Value::as_u64)
                .ok_or_else(|| McpError::InvalidParams("adjacency entry missing 'id'".into()))?;
            let id_u32 = u32::try_from(id)
                .map_err(|_| McpError::InvalidParams("id out of u32 range".into()))?;
            let succs = entry
                .get("successors")
                .and_then(Value::as_array)
                .cloned()
                .unwrap_or_default();
            let mut succ_vec: Vec<u32> = Vec::with_capacity(succs.len());
            for s in succs {
                let n = s
                    .as_u64()
                    .ok_or_else(|| McpError::InvalidParams("successor not integer".into()))?;
                succ_vec.push(
                    u32::try_from(n)
                        .map_err(|_| McpError::InvalidParams("successor out of u32 range".into()))?,
                );
            }
            adjacency.push((id_u32, succ_vec));
        }
        let hash = rustre_diff_bindiff::CfgHasher::hash_cfg(&adjacency);
        Ok(ToolResult::text(
            json!({
                "hash": hash,
                "nodes": adjacency.len(),
                "source": "rustre_diff_bindiff::CfgHasher::hash_cfg",
            })
            .to_string(),
        ))
    }
}

