// Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ rustre-flirt Ã¢â‚¬â€ extra pub fns Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬

pub(crate) fn parse_match_kind_bindiff_extra(s: &str) -> Option<rustre_diff_bindiff::MatchKind> {
    use rustre_diff_bindiff::MatchKind;
    match s {
        "ExactHash" => Some(MatchKind::ExactHash),
        "CfgHash" => Some(MatchKind::CfgHash),
        "CallGraphPropagation" => Some(MatchKind::CallGraphPropagation),
        "NameMatch" => Some(MatchKind::NameMatch),
        "ManualMatch" => Some(MatchKind::ManualMatch),
        "Heuristic" => Some(MatchKind::Heuristic),
        _ => None,
    }
}

pub(crate) fn parse_bindiff_matrix(v: &Value) -> Result<Vec<Vec<f64>>, McpError> {
    let arr = v.as_array().ok_or_else(|| McpError::InvalidParams("matrix must be array of arrays".into()))?;
    let mut out: Vec<Vec<f64>> = Vec::with_capacity(arr.len());
    for row in arr {
        let r = row.as_array().ok_or_else(|| McpError::InvalidParams("row must be array".into()))?;
        let mut rv: Vec<f64> = Vec::with_capacity(r.len());
        for x in r { rv.push(x.as_f64().ok_or_else(|| McpError::InvalidParams("cell must be number".into()))?); }
        out.push(rv);
    }
    if out.is_empty() { return Err(McpError::InvalidParams("matrix must not be empty".into())); }
    Ok(out)
}

pub(crate) fn parse_bindiff_function_info_list(v: &Value) -> Result<Vec<rustre_diff_bindiff::FunctionInfo>, McpError> {
    let arr = v.as_array().ok_or_else(|| McpError::InvalidParams("expected array".into()))?;
    Ok(arr.iter().map(parse_bindiff_function_info).collect())
}

