/// Compute a MinHash signature over a set of u64 elements.

impl DiffSemanticMinhashSignatureTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "diff_semantic_minhash_signature".to_string(),
            description: "Compute a MinHash signature (Vec<u64>) over the given u64 elements using `num_hashes` hash functions.".to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["num_hashes", "elements"],
                "properties": {
                    "num_hashes": { "type": "integer", "description": "Number of MinHash functions" },
                    "elements": { "type": "array", "items": { "type": "integer" }, "description": "Input u64 elements" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for DiffSemanticMinhashSignatureTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let num_hashes = args.get("num_hashes").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'num_hashes'".into()))? as usize;
        let elements: Vec<u64> = args.get("elements").and_then(Value::as_array)
            .ok_or_else(|| McpError::InvalidParams("missing 'elements'".into()))?
            .iter().filter_map(Value::as_u64).collect();
        let mh = rustre_diff_semantic::MinHash::new(num_hashes);
        let sig = mh.signature(&elements);
        Ok(ToolResult::text(json!({ "num_hashes": num_hashes, "signature": sig }).to_string()))
    }
}

