/// Scan x86-64 bytes and return masked (variable) operand ranges via
/// `rustre_flirt_gen::scan_x86_masks`.

impl FlirtGenScanX86MasksTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "flirt_gen_scan_x86_masks".to_string(),
            description:
                "Scan x86-64 bytes and return masked (offset,size) ranges for \
                 relocatable operands via rustre_flirt_gen::scan_x86_masks."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "hex": { "type": "string" }
                },
                "required": ["hex"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for FlirtGenScanX86MasksTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let hex_str = args
            .get("hex")
            .and_then(|v| v.as_str())
            .ok_or_else(|| McpError::InvalidParams("missing 'hex'".into()))?;
        let cleaned: String = hex_str.chars().filter(|c| !c.is_whitespace()).collect();
        if cleaned.len() % 2 != 0 {
            return Err(McpError::InvalidParams("hex must have even length".into()));
        }
        let mut bytes = Vec::with_capacity(cleaned.len() / 2);
        let cb = cleaned.as_bytes();
        for i in (0..cb.len()).step_by(2) {
            let s = std::str::from_utf8(&cb[i..i + 2])
                .map_err(|e| McpError::InvalidParams(e.to_string()))?;
            let b = u8::from_str_radix(s, 16)
                .map_err(|e| McpError::InvalidParams(e.to_string()))?;
            bytes.push(b);
        }
        let ranges = rustre_flirt_gen::scan_x86_masks(&bytes);
        let ranges_json: Vec<_> = ranges
            .iter()
            .map(|(off, sz)| json!({ "offset": off, "size": sz }))
            .collect();
        Ok(ToolResult::text(
            json!({
                "count": ranges.len(),
                "ranges": ranges_json,
                "bytes_len": bytes.len(),
                "source": "rustre_flirt_gen::scan_x86_masks",
            })
            .to_string(),
        ))
    }
}

