/// Parse an ELF relocatable object at `path` via
/// `rustre_flirt_gen::ElfObjectParser::parse` and report function count.

impl FlirtGenElfParseTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "flirt_gen_elf_parse".to_string(),
            description:
                "Parse an ELF .o file at `path` and report the number of \
                 STT_FUNC entries extracted via \
                 rustre_flirt_gen::ElfObjectParser::parse."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "path": { "type": "string" }
                },
                "required": ["path"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for FlirtGenElfParseTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let path = args
            .get("path")
            .and_then(|v| v.as_str())
            .ok_or_else(|| McpError::InvalidParams("missing 'path'".into()))?;
        let bytes = std::fs::read(path)
            .map_err(|e| McpError::InvalidParams(format!("read {path}: {e}")))?;
        let funcs = rustre_flirt_gen::ElfObjectParser::parse(&bytes)
            .map_err(|e| McpError::InvalidParams(e.to_string()))?;
        let names: Vec<&str> = funcs.iter().take(16).map(|(n, _, _)| n.as_str()).collect();
        Ok(ToolResult::text(
            json!({
                "function_count": funcs.len(),
                "sample_names": names,
                "bytes_read": bytes.len(),
                "source": "rustre_flirt_gen::ElfObjectParser::parse",
            })
            .to_string(),
        ))
    }
}

