impl LoaderPeIsSignedTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "loader_pe_is_signed".to_string(),
            description:
                "Parse a PE file and report whether it is Authenticode-signed."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["path"],
                "properties": {
                    "path": { "type": "string" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for LoaderPeIsSignedTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let path = args.get("path").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'path'".into()))?;
        let data = std::fs::read(path)
            .map_err(|e| McpError::InternalError(format!("read {path}: {e}")))?;
        let pe = rustre_loader_pe::PeInfo::parse(&data)
            .map_err(|e| McpError::InternalError(format!("PeInfo::parse: {e}")))?;
        Ok(ToolResult::text(json!({
            "path": path,
            "is_signed": pe.is_signed(),
            "cert_count": pe.authenticode_certs.len(),
            "source": "rustre_loader_pe::PeInfo::is_signed",
        }).to_string()))
    }
}

