#[async_trait]
impl ToolHandler for LoaderElfInfoSummaryTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let data = args_to_bytes(&args)?;
        let info = rustre_loader_elf::ElfInfo::parse(&data)
            .map_err(|e| McpError::InvalidParams(format!("ELF parse: {e}")))?;
        let build_id_hex = info.build_id().map(hex_encode);
        Ok(ToolResult::text(
            json!({
                "arch": format!("{:?}", info.arch),
                "bits": info.bits,
                "endian": format!("{:?}", info.endian),
                "elf_type": format!("{:?}", info.elf_type),
                "entry_point": info.entry_point,
                "segments": info.segments.len(),
                "sections": info.sections.len(),
                "symbols": info.symbols.len(),
                "dynamic_symbols": info.dynamic_symbols.len(),
                "plt_entries": info.plt_entries.len(),
                "needed_libs": info.needed_libs,
                "soname": info.soname,
                "rpath": info.rpath,
                "interpreter": info.interpreter,
                "build_id": build_id_hex,
                "debug_link": info.debug_link,
                "relocation_count": info.relocation_count,
                "stripped": info.stripped,
                "source": "rustre_loader_elf::ElfInfo::parse",
            })
            .to_string(),
        ))
    }
}

