/// Expose `rustre_mem::page_align_up` as an MCP tool.

impl MemPageAlignUpTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "mem_page_align_up".to_string(),
            description: "Round an address up to the next multiple of page_size (rustre_mem::page_align_up).".to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["addr", "page_size"],
                "properties": {
                    "addr": { "type": "integer" },
                    "page_size": { "type": "integer" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for MemPageAlignUpTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let addr = args.get("addr").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'addr'".into()))?;
        let page_size = args.get("page_size").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'page_size'".into()))?;
        if page_size == 0 {
            return Err(McpError::InvalidParams("'page_size' must be non-zero".into()));
        }
        let aligned = rustre_mem::page_align_up(rustre_core::address::Address::new(addr), page_size);
        Ok(ToolResult::text(
            json!({ "addr": addr, "page_size": page_size, "aligned": aligned.as_u64(), "source": "rustre_mem::page_align_up" }).to_string(),
        ))
    }
}

