/// Serialize a synthetic in-memory symbol list to CSV via `SymbolExporter::to_csv`.

impl SymbolsExporterToCsvTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "symbols_exporter_to_csv".to_string(),
            description: "Export a list of {name,address[,kind]} symbols to CSV \
                using rustre_symbols::SymbolExporter::to_csv.".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "symbols": {
                        "type": "array",
                        "items": {
                            "type": "object",
                            "properties": {
                                "name": {"type": "string"},
                                "address": {"type": "integer"},
                                "kind": {"type": "string"}
                            }
                        }
                    }
                },
                "required": ["symbols"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for SymbolsExporterToCsvTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let arr = args.get("symbols").and_then(Value::as_array)
            .ok_or_else(|| McpError::InvalidParams("missing 'symbols'".into()))?;
        let mut syms = Vec::with_capacity(arr.len());
        for v in arr {
            let name = v.get("name").and_then(Value::as_str)
                .ok_or_else(|| McpError::InvalidParams("symbol missing 'name'".into()))?;
            let address = v.get("address").and_then(Value::as_u64)
                .ok_or_else(|| McpError::InvalidParams("symbol missing 'address'".into()))?;
            let kind = match v.get("kind").and_then(Value::as_str).unwrap_or("Function") {
                "Data" => rustre_symbols::SymKind::Data,
                "Label" => rustre_symbols::SymKind::Label,
                "Section" => rustre_symbols::SymKind::Section,
                _ => rustre_symbols::SymKind::Function,
            };
            syms.push(rustre_symbols::Symbol::new(name.to_string(), address, kind));
        }
        let csv = rustre_symbols::SymbolExporter::to_csv(&syms);
        Ok(ToolResult::text(json!({
            "csv": csv,
            "count": syms.len(),
            "source": "rustre_symbols::SymbolExporter::to_csv",
        }).to_string()))
    }
}

/// Test whether two function-boundary ranges overlap.

impl SymbolsFunctionBoundaryOverlapsTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "symbols_function_boundary_overlaps".to_string(),
            description: "Check whether two [start,end) function boundary ranges overlap \
                using rustre_symbols::FunctionBoundary::overlaps.".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "a_start": {"type": "integer"},
                    "a_end":   {"type": "integer"},
                    "b_start": {"type": "integer"},
                    "b_end":   {"type": "integer"}
                },
                "required": ["a_start","a_end","b_start","b_end"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for SymbolsFunctionBoundaryOverlapsTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let get = |k: &str| args.get(k).and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams(format!("missing '{k}'")));
        let a_start = get("a_start")?;
        let a_end = get("a_end")?;
        let b_start = get("b_start")?;
        let b_end = get("b_end")?;
        let a = rustre_symbols::FunctionBoundary::new(a_start, a_end, "a".into());
        let b = rustre_symbols::FunctionBoundary::new(b_start, b_end, "b".into());
        let overlaps = a.overlaps(&b);
        Ok(ToolResult::text(json!({
            "overlaps": overlaps,
            "a": {"start": a.start, "end": a.end, "size": a.size()},
            "b": {"start": b.start, "end": b.end, "size": b.size()},
            "source": "rustre_symbols::FunctionBoundary::overlaps",
        }).to_string()))
    }
}

/// Return the confidence priority for a named `SymbolSource`.

impl SymbolsSymbolSourcePriorityTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "symbols_symbol_source_priority".to_string(),
            description: "Return the numeric confidence priority of a SymbolSource \
                via rustre_symbols::SymbolSource::priority. Accepts: pdb, dwarf, codeview, \
                stabs, flirt, manual, inferred, import, export, elf, pe, ai.".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": { "source": {"type": "string"} },
                "required": ["source"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for SymbolsSymbolSourcePriorityTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let s = args.get("source").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'source'".into()))?;
        let src = match s.to_ascii_lowercase().as_str() {
            "pdb" => rustre_symbols::SymbolSource::Pdb,
            "dwarf" => rustre_symbols::SymbolSource::Dwarf,
            "codeview" => rustre_symbols::SymbolSource::CodeView,
            "stabs" => rustre_symbols::SymbolSource::Stabs,
            "flirt" => rustre_symbols::SymbolSource::Flirt,
            "manual" => rustre_symbols::SymbolSource::Manual,
            "inferred" => rustre_symbols::SymbolSource::Inferred,
            "import" => rustre_symbols::SymbolSource::Import,
            "export" => rustre_symbols::SymbolSource::Export,
            "elf" => rustre_symbols::SymbolSource::Elf,
            "pe" => rustre_symbols::SymbolSource::Pe,
            "ai" => rustre_symbols::SymbolSource::Ai,
            other => return Err(McpError::InvalidParams(format!("unknown source '{other}'"))),
        };
        Ok(ToolResult::text(json!({
            "source": src.to_string(),
            "priority": src.priority(),
            "backend": "rustre_symbols::SymbolSource::priority",
        }).to_string()))
    }
}

