#[async_trait]
impl ToolHandler for PeToolsRichHeaderParseTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let data = args_to_bytes(&args)?;
        let parsed = rustre_pe_tools::RichHeader::parse(&data);
        let out = match parsed {
            Some(rh) => json!({
                "present": true,
                "xor_key": rh.xor_key,
                "entry_count": rh.entries.len(),
                "entries": rh.entries,
                "source": "rustre_pe_tools::RichHeader::parse",
            }),
            None => json!({
                "present": false,
                "source": "rustre_pe_tools::RichHeader::parse",
            }),
        };
        Ok(ToolResult::text(out.to_string()))
    }
}

