impl PeRebuildIsMemoryPeTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "pe_rebuild_is_memory_pe".to_string(),
            description: "Return true if hex-encoded bytes look like a PE image (MZ magic).".to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["hex"],
                "properties": { "hex": { "type": "string" } }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for PeRebuildIsMemoryPeTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let hex = args.get("hex").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'hex'".into()))?;
        let bytes: Vec<u8> = (0..hex.len()).step_by(2)
            .filter_map(|i| hex.get(i..i+2).and_then(|s| u8::from_str_radix(s, 16).ok()))
            .collect();
        let is_pe = rustre_pe_rebuild::is_memory_pe(&bytes);
        Ok(ToolResult::text(json!({ "is_memory_pe": is_pe, "bytes": bytes.len() }).to_string()))
    }
}

