/// Detect opaque predicates in a byte slice.

impl MhcdeOpaquePredicateDetectTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "mhcde_opaque_predicate_detect".to_string(),
            description: "Detect opaque predicate patterns in x86 bytes via rustre_deobf_mhcde::OpaquePredicateDetector.".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "bytes": { "type": "array", "items": { "type": "integer" } },
                    "hex":   { "type": "string" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for MhcdeOpaquePredicateDetectTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let data = args_to_bytes(&args)?;
        let detector = rustre_deobf_mhcde::OpaquePredicateDetector::new();
        let findings = detector.detect(&data);
        Ok(ToolResult::text(json!({
            "count": findings.len(),
            "findings": findings,
            "source": "rustre_deobf_mhcde::OpaquePredicateDetector::detect",
            "input_hex": hex_encode(&data),
        }).to_string()))
    }
}

