// Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ rustre-arch-x86: metadata / registers / calling-conventions Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬

pub(crate) fn ti_parse_ioc_type_v2(s: &str) -> Result<rustre_threatintel::IocType, McpError> {
    match s.to_ascii_lowercase().as_str() {
        "md5" => Ok(rustre_threatintel::IocType::Md5),
        "sha1" | "sha-1" => Ok(rustre_threatintel::IocType::Sha1),
        "sha256" | "sha-256" => Ok(rustre_threatintel::IocType::Sha256),
        "sha512" | "sha-512" => Ok(rustre_threatintel::IocType::Sha512),
        "ip" => Ok(rustre_threatintel::IocType::Ip),
        "domain" => Ok(rustre_threatintel::IocType::Domain),
        "url" => Ok(rustre_threatintel::IocType::Url),
        "email" => Ok(rustre_threatintel::IocType::Email),
        "registry" => Ok(rustre_threatintel::IocType::Registry),
        "filename" => Ok(rustre_threatintel::IocType::Filename),
        "mutex" => Ok(rustre_threatintel::IocType::Mutex),
        "yara" => Ok(rustre_threatintel::IocType::Yara),
        _ => Err(McpError::InvalidParams(format!("unknown ioc_type '{s}'"))),
    }
}

pub(crate) fn x86_arch_for_bits(bits: u64) -> Result<rustre_arch_x86::X86Arch, McpError> {
    match bits {
        16 => Ok(rustre_arch_x86::X86Arch::new_16bit()),
        32 => Ok(rustre_arch_x86::X86Arch::new_32bit()),
        64 => Ok(rustre_arch_x86::X86Arch::new_64bit()),
        _ => Err(McpError::InvalidParams("bits must be 16, 32, or 64".into())),
    }
}

