/// Count IoC-typed attributes in a synthesized MISP event.

impl TiMispEventIocCountTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "ti_misp_event_ioc_count".to_string(),
            description: "Build a MispEventFull, add attributes of the given MISP types, and \
                          return ioc_count() plus has_ids_attributes()."
                .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "info": { "type": "string" },
                    "attr_types": { "type": "array", "items": { "type": "string" } }
                },
                "required": ["attr_types"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for TiMispEventIocCountTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let info = args.get("info").and_then(Value::as_str).unwrap_or("event").to_string();
        let types = args.get("attr_types").and_then(Value::as_array)
            .ok_or_else(|| McpError::InvalidParams("missing 'attr_types'".into()))?;
        let mut ev = rustre_ti_misp::MispEventFull::new(info);
        for (i, t) in types.iter().enumerate() {
            let ts = t.as_str().unwrap_or("").to_string();
            ev.add_attribute(rustre_ti_misp::MispAttributeFull::new(
                (i as u64) + 1,
                ts,
                format!("v{i}"),
            ));
        }
        Ok(ToolResult::text(
            json!({
                "attribute_count": ev.attributes.len(),
                "ioc_count": ev.ioc_count(),
                "has_ids_attributes": ev.has_ids_attributes(),
                "source": "rustre_ti_misp::MispEventFull",
            })
            .to_string(),
        ))
    }
}

// Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ ti-misp Ã¢â‚¬â€ MispSharingGroup constructor Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬

/// Build a MISP sharing group and add orgs.

impl TiMispSharingGroupNewTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "ti_misp_sharing_group_new".to_string(),
            description: "Construct a MispSharingGroup via ::new and add N mock orgs; return counts."
                .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "id":       { "type": "integer" },
                    "name":     { "type": "string" },
                    "org_count":{ "type": "integer" }
                },
                "required": ["id", "name"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for TiMispSharingGroupNewTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let id = args.get("id").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'id'".into()))?;
        let name = args.get("name").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'name'".into()))?;
        let org_count = args.get("org_count").and_then(Value::as_u64).unwrap_or(0);
        let mut sg = rustre_ti_misp::MispSharingGroup::new(id, name.to_string());
        for i in 0..org_count {
            sg.add_org(rustre_ti_misp::MispOrg::new(
                i + 1,
                format!("Org {i}"),
                format!("uuid-{i}"),
            ));
        }
        Ok(ToolResult::text(
            json!({
                "id": sg.id,
                "name": sg.name,
                "active": sg.active,
                "organisations": sg.organisations.len(),
                "source": "rustre_ti_misp::MispSharingGroup",
            })
            .to_string(),
        ))
    }
}

// Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ crypto-id: binary crypto-constant scanners Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬

/// Scan a byte buffer for all known crypto constants.

impl CryptoIdScanBinaryConstantsTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "crypto_id_scan_binary_constants".to_string(),
            description:
                "Scan raw bytes for all known crypto constants (AES S-box, SHA/MD5 IVs, \
                 CRC32 table, ChaCha20 magic, Blowfish P, bcrypt magic, Camellia sigma, \
                 DES S-box). Returns hits sorted by offset."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "bytes": { "type": "array", "items": { "type": "integer" } },
                    "hex":   { "type": "string" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for CryptoIdScanBinaryConstantsTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let data = args_to_bytes(&args)?;
        let hits = rustre_crypto_id::scan_binary_for_crypto_constants(&data);
        let arr: Vec<Value> = hits
            .iter()
            .map(|h| {
                json!({
                    "algorithm": h.algorithm,
                    "constant_name": h.constant_name,
                    "offset": h.offset,
                    "confidence": h.confidence,
                    "match_length": h.match_length,
                })
            })
            .collect();
        Ok(ToolResult::text(
            json!({
                "count": arr.len(),
                "hits": arr,
                "bytes_scanned": data.len(),
            })
            .to_string(),
        ))
    }
}

/// Scan and summarise crypto constants: full hits plus per-algorithm counts.

impl CryptoIdScanAndSummarizeTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "crypto_id_scan_and_summarize".to_string(),
            description:
                "Run the full binary crypto-constant scan and return both the hit list \
                 and a per-algorithm count summary."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "bytes": { "type": "array", "items": { "type": "integer" } },
                    "hex":   { "type": "string" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for CryptoIdScanAndSummarizeTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let data = args_to_bytes(&args)?;
        let summary = rustre_crypto_id::scan_and_summarize(&data);
        let per_algo: serde_json::Map<String, Value> = summary
            .per_algorithm
            .iter()
            .map(|(k, v)| (k.clone(), json!(v)))
            .collect();
        let hits: Vec<Value> = summary
            .hits
            .iter()
            .map(|h| {
                json!({
                    "algorithm": h.algorithm,
                    "constant_name": h.constant_name,
                    "offset": h.offset,
                    "confidence": h.confidence,
                    "match_length": h.match_length,
                })
            })
            .collect();
        Ok(ToolResult::text(
            json!({
                "total_hits": summary.total_hits,
                "per_algorithm": per_algo,
                "hits": hits,
                "bytes_scanned": data.len(),
            })
            .to_string(),
        ))
    }
}

