/// Expose `rustre_ti_malpedia::malpedia_sample_finder::batch_lookup` as an MCP tool.

impl MalpediaBatchLookupTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "malpedia_batch_lookup".to_string(),
            description: "Batch-look up sample hashes against the mock Malpedia sample finder.".to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["hashes"],
                "properties": {
                    "hashes": {
                        "type": "array",
                        "items": { "type": "string" },
                        "description": "Hashes (SHA-256/SHA-1/MD5) to look up"
                    }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for MalpediaBatchLookupTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let hashes: Vec<String> = args.get("hashes")
            .and_then(Value::as_array)
            .ok_or_else(|| McpError::InvalidParams("missing 'hashes'".into()))?
            .iter()
            .filter_map(|v| v.as_str().map(std::string::ToString::to_string))
            .collect();
        let refs: Vec<&str> = hashes.iter().map(String::as_str).collect();
        let finder = rustre_ti_malpedia::malpedia_sample_finder::MalpediaSampleFinder::with_mock_data();
        let result = rustre_ti_malpedia::malpedia_sample_finder::batch_lookup(&finder, &refs);
        let payload = serde_json::to_value(&result)
            .map_err(|e| McpError::InternalError(format!("serialize failed: {e}")))?;
        Ok(ToolResult::text(payload.to_string()))
    }
}

