/// Batch-demangle a list of mangled symbols.

impl DemangleBatchTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "demangle_batch".to_string(),
            description:
                "Demangle a batch of mangled symbols, auto-detecting ABI for each \
                 (delegates to rustre_demangle::batch_demangle)."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "symbols": { "type": "array", "items": { "type": "string" } }
                },
                "required": ["symbols"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for DemangleBatchTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let syms_val = args
            .get("symbols")
            .and_then(Value::as_array)
            .ok_or_else(|| McpError::InvalidParams("missing 'symbols' array".to_string()))?;
        let symbols: Vec<String> = syms_val
            .iter()
            .filter_map(|v| v.as_str().map(std::string::ToString::to_string))
            .collect();
        let results = rustre_demangle::batch_demangle(&symbols);
        let items: Vec<Value> = results
            .into_iter()
            .map(|r| {
                json!({
                    "mangled": r.mangled,
                    "demangled": r.demangled,
                })
            })
            .collect();
        Ok(ToolResult::text(
            json!({
                "count": symbols.len(),
                "results": items,
                "source": "rustre_demangle::batch_demangle",
            })
            .to_string(),
        ))
    }
}

