/// Report whether `rustre_db::base_migrations()` versions form a contiguous ascending sequence.

impl DbBaseMigrationsIsContiguousTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "db_base_migrations_is_contiguous".to_string(),
            description:
                "Return whether the sorted `version` numbers of canonical base-schema \
                 migrations form a contiguous ascending sequence with step 1, plus the \
                 first gap (if any)."
                    .to_string(),
            input_schema: json!({ "type": "object", "properties": {} }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for DbBaseMigrationsIsContiguousTool {
    async fn call(&self, _args: Value) -> Result<ToolResult, McpError> {
        let migs = rustre_db::base_migrations();
        let mut versions: Vec<u32> = migs.iter().map(|m| m.version.0).collect();
        versions.sort_unstable();
        let mut contiguous = true;
        let mut first_gap: Option<(u32, u32)> = None;
        for w in versions.windows(2) {
            if w[1] != w[0].saturating_add(1) {
                contiguous = false;
                first_gap = Some((w[0], w[1]));
                break;
            }
        }
        Ok(ToolResult::text(
            json!({
                "count":      versions.len(),
                "contiguous": contiguous,
                "first_gap":  first_gap.map(|(a, b)| json!({ "after": a, "before": b })),
                "source":     "rustre_db::base_migrations",
            })
            .to_string(),
        ))
    }
}

