// â”€â”€â”€ patch_binary_diff â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

/// Expose `rustre_patch::diff` as an MCP tool.

impl PatchBinaryDiffTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "patch_binary_diff".to_string(),
            description:
                "Compute a binary delta between old and new byte buffers \
                 (hex-encoded) and return the encoded delta blob as hex."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["old_hex", "new_hex"],
                "properties": {
                    "old_hex": { "type": "string", "description": "Hex-encoded old buffer" },
                    "new_hex": { "type": "string", "description": "Hex-encoded new buffer" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for PatchBinaryDiffTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let old_hex = args.get("old_hex").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'old_hex'".into()))?;
        let new_hex = args.get("new_hex").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'new_hex'".into()))?;
        let old = rustre_patch::parse_hex_bytes(old_hex)
            .map_err(|e| McpError::InvalidParams(format!("old_hex: {e}")))?;
        let new = rustre_patch::parse_hex_bytes(new_hex)
            .map_err(|e| McpError::InvalidParams(format!("new_hex: {e}")))?;
        let delta = rustre_patch::diff(&old, &new);
        Ok(ToolResult::text(
            json!({
                "old_len":   old.len(),
                "new_len":   new.len(),
                "delta_len": delta.len(),
                "delta_hex": hex_encode(&delta),
                "source":    "rustre_patch::diff",
            })
            .to_string(),
        ))
    }
}

