/// Expose `rustre_patch::patch` as an MCP tool.

impl PatchBinaryPatchTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "patch_binary_patch".to_string(),
            description:
                "Decode a binary delta blob and apply it to an old buffer, \
                 returning the reconstructed buffer as hex."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["old_hex", "delta_hex"],
                "properties": {
                    "old_hex":   { "type": "string", "description": "Hex-encoded old buffer" },
                    "delta_hex": { "type": "string", "description": "Hex-encoded delta blob" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for PatchBinaryPatchTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let old_hex = args.get("old_hex").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'old_hex'".into()))?;
        let delta_hex = args.get("delta_hex").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'delta_hex'".into()))?;
        let old = rustre_patch::parse_hex_bytes(old_hex)
            .map_err(|e| McpError::InvalidParams(format!("old_hex: {e}")))?;
        let delta = rustre_patch::parse_hex_bytes(delta_hex)
            .map_err(|e| McpError::InvalidParams(format!("delta_hex: {e}")))?;
        let new = rustre_patch::patch(&old, &delta)
            .map_err(|e| McpError::InternalError(format!("patch: {e}")))?;
        Ok(ToolResult::text(
            json!({
                "old_len": old.len(),
                "new_len": new.len(),
                "new_hex": hex_encode(&new),
                "source":  "rustre_patch::patch",
            })
            .to_string(),
        ))
    }
}

