/// Convert a hex string to raw bytes via `rustre_script::builtin_hex_to_bytes`.

impl ScriptHexToBytesTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "script_hex_to_bytes".to_string(),
            description:
                "Decode a hex string (with or without `0x` prefix) into raw bytes \
                 using the rustre-script builtin `hex_to_bytes`."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["hex"],
                "properties": {
                    "hex": { "type": "string", "description": "Hex-encoded byte string" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for ScriptHexToBytesTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let hex = args
            .get("hex")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'hex'".into()))?;
        let sv = rustre_script::builtin_hex_to_bytes(&[
            rustre_script::ScriptValue::String(hex.to_string()),
        ])
        .map_err(|e| McpError::InvalidParams(e.to_string()))?;
        let bytes = match sv {
            rustre_script::ScriptValue::Bytes(b) => b,
            other => {
                return Err(McpError::InternalError(format!(
                    "hex_to_bytes returned non-bytes: {}",
                    other.type_name()
                )));
            }
        };
        Ok(ToolResult::text(
            json!({
                "bytes": bytes,
                "hex":   hex_encode(&bytes),
                "len":   bytes.len(),
                "source": "rustre_script::builtin_hex_to_bytes",
            })
            .to_string(),
        ))
    }
}

