impl TtdReplayerBuildSyscallSummariesTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "ttd_replayer_build_syscall_summaries".to_string(),
            description: "Build per-syscall aggregate summaries over a synthetic trace of n events via rustre_ttd_replayer::build_syscall_summaries."
                .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "n": {"type": "integer", "description": "Number of synthetic syscall entry/exit pairs (default 8)"}
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for TtdReplayerBuildSyscallSummariesTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        use rustre_ttd_replayer::{TraceBuilder, MemWriteRecord, DEFAULT_SNAPSHOT_INTERVAL, build_syscall_summaries};
        let n = args.get("n").and_then(Value::as_u64).unwrap_or(8);
        let mut b = TraceBuilder::new(DEFAULT_SNAPSHOT_INTERVAL);
        for i in 0..n {
            b.syscall_entry(i, [0; 6]);
            b.syscall_exit(0, vec![MemWriteRecord::new(0x1000 + i * 8, vec![0u8; 8])]);
        }
        let trace = b.build();
        let map = build_syscall_summaries(&trace);
        Ok(ToolResult::text(
            json!({
                "syscall_count": map.len(),
                "total_bytes_written": map.values().map(|s| s.total_bytes_written).sum::<usize>(),
                "source": "rustre_ttd_replayer::build_syscall_summaries",
            })
            .to_string(),
        ))
    }
}

impl TtdReplayerScanForWritesTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "ttd_replayer_scan_for_writes".to_string(),
            description: "Scan a synthetic trace for writes overlapping [addr, addr+size) via rustre_ttd_replayer::scan_for_writes."
                .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "addr": {"type": "integer", "description": "Base address to watch"},
                    "size": {"type": "integer", "description": "Watch range size in bytes"},
                    "n": {"type": "integer", "description": "Number of synthetic events (default 8)"}
                },
                "required": ["addr", "size"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for TtdReplayerScanForWritesTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        use rustre_ttd_replayer::{TraceBuilder, MemWriteRecord, DEFAULT_SNAPSHOT_INTERVAL, scan_for_writes};
        let addr = args.get("addr").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'addr'".into()))?;
        let size = args.get("size").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'size'".into()))? as usize;
        let n = args.get("n").and_then(Value::as_u64).unwrap_or(8);
        let mut b = TraceBuilder::new(DEFAULT_SNAPSHOT_INTERVAL);
        for i in 0..n {
            b.syscall_entry(1, [0; 6]);
            b.syscall_exit(0, vec![MemWriteRecord::new(addr + i * 4, vec![0xAAu8; 4])]);
        }
        let trace = b.build();
        let hits = scan_for_writes(&trace, addr, size);
        Ok(ToolResult::text(
            json!({
                "hit_count": hits.len(),
                "first_tick": hits.first().map(|h| h.tick),
                "last_tick": hits.last().map(|h| h.tick),
                "source": "rustre_ttd_replayer::scan_for_writes",
            })
            .to_string(),
        ))
    }
}

