impl TtdPositionEarliestTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "ttd_position_earliest".to_string(),
            description: "Return the earliest TTD position from a list via rustre_ttd::ttd_position::earliest."
                .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "positions": {
                        "type": "array",
                        "items": {
                            "type": "object",
                            "properties": {
                                "sequence": {"type": "integer"},
                                "step": {"type": "integer"}
                            },
                            "required": ["sequence", "step"]
                        }
                    }
                },
                "required": ["positions"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for TtdPositionEarliestTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let arr = args.get("positions").and_then(Value::as_array)
            .ok_or_else(|| McpError::InvalidParams("missing 'positions'".into()))?;
        let mut positions: Vec<rustre_ttd::ttd_position::TtdPosition> = Vec::with_capacity(arr.len());
        for v in arr {
            let seq = v.get("sequence").and_then(Value::as_u64)
                .ok_or_else(|| McpError::InvalidParams("missing 'sequence'".into()))?;
            let step = v.get("step").and_then(Value::as_u64)
                .ok_or_else(|| McpError::InvalidParams("missing 'step'".into()))? as u32;
            positions.push(rustre_ttd::ttd_position::TtdPosition::new(seq, step));
        }
        let found = rustre_ttd::ttd_position::earliest(&positions);
        Ok(ToolResult::text(
            json!({
                "found": found.is_some(),
                "sequence": found.map(|p| p.sequence),
                "step": found.map(|p| p.step),
                "source": "rustre_ttd::ttd_position::earliest",
            })
            .to_string(),
        ))
    }
}

// â”€â”€â”€ triage_entropy_report_path â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

/// Generate a comprehensive `EntropyReport` for a file at `path`.

impl TriageEntropyReportPathTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "triage_entropy_report_path".to_string(),
            description: "Generate a comprehensive EntropyReport (overall entropy, category, packing indicators, per-block entropy, histogram) for a file at `path`.".to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["path"],
                "properties": {
                    "path": { "type": "string" },
                    "block_size": { "type": "integer", "minimum": 1 }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for TriageEntropyReportPathTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let path = args.get("path").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'path'".into()))?;
        let data = std::fs::read(path)
            .map_err(|e| McpError::InternalError(format!("read {path}: {e}")))?;
        let report = match args.get("block_size").and_then(Value::as_u64) {
            Some(bs) => rustre_triage_entropy::EntropyReport::generate_with_block_size(&data, bs as usize),
            None => rustre_triage_entropy::EntropyReport::generate(&data),
        };
        Ok(ToolResult::text(json!({
            "path": path, "size": data.len(), "report": report,
        }).to_string()))
    }
}

// â”€â”€â”€ triage_entropy_histogram_path â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

/// Compute the byte histogram + chi-square randomness statistic for a file.

impl TriageEntropyHistogramPathTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "triage_entropy_histogram_path".to_string(),
            description: "Compute ByteHistogram (256-bin frequencies, chi-square statistic, likely-random flag, top-N common bytes) for a file at `path`.".to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["path"],
                "properties": {
                    "path": { "type": "string" },
                    "top_n": { "type": "integer", "minimum": 1 }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for TriageEntropyHistogramPathTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let path = args.get("path").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'path'".into()))?;
        let top_n = args.get("top_n").and_then(Value::as_u64).unwrap_or(16) as usize;
        let data = std::fs::read(path)
            .map_err(|e| McpError::InternalError(format!("read {path}: {e}")))?;
        let hist = rustre_triage_entropy::ByteHistogram::new(&data);
        let chi2 = hist.chi_square_statistic();
        let likely_random = hist.is_likely_random();
        let top: Vec<serde_json::Value> = hist.most_common_bytes(top_n).into_iter()
            .map(|(b, c)| json!({ "byte": b, "count": c })).collect();
        Ok(ToolResult::text(json!({
            "path": path, "size": data.len(),
            "total": hist.total, "chi_square": chi2,
            "likely_random": likely_random, "top": top,
        }).to_string()))
    }
}

