impl DecompilerDetectFunctionsTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "decompiler_detect_functions".to_string(),
            description:
                "Enumerate function boundaries in a binary using prologue scan + \
                 call-target collection. Returns start VAs with optional end/name."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["binary_path"],
                "properties": {
                    "binary_path": { "type": "string" },
                    "limit":       { "type": "integer" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for DecompilerDetectFunctionsTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let binary_path = args
            .get("binary_path")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'binary_path'".into()))?;
        let limit = args
            .get("limit")
            .and_then(Value::as_u64)
            .map(|n| n as usize);
        let load = rustre_decompiler::load_binary(std::path::Path::new(binary_path))
            .map_err(|e| McpError::InternalError(format!("load_binary failed: {e}")))?;
        let boundaries = rustre_decompiler::detect_functions_in_load(&load);
        let total = boundaries.len();
        let iter: Box<dyn Iterator<Item = _>> = match limit {
            Some(n) => Box::new(boundaries.into_iter().take(n)),
            None => Box::new(boundaries.into_iter()),
        };
        let items: Vec<Value> = iter
            .map(|b| {
                json!({
                    "start": b.start.as_u64(),
                    "end":   b.end.map(|a| a.as_u64()),
                    "name":  b.name,
                    "confidence": format!("{:?}", b.confidence),
                    "source":     format!("{:?}", b.source),
                })
            })
            .collect();
        Ok(ToolResult::text(
            json!({
                "binary_path": binary_path,
                "total": total,
                "returned": items.len(),
                "functions": items,
            })
            .to_string(),
        ))
    }
}

impl DecompilerDisassembleFunctionX86Tool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "decompiler_disassemble_function_x86".to_string(),
            description:
                "Disassemble one function from an x86/x64 binary at a given VA. \
                 Stops at first RET, invalid encoding, or the byte/instruction cap."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["binary_path", "addr"],
                "properties": {
                    "binary_path": { "type": "string" },
                    "addr":        { "type": "integer" },
                    "max_bytes":   { "type": "integer" },
                    "max_instr":   { "type": "integer" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for DecompilerDisassembleFunctionX86Tool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let binary_path = args
            .get("binary_path")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'binary_path'".into()))?;
        let addr = args
            .get("addr")
            .and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'addr'".into()))?;
        let max_bytes = args
            .get("max_bytes")
            .and_then(Value::as_u64)
            .map_or(65536usize, |n| n as usize);
        let max_instr = args
            .get("max_instr")
            .and_then(Value::as_u64)
            .map_or(10_000usize, |n| n as usize);

        let load = rustre_decompiler::load_binary(std::path::Path::new(binary_path))
            .map_err(|e| McpError::InternalError(format!("load_binary failed: {e}")))?;
        let (base_va, slice) = rustre_decompiler::slice_at_va(&load, addr)
            .ok_or_else(|| McpError::InternalError(format!("addr {addr:#x} not mapped")))?;
        let bits: u8 = if load.bits == 32 { 32 } else if load.bits == 16 { 16 } else { 64 };
        let insns = rustre_decompiler::binary_entry::disassemble_function_x86(slice, base_va, bits, max_bytes, max_instr)
            .map_err(|e| McpError::InternalError(format!("disasm failed: {e}")))?;

        let items: Vec<Value> = insns
            .iter()
            .map(|i| {
                json!({
                    "addr":     i.address.as_u64(),
                    "mnemonic": i.mnemonic,
                    "operands": i.operands,
                    "size":     i.bytes.len(),
                })
            })
            .collect();

        Ok(ToolResult::text(
            json!({
                "binary_path": binary_path,
                "addr":        addr,
                "bits":        bits,
                "count":       items.len(),
                "instructions": items,
            })
            .to_string(),
        ))
    }
}

