/// Expose `rustre_analysis_vsa::resolve_jump_table` as an MCP tool.

impl AnalysisVsaResolveJumpTableTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "analysis_vsa_resolve_jump_table".to_string(),
            description: "Resolve an indirect-jump table via VSA.".to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["table_base", "entry_size", "code_base", "code_limit"],
                "properties": {
                    "table_base": { "type": "integer" },
                    "entry_size": { "type": "integer" },
                    "code_base": { "type": "integer" },
                    "code_limit": { "type": "integer" },
                    "entries": { "type": "array", "items": { "type": "integer" } }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for AnalysisVsaResolveJumpTableTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let table_base = args.get("table_base").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'table_base'".into()))?;
        let entry_size = u8::try_from(args.get("entry_size").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'entry_size'".into()))?)
            .map_err(|_| McpError::InvalidParams("entry_size out of range".into()))?;
        let code_base = args.get("code_base").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'code_base'".into()))?;
        let code_limit = args.get("code_limit").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'code_limit'".into()))?;
        let entries: Vec<u64> = args.get("entries").and_then(Value::as_array)
            .map(|a| a.iter().filter_map(Value::as_u64).collect()).unwrap_or_default();
        let mut map = std::collections::HashMap::new();
        for (k, target) in entries.iter().enumerate() {
            let addr = table_base + (k as u64) * u64::from(entry_size);
            let bytes = target.to_le_bytes();
            let n = usize::from(entry_size).min(8);
            for i in 0..n { map.insert(addr + i as u64, bytes[i]); }
        }
        let mem = rustre_analysis_vsa::MapBinaryMemory(map);
        let vsa = rustre_analysis_vsa::VsaEngineResult {
            states_before: std::collections::HashMap::new(),
            states_after: std::collections::HashMap::new(),
            converged: true,
            iterations: 0,
        };
        let info = rustre_analysis_vsa::resolve_jump_table(
            &vsa, 0, "idx", table_base, entry_size, (code_base, code_limit), &mem,
        );
        Ok(ToolResult::text(json!({
            "table_base": info.table_base,
            "entry_size": info.entry_size,
            "targets": info.targets,
            "complete": info.complete
        }).to_string()))
    }
}

