/// Scan a raw binary blob for C++ vtable candidates.

impl VtableScanBinaryTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "vtable_scan_binary".to_string(),
            description: "Scan a raw binary blob for vtable candidates via \
                          rustre_analysis_vtable::VtableScanner::scan_binary.".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "data": { "type": "array", "items": { "type": "integer" } },
                    "hex": { "type": "string" },
                    "base": { "type": "integer" },
                    "bits": { "type": "integer" }
                },
                "required": ["base", "bits"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for VtableScanBinaryTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let data = extract_byte_array(&args, "data", "hex")?;
        let base = args.get("base").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'base'".to_string()))?;
        let bits = args.get("bits").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'bits'".to_string()))?;
        let bits_u32 = u32::try_from(bits)
            .map_err(|_| McpError::InvalidParams("bits out of range".to_string()))?;
        let candidates = rustre_analysis_vtable::VtableScanner::scan_binary(&data, base, bits_u32);
        Ok(ToolResult::text(json!({
            "count": candidates.len(),
            "candidates": candidates,
            "source": "rustre_analysis_vtable::VtableScanner::scan_binary",
        }).to_string()))
    }
}

