#[async_trait]
impl ToolHandler for ForensicsFsPrefetchParseTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let data = read_path_bytes_forensics(&args)?;
        let pf = rustre_forensics_fs::prefetch_analyzer::PrefetchFile::parse(&data)
            .map_err(|e| McpError::InvalidParams(format!("prefetch parse: {e}")))?;
        let modules = pf.loaded_modules().into_iter().map(str::to_string).collect::<Vec<_>>();
        Ok(ToolResult::text(json!({
            "executable": pf.header.exe_name,
            "run_count": pf.run_count,
            "hash": format!("0x{:08x}", pf.header.prefetch_hash),
            "loaded_modules": modules,
            "source": "rustre_forensics_fs::prefetch_analyzer::PrefetchFile::parse",
        }).to_string()))
    }
}

