/// Concatenate two byte buffers via `rustre_script::builtin_bytes_concat`.

impl ScriptBytesConcatTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "script_bytes_concat".to_string(),
            description: "Concatenate two byte buffers via rustre-script builtin `bytes_concat`.".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "a":     { "type": "array", "items": { "type": "integer" } },
                    "a_hex": { "type": "string" },
                    "b":     { "type": "array", "items": { "type": "integer" } },
                    "b_hex": { "type": "string" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for ScriptBytesConcatTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let a = extract_byte_array(&args, "a", "a_hex")?;
        let b = extract_byte_array(&args, "b", "b_hex")?;
        let sv = rustre_script::builtin_bytes_concat(&[
            rustre_script::ScriptValue::Bytes(a),
            rustre_script::ScriptValue::Bytes(b),
        ])
        .map_err(|e| McpError::InvalidParams(e.to_string()))?;
        let out = match sv {
            rustre_script::ScriptValue::Bytes(v) => v,
            other => return Err(McpError::InternalError(format!("bytes_concat returned non-bytes: {}", other.type_name()))),
        };
        Ok(ToolResult::text(json!({
            "bytes": out,
            "hex":   hex_encode(&out),
            "len":   out.len(),
            "source": "rustre_script::builtin_bytes_concat",
        }).to_string()))
    }
}

/// Slice a byte buffer via `rustre_script::builtin_bytes_slice`.

impl ScriptBytesSliceTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "script_bytes_slice".to_string(),
            description: "Slice a byte buffer [start, end) via rustre-script builtin `bytes_slice`.".to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["start", "end"],
                "properties": {
                    "bytes":     { "type": "array", "items": { "type": "integer" } },
                    "bytes_hex": { "type": "string" },
                    "start":     { "type": "integer" },
                    "end":       { "type": "integer" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for ScriptBytesSliceTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let data = extract_byte_array(&args, "bytes", "bytes_hex")?;
        let start = args.get("start").and_then(Value::as_i64)
            .ok_or_else(|| McpError::InvalidParams("missing 'start'".into()))?;
        let end = args.get("end").and_then(Value::as_i64)
            .ok_or_else(|| McpError::InvalidParams("missing 'end'".into()))?;
        let sv = rustre_script::builtin_bytes_slice(&[
            rustre_script::ScriptValue::Bytes(data),
            rustre_script::ScriptValue::Int(start),
            rustre_script::ScriptValue::Int(end),
        ])
        .map_err(|e| McpError::InvalidParams(e.to_string()))?;
        let out = match sv {
            rustre_script::ScriptValue::Bytes(v) => v,
            other => return Err(McpError::InternalError(format!("bytes_slice returned non-bytes: {}", other.type_name()))),
        };
        Ok(ToolResult::text(json!({
            "bytes": out,
            "hex":   hex_encode(&out),
            "len":   out.len(),
            "source": "rustre_script::builtin_bytes_slice",
        }).to_string()))
    }
}

/// Find a needle inside a haystack via `rustre_script::builtin_bytes_find`.

impl ScriptBytesFindTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "script_bytes_find".to_string(),
            description: "Find first offset of `needle` in `haystack` via rustre-script builtin `bytes_find`.".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "haystack":     { "type": "array", "items": { "type": "integer" } },
                    "haystack_hex": { "type": "string" },
                    "needle":       { "type": "array", "items": { "type": "integer" } },
                    "needle_hex":   { "type": "string" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for ScriptBytesFindTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let haystack = extract_byte_array(&args, "haystack", "haystack_hex")?;
        let needle = extract_byte_array(&args, "needle", "needle_hex")?;
        let haystack_len = haystack.len();
        let needle_len = needle.len();
        let sv = rustre_script::builtin_bytes_find(&[
            rustre_script::ScriptValue::Bytes(haystack),
            rustre_script::ScriptValue::Bytes(needle),
        ])
        .map_err(|e| McpError::InvalidParams(e.to_string()))?;
        let (found, offset) = match sv {
            rustre_script::ScriptValue::Int(i) => (true, Some(i)),
            rustre_script::ScriptValue::Null => (false, None),
            other => return Err(McpError::InternalError(format!("bytes_find returned unexpected: {}", other.type_name()))),
        };
        Ok(ToolResult::text(json!({
            "found":        found,
            "offset":       offset,
            "haystack_len": haystack_len,
            "needle_len":   needle_len,
            "source": "rustre_script::builtin_bytes_find",
        }).to_string()))
    }
}

