#[async_trait]
impl ToolHandler for AgentBuiltinWorkflowsTool {
    async fn call(&self, _args: Value) -> Result<ToolResult, McpError> {
        let workflows = rustre_agent::builtin_workflows();
        let agents: Vec<Value> = workflows
            .iter()
            .map(|(agent, _cfg)| {
                let caps: Vec<String> = agent
                    .capabilities()
                    .iter()
                    .map(|c| format!("{c:?}"))
                    .collect();
                json!({
                    "name": agent.name(),
                    "description": agent.description(),
                    "capabilities": caps,
                })
            })
            .collect();
        Ok(ToolResult::text(json!({
            "count": agents.len(),
            "agents": agents,
            "source": "rustre_agent::builtin_workflows",
        }).to_string()))
    }
}

