/// Compute edit distance between two call-stack signatures.

impl FuzzSanStackEditDistanceTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "fuzz_san_stack_edit_distance".to_string(),
            description:
                "Compute Levenshtein edit distance between two call-stack frame sequences via \
                 rustre_fuzz_sanitizers::crash_deduplicator::stack_edit_distance."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "a": { "type": "array", "items": { "type": "string" } },
                    "b": { "type": "array", "items": { "type": "string" } }
                },
                "required": ["a", "b"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for FuzzSanStackEditDistanceTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let to_vec = |k: &str| -> Result<Vec<String>, McpError> {
            args.get(k)
                .and_then(Value::as_array)
                .ok_or_else(|| McpError::InvalidParams(format!("missing '{k}'")))?
                .iter()
                .map(|v| {
                    v.as_str()
                        .map(str::to_owned)
                        .ok_or_else(|| McpError::InvalidParams(format!("'{k}' must be strings")))
                })
                .collect()
        };
        let a = to_vec("a")?;
        let b = to_vec("b")?;
        let distance =
            rustre_fuzz_sanitizers::crash_deduplicator::stack_edit_distance(&a, &b);
        Ok(ToolResult::text(
            json!({
                "distance": distance,
                "a_len": a.len(),
                "b_len": b.len(),
                "source": "rustre_fuzz_sanitizers::crash_deduplicator::stack_edit_distance",
            })
            .to_string(),
        ))
    }
}

