// --- rustre-fuzz-libfuzzer wrappers ----------------------------------------

pub(crate) fn libfuzzer_hex_str_to_bytes(s: &str) -> Result<Vec<u8>, McpError> {
    let s = s.trim();
    if s.len() % 2 != 0 {
        return Err(McpError::InvalidParams("hex length must be even".to_string()));
    }
    let mut out = Vec::with_capacity(s.len() / 2);
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let hi = (bytes[i] as char).to_digit(16)
            .ok_or_else(|| McpError::InvalidParams("invalid hex".to_string()))?;
        let lo = (bytes[i + 1] as char).to_digit(16)
            .ok_or_else(|| McpError::InvalidParams("invalid hex".to_string()))?;
        out.push(((hi << 4) | lo) as u8);
        i += 2;
    }
    Ok(out)
}

