// â”€â”€â”€ rustre-diff-semantic â€” extra wrappers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

fn ds_extract_bytes(args: &Value, hex_key: &str, arr_key: &str) -> Result<Vec<u8>, McpError> {
    if let Some(s) = args.get(hex_key).and_then(Value::as_str) {
        return crate::hex_decode(s);
    }
    if let Some(arr) = args.get(arr_key).and_then(Value::as_array) {
        let mut out = Vec::with_capacity(arr.len());
        for v in arr {
            let n = v.as_u64().ok_or_else(|| McpError::InvalidParams(format!("{arr_key} must be array of u8")))?;
            if n > 255 { return Err(McpError::InvalidParams(format!("{arr_key} byte > 255"))); }
            out.push(n as u8);
        }
        return Ok(out);
    }
    Err(McpError::InvalidParams(format!("missing '{hex_key}' or '{arr_key}'")))
}

/// Weighted similarity score in [0.0,1.0] between two SemanticSignatures computed from raw bytes.

impl DiffSemanticMatcherSimilarityTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "diff_semantic_matcher_similarity".to_string(),
            description: "Compute SemanticMatcher::similarity between two functions given as raw bytes ('hex_a'/'bytes_a' + 'base_a', 'hex_b'/'bytes_b' + 'base_b'). Returns f32 similarity in [0,1].".to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["base_a", "base_b"],
                "properties": {
                    "hex_a": { "type": "string" }, "bytes_a": { "type": "array", "items": { "type": "integer" } }, "base_a": { "type": "integer" },
                    "hex_b": { "type": "string" }, "bytes_b": { "type": "array", "items": { "type": "integer" } }, "base_b": { "type": "integer" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for DiffSemanticMatcherSimilarityTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let bytes_a = ds_extract_bytes(&args, "hex_a", "bytes_a")?;
        let bytes_b = ds_extract_bytes(&args, "hex_b", "bytes_b")?;
        let base_a = args.get("base_a").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'base_a'".into()))?;
        let base_b = args.get("base_b").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'base_b'".into()))?;
        let sig_a = rustre_diff_semantic::SemanticSignature::compute(&bytes_a, base_a);
        let sig_b = rustre_diff_semantic::SemanticSignature::compute(&bytes_b, base_b);
        let sim = rustre_diff_semantic::SemanticMatcher::similarity(&sig_a, &sig_b);
        Ok(ToolResult::text(json!({ "similarity": sim }).to_string()))
    }
}

