// --- pe-rebuild extra: find_pe_candidates / calculate_pe_checksum / infer_characteristics ---

impl PeRebuildFindPeCandidatesTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "pe_rebuild_find_pe_candidates".to_string(),
            description: "Scan hex-encoded dump for PE header candidate offsets via rustre_pe_rebuild::find_pe_candidates.".to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["hex"],
                "properties": { "hex": { "type": "string" } }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for PeRebuildFindPeCandidatesTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let hex = args.get("hex").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'hex'".into()))?;
        let bytes: Vec<u8> = (0..hex.len()).step_by(2)
            .filter_map(|i| hex.get(i..i+2).and_then(|s| u8::from_str_radix(s, 16).ok()))
            .collect();
        let cands = rustre_pe_rebuild::pe_reconstructor::find_pe_candidates(&bytes);
        let count = cands.len();
        Ok(ToolResult::text(json!({
            "candidates": cands,
            "count": count,
            "bytes": bytes.len(),
        }).to_string()))
    }
}

