/// Diff two export tables by name/ordinal.

impl DiffExportsTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "diff_exports".to_string(),
            description:
                "Diff two export tables via rustre_diff::diff_exports. Each entry: {name?, ordinal, address}."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "a": { "type": "array" },
                    "b": { "type": "array" }
                },
                "required": ["a", "b"]
            }),
            parameters: Value::Null,
        }
    }
}

fn parse_export_entries_diff(v: &Value) -> Vec<rustre_diff::ExportEntry> {
    v.as_array()
        .map(|arr| {
            arr.iter()
                .map(|e| rustre_diff::ExportEntry {
                    name: e.get("name").and_then(Value::as_str).map(str::to_string),
                    ordinal: u32::try_from(e.get("ordinal").and_then(Value::as_u64).unwrap_or(0)).unwrap_or(0),
                    address: e.get("address").and_then(Value::as_u64).unwrap_or(0),
                })
                .collect()
        })
        .unwrap_or_default()
}

#[async_trait]
impl ToolHandler for DiffExportsTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let a = parse_export_entries_diff(args.get("a").unwrap_or(&Value::Null));
        let b = parse_export_entries_diff(args.get("b").unwrap_or(&Value::Null));
        let d = rustre_diff::diff_exports(&a, &b);
        let val = serde_json::to_value(&d)
            .map_err(|e| McpError::InternalError(format!("serialize export diff: {e}")))?;
        Ok(ToolResult::text(
            json!({
                "diff": val,
                "source": "rustre_diff::diff_exports",
            })
            .to_string(),
        ))
    }
}

