/// Expose `rustre_patch::patch_xor_region_at_va` as an MCP tool.

impl PatchPatchXorRegionAtVaTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "patch_patch_xor_region_at_va".to_string(),
            description:
                "XOR-encode/decode `length` bytes at `va` with `key` in a PE file on disk via \
                 rustre_patch::patch_xor_region_at_va."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["path", "va", "length", "key_hex"],
                "properties": {
                    "path":    { "type": "string",  "description": "Path to the PE file" },
                    "va":      { "type": "integer", "description": "Virtual address" },
                    "length":  { "type": "integer", "description": "Region length in bytes" },
                    "key_hex": { "type": "string",  "description": "Hex-encoded XOR key" },
                    "dry_run": { "type": "boolean", "description": "If true, do not write file" },
                    "backup":  { "type": "boolean", "description": "If true, create a .bak backup" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for PatchPatchXorRegionAtVaTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let path = args
            .get("path")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'path'".into()))?;
        let va = args
            .get("va")
            .and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'va'".into()))?;
        let length = args
            .get("length")
            .and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'length'".into()))?
            as usize;
        let key_hex = args
            .get("key_hex")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'key_hex'".into()))?;
        let dry_run = args.get("dry_run").and_then(Value::as_bool).unwrap_or(true);
        let backup = args.get("backup").and_then(Value::as_bool).unwrap_or(false);
        let key = rustre_patch::parse_hex_bytes(key_hex)
            .map_err(|e| McpError::InvalidParams(format!("parse_hex_bytes: {e}")))?;
        let outcome = rustre_patch::patch_xor_region_at_va(path, va, length, &key, dry_run, backup)
            .map_err(|e| McpError::InternalError(format!("patch_xor_region_at_va: {e}")))?;
        let val = serde_json::to_value(&outcome)
            .map_err(|e| McpError::InternalError(format!("serialize outcome: {e}")))?;
        Ok(ToolResult::text(
            json!({
                "outcome": val,
                "source":  "rustre_patch::patch_xor_region_at_va",
            })
            .to_string(),
        ))
    }
}

// â”€â”€â”€ patch_build_delta â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

/// Expose `rustre_patch::build_delta` as an MCP tool.

impl PatchBuildDeltaTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "patch_build_delta".to_string(),
            description:
                "Build a BinaryDelta between two hex-encoded byte buffers via \
                 rustre_patch::build_delta using default DiffOptions."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["old_hex", "new_hex"],
                "properties": {
                    "old_hex":   { "type": "string",  "description": "Old buffer, hex-encoded" },
                    "new_hex":   { "type": "string",  "description": "New buffer, hex-encoded" },
                    "min_match": { "type": "integer", "description": "Optional minimum match length" },
                    "window":    { "type": "integer", "description": "Optional sliding window size" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for PatchBuildDeltaTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let old_hex = args
            .get("old_hex")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'old_hex'".into()))?;
        let new_hex = args
            .get("new_hex")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'new_hex'".into()))?;
        let old = rustre_patch::parse_hex_bytes(old_hex)
            .map_err(|e| McpError::InvalidParams(format!("parse_hex_bytes old: {e}")))?;
        let new = rustre_patch::parse_hex_bytes(new_hex)
            .map_err(|e| McpError::InvalidParams(format!("parse_hex_bytes new: {e}")))?;
        let mut opts = rustre_patch::DiffOptions::default();
        if let Some(m) = args.get("min_match").and_then(Value::as_u64) {
            opts.min_match = m as usize;
        }
        if let Some(w) = args.get("window").and_then(Value::as_u64) {
            opts.window = w as usize;
        }
        let delta = rustre_patch::build_delta(&old, &new, &opts);
        let val = serde_json::to_value(&delta)
            .map_err(|e| McpError::InternalError(format!("serialize delta: {e}")))?;
        Ok(ToolResult::text(
            json!({
                "delta":  val,
                "source": "rustre_patch::build_delta",
            })
            .to_string(),
        ))
    }
}

