/// Expose `rustre_flirt_gen::PatternGenerator::generate()` â€” build a single
/// FLIRT pattern from raw bytes, an optional relocation table, and a name.

impl FlirtGenPatternGenerateTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "flirt_gen_pattern_generate".to_string(),
            description:
                "Generate a FLIRT pattern from function bytes (hex-encoded) \
                 and optional [(offset,size)] relocation entries via \
                 rustre_flirt_gen::PatternGenerator::generate."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["bytes_hex", "name"],
                "properties": {
                    "bytes_hex": { "type": "string", "description": "Function bytes, hex-encoded" },
                    "name":      { "type": "string", "description": "Primary function name" },
                    "relocs": {
                        "type":  "array",
                        "items": {
                            "type": "object",
                            "properties": {
                                "offset": { "type": "integer" },
                                "size":   { "type": "integer" }
                            }
                        }
                    }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for FlirtGenPatternGenerateTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let bytes_hex = args
            .get("bytes_hex")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'bytes_hex'".into()))?;
        let name = args
            .get("name")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'name'".into()))?;
        let bytes = crate::hex_decode(bytes_hex)?;

        let mut relocs: Vec<rustre_flirt_gen::RelocationEntry> = Vec::new();
        if let Some(arr) = args.get("relocs").and_then(Value::as_array) {
            for r in arr {
                let offset = r.get("offset").and_then(Value::as_u64).unwrap_or(0);
                let size = r.get("size").and_then(Value::as_u64).unwrap_or(0);
                relocs.push(rustre_flirt_gen::RelocationEntry {
                    offset: u16::try_from(offset).unwrap_or(u16::MAX),
                    size:   u8::try_from(size).unwrap_or(u8::MAX),
                });
            }
        }

        let fname = rustre_flirt::FlirtName {
            name:      name.to_string(),
            offset:    0,
            is_public: true,
            is_local:  false,
        };
        let generator = rustre_flirt_gen::PatternGenerator::new();
        let pat = generator
            .generate(&bytes, &relocs, vec![fname])
            .map_err(|e| McpError::InternalError(format!("generate: {e}")))?;
        Ok(ToolResult::text(
            json!({
                "pattern_hex":    pat.pattern_hex(),
                "crc16":          pat.crc16,
                "crc_length":     pat.crc_length,
                "pattern_length": pat.pattern_length,
                "source":         "rustre_flirt_gen::PatternGenerator::generate",
            })
            .to_string(),
        ))
    }
}

