/// Return imports filtered by DLL name via `PeInfo::imports_from_dll`.

impl LoaderPeImportsFromDllTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "loader_pe_imports_from_dll".to_string(),
            description: "Parse a PE binary and return imports filtered by DLL name (case-insensitive).".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "bytes": { "type": "array", "items": { "type": "integer" } },
                    "hex":   { "type": "string" },
                    "dll":   { "type": "string" }
                },
                "required": ["dll"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for LoaderPeImportsFromDllTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let data = args_to_bytes(&args)?;
        let dll = args.get("dll").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'dll'".to_string()))?;
        let info = rustre_loader_pe::PeInfo::parse(&data)
            .map_err(|e| McpError::InvalidParams(format!("PeInfo::parse: {e}")))?;
        let entries: Vec<Value> = info.imports_from_dll(dll).iter().map(|imp| {
            json!({
                "dll":     imp.dll,
                "name":    imp.name,
                "ordinal": imp.ordinal,
                "address": imp.address,
            })
        }).collect();
        Ok(ToolResult::text(
            json!({
                "dll":     dll,
                "count":   entries.len(),
                "entries": entries,
                "source":  "rustre_loader_pe::PeInfo::imports_from_dll",
            })
            .to_string(),
        ))
    }
}

