/// Expose `rustre_syscalls::signal_name` as an MCP tool.

impl SyscallsSignalNameTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "syscalls_signal_name".to_string(),
            description: "Map a Linux signal number to its symbolic name (e.g. 9 -> SIGKILL).".to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["sig"],
                "properties": {
                    "sig": { "type": "integer", "description": "Signal number" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for SyscallsSignalNameTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let sig = args.get("sig").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'sig'".into()))?;
        let sig_u32 = u32::try_from(sig)
            .map_err(|_| McpError::InvalidParams("sig out of range".into()))?;
        let name = rustre_syscalls::signal_name(sig_u32);
        Ok(ToolResult::text(json!({ "sig": sig_u32, "name": name }).to_string()))
    }
}

