/// Compute per-function coverage stats from a coverage run (v2 wrapper).

impl TraceCoverageComputeFunctionStatsTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "trace_coverage_compute_function_stats_v2".to_string(),
            description:
                "Compute per-function coverage stats. Wraps rustre_trace_coverage::compute_function_stats."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "run_json": { "type": "string" },
                    "functions_json": { "type": "string" }
                },
                "required": ["run_json", "functions_json"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for TraceCoverageComputeFunctionStatsTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let run_json = args
            .get("run_json")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'run_json'".to_string()))?;
        let functions_json = args
            .get("functions_json")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'functions_json'".to_string()))?;
        let run: rustre_trace_coverage::CoverageRun = serde_json::from_str(run_json)
            .map_err(|e| McpError::InvalidParams(format!("run_json: {e}")))?;
        let functions: Vec<rustre_trace_coverage::FunctionStats> =
            serde_json::from_str(functions_json)
                .map_err(|e| McpError::InvalidParams(format!("functions_json: {e}")))?;
        let stats = rustre_trace_coverage::compute_function_stats(&run, &functions);
        Ok(ToolResult::text(
            json!({
                "count": stats.len(),
                "stats": stats,
                "source": "rustre_trace_coverage::compute_function_stats",
            })
            .to_string(),
        ))
    }
}

