/// Compute an API-hash of the given bytes using a supported algorithm.

impl IadlComputeHashTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "iadl_compute_hash".to_string(),
            description:
                "Compute an API hash of `bytes` using the given algorithm \
                 (djb2|fnv1a32|sdbm|crc32|adler32|ror_hash). Wraps rustre_deobf_iadl::compute_hash."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "bytes": { "type": "array", "items": { "type": "integer" } },
                    "hex": { "type": "string" },
                    "algorithm": { "type": "string" }
                },
                "required": ["algorithm"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for IadlComputeHashTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let data = args_to_bytes(&args)?;
        let algo_s = args
            .get("algorithm")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'algorithm'".to_string()))?;
        let algo = match algo_s.to_ascii_lowercase().as_str() {
            "djb2" => rustre_deobf_iadl::HashAlgorithm::Djb2,
            "fnv1a32" => rustre_deobf_iadl::HashAlgorithm::Fnv1a32,
            "sdbm" => rustre_deobf_iadl::HashAlgorithm::Sdbm,
            "crc32" => rustre_deobf_iadl::HashAlgorithm::Crc32,
            "adler32" => rustre_deobf_iadl::HashAlgorithm::Adler32,
            "ror_hash" | "rorhash" | "ror" => rustre_deobf_iadl::HashAlgorithm::RorHash,
            other => {
                return Err(McpError::InvalidParams(format!(
                    "unsupported algorithm: {other}"
                )));
            }
        };
        let hash = rustre_deobf_iadl::compute_hash(&data, algo);
        Ok(ToolResult::text(
            json!({
                "algorithm": algo.name(),
                "input_len": data.len(),
                "hash": hash,
                "hash_hex": format!("{:016x}", hash),
                "source": "rustre_deobf_iadl::compute_hash",
            })
            .to_string(),
        ))
    }
}

// --- rustre-emu arch info wrappers ---------------------------------------

fn parse_emu_arch(s: &str) -> Result<rustre_emu::EmulatorArch, McpError> {
    use rustre_emu::EmulatorArch as A;
    Ok(match s.to_ascii_lowercase().as_str() {
        "x86_16" | "x86-16" => A::X86_16,
        "x86_32" | "x86-32" | "x86" => A::X86_32,
        "x86_64" | "x86-64" | "x64" | "amd64" => A::X86_64,
        "arm" => A::Arm,
        "arm-thumb" | "arm_thumb" | "thumb" => A::ArmThumb,
        "arm64" | "aarch64" => A::Arm64,
        "mips32" => A::Mips32,
        "mips64" => A::Mips64,
        "mips32el" => A::Mips32El,
        "riscv32" => A::RiscV32,
        "riscv64" => A::RiscV64,
        "sparc32" => A::Sparc32,
        "sparc64" => A::Sparc64,
        other => return Err(McpError::InvalidParams(format!("unknown arch: {other}"))),
    })
}

