/// Scan bytes against a set of YARA rules using the pure-Rust engine.

impl YaraEngineScanBytesTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "yara_engine_scan_bytes".to_string(),
            description:
                "Scan bytes against loaded YARA rules using rustre_yara_engine::YaraScanner::scan."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "bytes": { "type": "array", "items": { "type": "integer" } },
                    "hex":   { "type": "string" },
                    "rules": { "type": "string" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for YaraEngineScanBytesTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let data = args_to_bytes(&args)?;
        let rules_src = args
            .get("rules")
            .and_then(Value::as_str)
            .unwrap_or("rule dummy { condition: true }");
        let parser = rustre_yara_engine::YaraParser::new();
        let rules = parser
            .parse_rules(rules_src)
            .map_err(|e| McpError::InvalidParams(format!("yara parse: {e}")))?;
        let scanner = rustre_yara_engine::YaraScanner::new();
        for r in rules {
            scanner.add_rule(r);
        }
        let matches = scanner.scan_names(&data);
        Ok(ToolResult::text(
            json!({
                "matches": matches,
                "bytes": data.len(),
                "source": "rustre_yara_engine::YaraScanner::scan",
            })
            .to_string(),
        ))
    }
}

