/// Look up a meta value on a YARA rule parsed from source.

impl YaraRuleGetMetaTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "yara_rule_get_meta".to_string(),
            description:
                "Parse a YARA rule source and return the value of a `meta:` key \
                 (mirrors rustre_yara::YaraRule::get_meta)."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "source": { "type": "string" },
                    "key":    { "type": "string" }
                },
                "required": ["source", "key"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for YaraRuleGetMetaTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let source = args
            .get("source")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'source'".to_string()))?;
        let key = args
            .get("key")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'key'".to_string()))?;
        let rule = rustre_yara::YaraParser::parse_rule(source)
            .map_err(|e| McpError::InvalidParams(format!("parse error: {e}")))?;
        let value_json = match rule.get_meta(key) {
            Some(rustre_yara::YaraMetaValue::String(s)) => json!({ "type": "string", "value": s }),
            Some(rustre_yara::YaraMetaValue::Integer(i)) => json!({ "type": "integer", "value": i }),
            Some(rustre_yara::YaraMetaValue::Bool(b)) => json!({ "type": "bool", "value": b }),
            None => Value::Null,
        };
        Ok(ToolResult::text(
            json!({
                "rule": rule.name,
                "key": key,
                "value": value_json,
                "source": "rustre_yara::YaraRule::get_meta",
            })
            .to_string(),
        ))
    }
}

