/// Return the mnemonic for a Lua opcode byte for a given Lua version.

impl LuaLoaderOpcodeNameTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "lua_loader_opcode_name".to_string(),
            description:
                "Return the mnemonic for a Lua opcode byte for a given Lua minor version \
                 (51/52/53/54) (mirrors rustre_loader_lua::opcode_name)."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "version": { "type": "integer" },
                    "opcode": { "type": "integer" }
                },
                "required": ["version", "opcode"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for LuaLoaderOpcodeNameTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let version_num = args
            .get("version")
            .and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'version'".to_string()))?;
        let opcode = args
            .get("opcode")
            .and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'opcode'".to_string()))?;
        let version = match version_num {
            51 => rustre_loader_lua::LuaVersion::Lua51,
            52 => rustre_loader_lua::LuaVersion::Lua52,
            53 => rustre_loader_lua::LuaVersion::Lua53,
            54 => rustre_loader_lua::LuaVersion::Lua54,
            other => rustre_loader_lua::LuaVersion::Unknown(other as u8),
        };
        let name = rustre_loader_lua::opcode_name(version, opcode as u8);
        Ok(ToolResult::text(
            json!({
                "version": version_num,
                "opcode": opcode,
                "name": name,
                "source": "rustre_loader_lua::opcode_name",
            })
            .to_string(),
        ))
    }
}

