/// Decode a `MethodDef.Flags` raw u32 via `rustre_dotnet::MethodFlags`.

impl DotnetMethodFlagsDecodeTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "dotnet_method_flags_decode".to_string(),
            description:
                "Decode a raw CLR MethodDef.Flags u32 into access / static / \
                 virtual / abstract / sealed / pinvoke / ctor booleans via \
                 rustre_dotnet::MethodFlags."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "flags": { "type": "integer", "description": "raw MethodDef.Flags" }
                },
                "required": ["flags"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for DotnetMethodFlagsDecodeTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let raw = args
            .get("flags")
            .and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'flags'".to_string()))?;
        let raw_u32 = u32::try_from(raw)
            .map_err(|_| McpError::InvalidParams("flags out of u32 range".to_string()))?;
        let f = rustre_dotnet::MethodFlags::from_raw(raw_u32);
        Ok(ToolResult::text(
            json!({
                "raw": raw_u32,
                "access": f.access_modifier(),
                "is_public": f.is_public(),
                "is_static": f.is_static(),
                "is_virtual": f.is_virtual(),
                "is_abstract": f.is_abstract(),
                "is_sealed": f.is_sealed(),
                "is_special_name": f.is_special_name(),
                "is_rt_special_name": f.is_rt_special_name(),
                "is_pinvoke": f.is_pinvoke(),
                "is_constructor": f.is_constructor(),
                "source": "rustre_dotnet::MethodFlags",
            })
            .to_string(),
        ))
    }
}

/// Build a synthetic no-operand CIL instruction via
/// `rustre_dotnet::CilInstruction::simple` and report its metadata.

impl DotnetCilSimpleInstrTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "dotnet_cil_simple_instr".to_string(),
            description:
                "Construct a no-operand CIL instruction at a given offset and \
                 report its opcode / size / branch / terminator kind via \
                 rustre_dotnet::CilInstruction."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "offset": { "type": "integer" },
                    "opcode": { "type": "string" }
                },
                "required": ["opcode"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for DotnetCilSimpleInstrTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let offset = args.get("offset").and_then(Value::as_u64).unwrap_or(0);
        let offset_u32 = u32::try_from(offset)
            .map_err(|_| McpError::InvalidParams("offset out of u32 range".to_string()))?;
        let opcode = args
            .get("opcode")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'opcode'".to_string()))?;
        let instr = rustre_dotnet::CilInstruction::simple(offset_u32, opcode);
        Ok(ToolResult::text(
            json!({
                "display": instr.to_string(),
                "offset": instr.offset,
                "opcode": instr.opcode,
                "byte_size": instr.byte_size(),
                "is_branch": instr.is_branch(),
                "is_unconditional_branch": instr.is_unconditional_branch(),
                "is_terminator": instr.is_terminator(),
                "branch_targets": instr.branch_targets(),
                "source": "rustre_dotnet::CilInstruction::simple",
            })
            .to_string(),
        ))
    }
}

