#[async_trait]
impl ToolHandler for SymbolsSymbolContainsTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let address = args
            .get("address")
            .and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("address: required u64".to_string()))?;
        let target = args
            .get("target")
            .and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("target: required u64".to_string()))?;
        let size = args.get("size").and_then(Value::as_u64);
        let mut sym = rustre_symbols::Symbol::new(
            "wire_probe".to_string(),
            address,
            rustre_symbols::SymKind::Function,
        );
        sym.size = size;
        let contains = sym.contains(target);
        let end = sym.end_address();
        Ok(ToolResult::text(
            json!({
                "address": address,
                "size": size,
                "target": target,
                "contains": contains,
                "end_address": end,
                "source": "rustre_symbols::Symbol::contains",
            })
            .to_string(),
        ))
    }
}

