/// Bucket PDB symbols by `SymbolKind` (Function / Data / Label / Thunk).

impl SymbolsPdbSymbolsCountByKindTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "symbols_pdb_symbols_count_by_kind".to_string(),
            description:
                "Parse a PDB from bytes and return counts of PdbSymbol grouped by \
                 SymbolKind (function/data/label/thunk)."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "bytes": { "type": "array", "items": { "type": "integer" } },
                    "hex":   { "type": "string" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for SymbolsPdbSymbolsCountByKindTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let data = args_to_bytes(&args)?;
        match rustre_symbols_pdb::PdbReader::from_bytes(&data) {
            Ok(r) => {
                use rustre_symbols_pdb::SymbolKind;
                let mut func = 0u64;
                let mut data_c = 0u64;
                let mut label = 0u64;
                let mut thunk = 0u64;
                for s in r.symbols() {
                    match s.kind {
                        SymbolKind::Function => func += 1,
                        SymbolKind::Data => data_c += 1,
                        SymbolKind::Label => label += 1,
                        SymbolKind::Thunk => thunk += 1,
                    }
                }
                Ok(ToolResult::text(
                    json!({
                        "ok": true,
                        "function": func,
                        "data": data_c,
                        "label": label,
                        "thunk": thunk,
                        "source": "rustre_symbols_pdb::SymbolKind",
                    })
                    .to_string(),
                ))
            }
            Err(e) => Ok(ToolResult::text(
                json!({
                    "ok": false,
                    "error": e.to_string(),
                    "source": "rustre_symbols_pdb::SymbolKind",
                })
                .to_string(),
            )),
        }
    }
}

