/// Classify a STABS type descriptor character (the byte after `:` in `name:X`).

impl StabsTypeCodeFromCharTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "stabs_type_code_from_char".to_string(),
            description: "Classify the STABS type-descriptor character (e.g. 'f', \
                          'F', 'g', 't', 'T') via \
                          rustre_symbols_stabs::StabTypeCode::from_char."
                .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": { "ch": { "type": "string", "minLength": 1, "maxLength": 1 } },
                "required": ["ch"],
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for StabsTypeCodeFromCharTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let s = args
            .get("ch")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("ch: required single char".to_string()))?;
        let c = s
            .chars()
            .next()
            .ok_or_else(|| McpError::InvalidParams("ch: empty".to_string()))?;
        let code = rustre_symbols_stabs::StabTypeCode::from_char(c);
        Ok(ToolResult::text(
            json!({
                "input": c.to_string(),
                "code": format!("{:?}", code),
                "display": code.to_string(),
                "source": "rustre_symbols_stabs::StabTypeCode::from_char",
            })
            .to_string(),
        ))
    }
}

