/// Wrapper that extracts a bit-field slice from a raw u64 using
/// `rustre_hex_template::BitfieldDef::extract`.

impl HexTemplateBitfieldExtractTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "hex_template_bitfield_extract".to_string(),
            description: "Extract a bit-field slice from a raw u64 using \
                          rustre_hex_template::BitfieldDef::extract."
                .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "raw":       { "type": "integer" },
                    "start_bit": { "type": "integer" },
                    "bit_count": { "type": "integer" }
                },
                "required": ["raw", "start_bit", "bit_count"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for HexTemplateBitfieldExtractTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let raw = args
            .get("raw")
            .and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("raw: required u64".to_string()))?;
        let start_bit = args
            .get("start_bit")
            .and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("start_bit: required u8".to_string()))?
            as u8;
        let bit_count = args
            .get("bit_count")
            .and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("bit_count: required u8".to_string()))?
            as u8;
        let def = rustre_hex_template::BitfieldDef::new("f", start_bit, bit_count);
        let value = def.extract(raw);
        Ok(ToolResult::text(
            json!({
                "raw": raw,
                "start_bit": start_bit,
                "bit_count": bit_count,
                "value": value,
                "source": "rustre_hex_template::BitfieldDef::extract",
            })
            .to_string(),
        ))
    }
}

