#[cfg(any())] // DISABLED 2026-07-12 — rustre-debug-macos disabled
#[async_trait]
impl ToolHandler for DebugMacosBreakpointManagerBuildTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let entries = args
            .get("entries")
            .and_then(Value::as_array)
            .ok_or_else(|| McpError::InvalidParams("missing 'entries'".into()))?;
        let mut mgr = rustre_debug_macos::BreakpointManager::new();
        for e in entries {
            let addr = e
                .get("addr")
                .and_then(Value::as_u64)
                .ok_or_else(|| McpError::InvalidParams("entry: missing 'addr'".into()))?;
            let byte_u = e
                .get("byte")
                .and_then(Value::as_u64)
                .ok_or_else(|| McpError::InvalidParams("entry: missing 'byte'".into()))?;
            let byte = u8::try_from(byte_u)
                .map_err(|_| McpError::InvalidParams("entry: byte out of range".into()))?;
            mgr.insert(addr, byte);
        }
        let mut all = mgr.all();
        all.sort_unstable();
        Ok(ToolResult::text(
            json!({
                "count": all.len(),
                "addresses": all,
                "source": "rustre_debug_macos::BreakpointManager",
            })
            .to_string(),
        ))
    }
}

