/// Decode a caller-supplied hex payload, refusing what is not hex.
///
/// Feeds the `syscalls_windows_is_clean_*_stub` / `detect_hook_type` tools,
/// which COMPARE the decoded bytes against an expected prologue. A dropped byte
/// breaks the comparison, so the failure direction is a false ALARM ("stub not
/// clean") rather than a missed hook — loud, but still a security verdict
/// produced from bytes the caller did not send.
pub(crate) fn hex_to_bytes_swin(hex: &str) -> Result<Vec<u8>, McpError> { crate::hex_decode(hex) }

impl SyscallsWindowsIsCleanX64StubTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "syscalls_windows_is_clean_x64_stub".to_string(),
            description: "Check whether an x64 syscall stub (hex bytes) matches the expected SSN pattern.".to_string(),
            input_schema: json!({"type":"object","properties":{"stub_hex":{"type":"string"},"expected_ssn":{"type":"integer"}},"required":["stub_hex","expected_ssn"]}),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for SyscallsWindowsIsCleanX64StubTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let hex = args.get("stub_hex").and_then(|v| v.as_str()).ok_or_else(|| McpError::InvalidParams("missing 'stub_hex'".into()))?;
        let ssn = args.get("expected_ssn").and_then(|v| v.as_u64()).ok_or_else(|| McpError::InvalidParams("missing 'expected_ssn'".into()))? as u32;
        let bytes = hex_to_bytes_swin(hex)?;
        let clean = rustre_syscalls_windows::is_clean_x64_stub(&bytes, ssn);
        Ok(ToolResult::text(json!({"expected_ssn": ssn, "clean": clean, "source": "rustre_syscalls_windows::is_clean_x64_stub"}).to_string()))
    }
}

