/// Return the byte size of a primitive `DecompType` selected by name.
///
/// Wraps `rustre_decompiler_type::DecompType::byte_size`.

impl DecompilerTypeIntByteSizeTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "decompiler_type_int_byte_size".to_string(),
            description:
                "Return the byte size of a decompiler integer type (i8/i16/i32/i64/u8/u16/u32/u64) \
                 via rustre_decompiler_type::DecompType::byte_size."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": { "width": { "type": "string" } },
                "required": ["width"]
            }),
            parameters: Value::Null,
        }
    }
}

fn parse_int_width(s: &str) -> Result<rustre_decompiler_expr::IntWidth, McpError> {
    use rustre_decompiler_expr::IntWidth;
    Ok(match s.to_ascii_lowercase().as_str() {
        "i8" => IntWidth::I8,
        "i16" => IntWidth::I16,
        "i32" => IntWidth::I32,
        "i64" => IntWidth::I64,
        "u8" => IntWidth::U8,
        "u16" => IntWidth::U16,
        "u32" => IntWidth::U32,
        "u64" => IntWidth::U64,
        other => {
            return Err(McpError::InvalidParams(format!(
                "unknown width '{other}' (expected i8..i64 / u8..u64)"
            )))
        }
    })
}

#[async_trait]
impl ToolHandler for DecompilerTypeIntByteSizeTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let w = args
            .get("width")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'width'".into()))?;
        let width = parse_int_width(w)?;
        let ty = rustre_decompiler_type::DecompType::Int(width);
        let size = ty.byte_size();
        Ok(ToolResult::text(
            json!({
                "width":     w,
                "byte_size": size,
                "source":    "rustre_decompiler_type::DecompType::byte_size",
            })
            .to_string(),
        ))
    }
}

