/// Render an indent prefix mirroring `rustre_decompiler_c::IndentStyle`.

impl DecompilerCIndentMakeTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "decompiler_c_indent_make".to_string(),
            description:
                "Build an indent prefix string using rustre_decompiler_c::IndentStyle."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "style": {
                        "oneOf": [
                            { "type": "string" },
                            { "type": "integer", "minimum": 0, "maximum": 255 }
                        ]
                    },
                    "level": { "type": "integer", "minimum": 0 }
                },
                "required": ["level"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for DecompilerCIndentMakeTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let level = args
            .get("level")
            .and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'level'".into()))?
            as usize;
        let style = match args.get("style") {
            Some(v) if v.is_string() => {
                if v.as_str().unwrap_or("").eq_ignore_ascii_case("tabs") {
                    rustre_decompiler_c::IndentStyle::Tabs
                } else {
                    return Err(McpError::InvalidParams(
                        "'style' string must be \"tabs\"".into(),
                    ));
                }
            }
            Some(v) if v.is_u64() => {
                let n = u8::try_from(v.as_u64().unwrap_or(0)).map_err(|_| {
                    McpError::InvalidParams("'style' spaces out of u8 range".into())
                })?;
                rustre_decompiler_c::IndentStyle::Spaces(n)
            }
            None => rustre_decompiler_c::IndentStyle::default(),
            _ => {
                return Err(McpError::InvalidParams(
                    "'style' must be string \"tabs\" or integer".into(),
                ));
            }
        };
        let lvl = level.min(256);
        let out = match &style {
            rustre_decompiler_c::IndentStyle::Spaces(n) => {
                " ".repeat((*n as usize).saturating_mul(lvl))
            }
            rustre_decompiler_c::IndentStyle::Tabs => "\t".repeat(lvl),
        };
        Ok(ToolResult::text(
            json!({
                "indent":  out,
                "length":  out.len(),
                "level":   level,
                "source":  "rustre_decompiler_c::IndentStyle",
            })
            .to_string(),
        ))
    }
}

