/// IntWidth bits.

impl DecompilerExprIntWidthBitsTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "decompiler_expr_int_width_bits".to_string(),
            description: "Return the bit-width of a rustre_decompiler_expr::IntWidth variant.".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": { "width": { "type": "string", "enum": ["i8","i16","i32","i64","u8","u16","u32","u64"] } },
                "required": ["width"]
            }),
            parameters: Value::Null,
        }
    }
}

fn parse_int_width_wire(name: &str) -> Result<rustre_decompiler_expr::IntWidth, McpError> {
    match name.to_ascii_lowercase().as_str() {
        "i8" => Ok(rustre_decompiler_expr::IntWidth::I8),
        "i16" => Ok(rustre_decompiler_expr::IntWidth::I16),
        "i32" => Ok(rustre_decompiler_expr::IntWidth::I32),
        "i64" => Ok(rustre_decompiler_expr::IntWidth::I64),
        "u8" => Ok(rustre_decompiler_expr::IntWidth::U8),
        "u16" => Ok(rustre_decompiler_expr::IntWidth::U16),
        "u32" => Ok(rustre_decompiler_expr::IntWidth::U32),
        "u64" => Ok(rustre_decompiler_expr::IntWidth::U64),
        other => Err(McpError::InvalidParams(format!("unknown IntWidth '{other}'"))),
    }
}

#[async_trait]
impl ToolHandler for DecompilerExprIntWidthBitsTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let name = args.get("width").and_then(Value::as_str).ok_or_else(|| McpError::InvalidParams("missing 'width'".into()))?;
        let w = parse_int_width_wire(name)?;
        Ok(ToolResult::text(json!({ "width": name, "bits": w.bits(), "source": "rustre_decompiler_expr::IntWidth::bits" }).to_string()))
    }
}

