/// Expose `rustre_yara::StringMatcher::check_fullword` as an MCP tool.

impl YaraCheckFullwordTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "yara_check_fullword".to_string(),
            description: "Return true if data[offset..offset+len] is bounded by non-word characters (or file start/end).".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "data": {"type": "array", "items": {"type": "integer"}},
                    "offset": {"type": "integer"},
                    "len": {"type": "integer"}
                },
                "required": ["data", "offset", "len"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for YaraCheckFullwordTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let data: Vec<u8> = args
            .get("data")
            .and_then(Value::as_array)
            .map(|arr| arr.iter().filter_map(|v| v.as_u64().map(|n| n as u8)).collect())
            .unwrap_or_default();
        let offset = args.get("offset").and_then(Value::as_u64).ok_or_else(|| McpError::InvalidParams("missing 'offset'".into()))? as usize;
        let len = args.get("len").and_then(Value::as_u64).ok_or_else(|| McpError::InvalidParams("missing 'len'".into()))? as usize;
        let ok = rustre_yara::StringMatcher::check_fullword(&data, offset, len);
        Ok(ToolResult::text(json!({ "fullword": ok }).to_string()))
    }
}

