/// Build a `MemFsNodeV2` file node and return its size.

impl ForensicsFsMemFsNodeV2FileSizeTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "forensics_fs_memfs_node_v2_file_size".to_string(),
            description:
                "Construct a MemFsNodeV2 file via new_file and return its size in bytes."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "name":    { "type": "string" },
                    "content": { "type": "array", "items": { "type": "integer" } },
                    "hex":     { "type": "string" },
                    "inode":   { "type": "integer" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for ForensicsFsMemFsNodeV2FileSizeTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let name = args
            .get("name")
            .and_then(Value::as_str)
            .unwrap_or("f")
            .to_string();
        let content = extract_byte_array(&args, "content", "hex").unwrap_or_default();
        let inode = args.get("inode").and_then(Value::as_u64).unwrap_or(2);
        let node = rustre_forensics_fs::MemFsNodeV2::new_file(name, content, inode);
        Ok(ToolResult::text(
            json!({
                "name": node.name,
                "inode": node.inode,
                "size": node.size(),
                "is_file": node.is_file(),
                "source": "rustre_forensics_fs::MemFsNodeV2::new_file",
            })
            .to_string(),
        ))
    }
}

