// --- triage-entropy extra wrappers ---

impl EmuArchPointerSizeWireTool {
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "emu_arch_pointer_size_wire".to_string(),
            description: "Return the pointer size in bytes for a rustre_emu::EmulatorArch variant.".to_string(),
            input_schema: json!({"type":"object","properties":{"arch":{"type":"string"}}}),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for EmuArchPointerSizeWireTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let arch_name = args.get("arch").and_then(Value::as_str).unwrap_or("x86-64");
        let arch = match arch_name {
            "x86-16" => rustre_emu::EmulatorArch::X86_16,
            "x86-32" => rustre_emu::EmulatorArch::X86_32,
            "x86-64" => rustre_emu::EmulatorArch::X86_64,
            "arm" => rustre_emu::EmulatorArch::Arm,
            "arm-thumb" => rustre_emu::EmulatorArch::ArmThumb,
            "arm64" => rustre_emu::EmulatorArch::Arm64,
            "mips32" => rustre_emu::EmulatorArch::Mips32,
            "mips64" => rustre_emu::EmulatorArch::Mips64,
            "mips32el" => rustre_emu::EmulatorArch::Mips32El,
            "riscv32" => rustre_emu::EmulatorArch::RiscV32,
            "riscv64" => rustre_emu::EmulatorArch::RiscV64,
            "sparc32" => rustre_emu::EmulatorArch::Sparc32,
            "sparc64" => rustre_emu::EmulatorArch::Sparc64,
            _ => rustre_emu::EmulatorArch::X86_64,
        };
        Ok(ToolResult::text(json!({
            "arch": arch.name(),
            "pointer_size": arch.pointer_size(),
            "is_64bit": arch.is_64bit(),
            "source": "rustre_emu::EmulatorArch::pointer_size",
        }).to_string()))
    }
}

