/// Wrap `rustre_agent::MessageRole::as_str`.

impl AgentMessageRoleAsStrWireTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "agent_message_role_as_str_wire".to_string(),
            description: "Return the lowercase string form of a rustre_agent::MessageRole (system|user|assistant|tool).".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": { "role": { "type": "string" } },
                "required": ["role"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for AgentMessageRoleAsStrWireTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let role = args
            .get("role")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'role'".into()))?;
        let r = match role.to_ascii_lowercase().as_str() {
            "system" => rustre_agent::MessageRole::System,
            "user" => rustre_agent::MessageRole::User,
            "assistant" => rustre_agent::MessageRole::Assistant,
            "tool" => rustre_agent::MessageRole::Tool,
            other => {
                return Err(McpError::InvalidParams(format!(
                    "unknown role '{other}' (expected system|user|assistant|tool)"
                )));
            }
        };
        Ok(ToolResult::text(
            json!({
                "as_str": r.as_str(),
                "source": "rustre_agent::MessageRole::as_str",
            })
            .to_string(),
        ))
    }
}

