struct SparcEncodeCallWireTool;

impl SparcEncodeCallWireTool {
    fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "sparc_encode_call".to_string(),
            description: "Encode a SPARC CALL instruction with PC-relative displacement (must be 4-byte aligned).".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "disp": { "type": "integer" }
                },
                "required": ["disp"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for SparcEncodeCallWireTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let disp_i64 = args
            .get("disp")
            .and_then(Value::as_i64)
            .ok_or_else(|| McpError::InvalidParams("missing disp".to_string()))?;
        let disp = i32::try_from(disp_i64)
            .map_err(|_| McpError::InvalidParams("disp out of i32 range".to_string()))?;
        if disp % 4 != 0 {
            return Err(McpError::InvalidParams(
                "disp must be 4-byte aligned".to_string(),
            ));
        }
        let word = rustre_arch_sparc::encode_call(disp);
        Ok(ToolResult::text(
            json!({
                "word": word,
                "hex": format!("{:08X}", word),
                "disp": disp,
                "source": "rustre_arch_sparc::encode_call",
            })
            .to_string(),
        ))
    }
}

// --- sparc extended wrappers ---

fn sparc_arg_u32(args: &Value, key: &str) -> Result<u32, McpError> {
    let v = args.get(key).and_then(Value::as_u64)
        .ok_or_else(|| McpError::InvalidParams(format!("missing {}", key)))?;
    u32::try_from(v).map_err(|_| McpError::InvalidParams(format!("{} out of u32 range", key)))
}
fn sparc_arg_i32(args: &Value, key: &str) -> Result<i32, McpError> {
    let v = args.get(key).and_then(Value::as_i64)
        .ok_or_else(|| McpError::InvalidParams(format!("missing {}", key)))?;
    i32::try_from(v).map_err(|_| McpError::InvalidParams(format!("{} out of i32 range", key)))
}
fn sparc_arg_u8(args: &Value, key: &str) -> Result<u8, McpError> {
    let v = args.get(key).and_then(Value::as_u64)
        .ok_or_else(|| McpError::InvalidParams(format!("missing {}", key)))?;
    u8::try_from(v).map_err(|_| McpError::InvalidParams(format!("{} out of u8 range", key)))
}

macro_rules! sparc_wire_word_tool {
    ($ty:ident, $name:literal, $desc:literal, $src:literal, $call:expr, [$($arg:literal),*]) => {
        struct $ty;
        impl $ty {
            fn definition() -> ToolDefinition {
                let mut props = serde_json::Map::new();
                $( props.insert($arg.to_string(), json!({"type": "integer"})); )*
                ToolDefinition {
                    name: $name.to_string(),
                    description: $desc.to_string(),
                    input_schema: json!({
                        "type": "object",
                        "properties": Value::Object(props),
                        "required": [$($arg),*]
                    }),
                    parameters: Value::Null,
                }
            }
        }
        #[async_trait]
        impl ToolHandler for $ty {
            async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
                let word: u32 = ($call)(&args)?;
                Ok(ToolResult::text(json!({
                    "word": word,
                    "hex": format!("{:08X}", word),
                    "source": $src,
                }).to_string()))
            }
        }
    };
}

