struct SparcExtractBranchTargetsWireTool;
impl SparcExtractBranchTargetsWireTool {
    fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "sparc_extract_branch_targets".to_string(),
            description: "Extract branch targets from SPARC code (hex bytes, base VA).".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {"bytes_hex": {"type": "string"}, "base": {"type": "integer"}},
                "required": ["bytes_hex", "base"]
            }),
            parameters: Value::Null,
        }
    }
}
#[async_trait]
impl ToolHandler for SparcExtractBranchTargetsWireTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let hex = args.get("bytes_hex").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing bytes_hex".to_string()))?;
        let base = args.get("base").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing base".to_string()))?;
        let clean: String = hex.chars().filter(|c| !c.is_whitespace()).collect();
        if !clean.is_ascii() {
            return Err(McpError::InvalidParams("hex must be ASCII".into()));
        }
        if clean.len() % 2 != 0 {
            return Err(McpError::InvalidParams("bytes_hex must be even length".to_string()));
        }
        let mut bytes = Vec::with_capacity(clean.len() / 2);
        for i in (0..clean.len()).step_by(2) {
            bytes.push(u8::from_str_radix(&clean[i..i+2], 16)
                .map_err(|e| McpError::InvalidParams(format!("bad hex: {}", e)))?);
        }
        let targets = rustre_arch_sparc::extract_branch_targets(&bytes, base);
        Ok(ToolResult::text(json!({
            "count": targets.len(),
            "targets": targets.iter().map(|(a, b)| json!({"from": a, "to": b})).collect::<Vec<_>>(),
            "source": "rustre_arch_sparc::extract_branch_targets",
        }).to_string()))
    }
}

