// â”€â”€â”€ arch68k_size_bytes / arch68k_condcode_mnemonic â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

/// Expose `rustre_arch_68k::Size::bytes` as an MCP tool.

impl Arch68kSizeBytesTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "arch68k_size_bytes".to_string(),
            description: "Return the number of bytes consumed by a Motorola 68k operand size (B/W/L/Q).".to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["size"],
                "properties": {
                    "size": { "type": "string", "description": "One of: B, W, L, Q" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for Arch68kSizeBytesTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let s = args.get("size").and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'size'".into()))?;
        let sz = match s {
            "B" | "b" => rustre_arch_68k::Size::Byte,
            "W" | "w" => rustre_arch_68k::Size::Word,
            "L" | "l" => rustre_arch_68k::Size::Long,
            "Q" | "q" => rustre_arch_68k::Size::Quad,
            other => return Err(McpError::InvalidParams(format!("unknown size '{other}'"))),
        };
        Ok(ToolResult::text(
            json!({
                "size": s,
                "suffix": sz.suffix(),
                "bytes": sz.bytes(),
            })
            .to_string(),
        ))
    }
}

/// Expose `rustre_arch_68k::CondCode::mnemonic` as an MCP tool.

impl Arch68kCondCodeMnemonicTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "arch68k_condcode_mnemonic".to_string(),
            description: "Return the Motorola 68k condition-code mnemonic for a 4-bit code.".to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["bits"],
                "properties": {
                    "bits": { "type": "integer", "description": "4-bit condition code (0..15)" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for Arch68kCondCodeMnemonicTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let bits = args.get("bits").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'bits'".into()))?;
        let cc = rustre_arch_68k::CondCode::from_bits(bits as u8);
        Ok(ToolResult::text(
            json!({
                "bits": bits & 0xF,
                "mnemonic": cc.mnemonic(),
                "is_unconditional": cc.is_unconditional(),
            })
            .to_string(),
        ))
    }
}

