/// Match a pipe-delimited AlternationPattern at a given offset in a byte buffer.

impl HexPatternAlternationMatchesTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "hex_pattern_alternation_matches".to_string(),
            description:
                "Parse a pipe-delimited alternation pattern via                  rustre_hex_pattern::AlternationPattern::parse and test whether it                  matches the given byte buffer at the specified offset."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "pattern": { "type": "string" },
                    "bytes":   { "type": "array", "items": { "type": "integer" } },
                    "offset":  { "type": "integer", "default": 0 }
                },
                "required": ["pattern", "bytes"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for HexPatternAlternationMatchesTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let s = args
            .get("pattern")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing pattern string".into()))?;
        let arr = args
            .get("bytes")
            .and_then(Value::as_array)
            .ok_or_else(|| McpError::InvalidParams("missing bytes array".into()))?;
        let mut buf = Vec::with_capacity(arr.len());
        for v in arr {
            let n = v.as_u64().ok_or_else(|| McpError::InvalidParams("byte not integer".into()))?;
            buf.push(u8::try_from(n).map_err(|_| McpError::InvalidParams("byte out of u8 range".into()))?);
        }
        let offset = usize::try_from(args.get("offset").and_then(Value::as_u64).unwrap_or(0))
            .map_err(|_| McpError::InvalidParams("offset too large".into()))?;
        let alt = rustre_hex_pattern::AlternationPattern::parse(s)
            .map_err(|e| McpError::InvalidParams(format!("parse error: {e}")))?;
        let matched = alt.matches(&buf, offset);
        Ok(ToolResult::text(
            json!({
                "matches": matched,
                "offset": offset,
                "alt_count": alt.len(),
                "source": "rustre_hex_pattern::AlternationPattern::matches",
            })
            .to_string(),
        ))
    }
}

/// Search all matches of a pattern (via MaskedPattern) in a byte buffer.

impl HexPatternMaskedSearchTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "hex_pattern_masked_search".to_string(),
            description:
                "Parse a pattern string, convert into a MaskedPattern, and return                  all match offsets in the given byte buffer via                  rustre_hex_pattern::MaskedPattern::search."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "pattern": { "type": "string" },
                    "bytes":   { "type": "array", "items": { "type": "integer" } }
                },
                "required": ["pattern", "bytes"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for HexPatternMaskedSearchTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let s = args
            .get("pattern")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing pattern string".into()))?;
        let arr = args
            .get("bytes")
            .and_then(Value::as_array)
            .ok_or_else(|| McpError::InvalidParams("missing bytes array".into()))?;
        let mut buf = Vec::with_capacity(arr.len());
        for v in arr {
            let n = v.as_u64().ok_or_else(|| McpError::InvalidParams("byte not integer".into()))?;
            buf.push(u8::try_from(n).map_err(|_| McpError::InvalidParams("byte out of u8 range".into()))?);
        }
        let pat = rustre_hex_pattern::Pattern::parse(s)
            .map_err(|e| McpError::InvalidParams(format!("parse error: {e}")))?;
        let masked = rustre_hex_pattern::MaskedPattern::from_pattern(&pat);
        let hits = masked.search(&buf);
        Ok(ToolResult::text(
            json!({
                "pattern_len": masked.len(),
                "match_count": hits.len(),
                "offsets": hits,
                "source": "rustre_hex_pattern::MaskedPattern::search",
            })
            .to_string(),
        ))
    }
}

