impl MemPageRangeIndicesTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "mem_page_range_indices".to_string(),
            description: "Return (first_page_index, last_page_index) covering [start, end) (rustre_mem::page_range_indices).".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "start": { "type": "integer" },
                    "end": { "type": "integer" },
                    "page_size": { "type": "integer" }
                },
                "required": ["start", "end", "page_size"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for MemPageRangeIndicesTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let start = args.get("start").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'start'".to_string()))?;
        let end = args.get("end").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'end'".to_string()))?;
        let page_size = args.get("page_size").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'page_size'".to_string()))?;
        let range = rustre_core::address::AddressRange::new(
            rustre_core::address::Address::new(start),
            rustre_core::address::Address::new(end),
        );
        let (first, last) = rustre_mem::page_range_indices(&range, page_size);
        Ok(ToolResult::text(
            json!({
                "start": start, "end": end, "page_size": page_size,
                "first_page_index": first, "last_page_index": last,
                "source": "rustre_mem::page_range_indices"
            }).to_string(),
        ))
    }
}

