/// Serialize a `CoverageRun` to the custom binary format (wraps `rustre_trace_coverage::to_custom_binary`).

impl TraceCoverageToCustomBinaryTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "trace_coverage_to_custom_binary".to_string(),
            description:
                "Serialize a CoverageRun (JSON) to the custom binary format. Wraps rustre_trace_coverage::to_custom_binary."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": { "run_json": { "type": "string" } },
                "required": ["run_json"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for TraceCoverageToCustomBinaryTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let run_json = args
            .get("run_json")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'run_json'".to_string()))?;
        let run: rustre_trace_coverage::CoverageRun = serde_json::from_str(run_json)
            .map_err(|e| McpError::InvalidParams(format!("run_json: {e}")))?;
        let bytes = rustre_trace_coverage::to_custom_binary(&run);
        let hex_out: String = bytes.iter().map(|b| format!("{:02x}", b)).collect();
        Ok(ToolResult::text(
            json!({
                "len": bytes.len(),
                "hex": hex_out,
                "source": "rustre_trace_coverage::to_custom_binary",
            })
            .to_string(),
        ))
    }
}

/// Merge two `CoverageRun`s (wraps `rustre_trace_coverage::merge_runs`).

impl TraceCoverageMergeRunsTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "trace_coverage_merge_runs".to_string(),
            description:
                "Merge two CoverageRun (JSON) values into one by summing hit counts. Wraps rustre_trace_coverage::merge_runs."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "a_json": { "type": "string" },
                    "b_json": { "type": "string" },
                    "name": { "type": "string" }
                },
                "required": ["a_json", "b_json", "name"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for TraceCoverageMergeRunsTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let a_json = args
            .get("a_json")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'a_json'".to_string()))?;
        let b_json = args
            .get("b_json")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'b_json'".to_string()))?;
        let name = args
            .get("name")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'name'".to_string()))?;
        let a: rustre_trace_coverage::CoverageRun = serde_json::from_str(a_json)
            .map_err(|e| McpError::InvalidParams(format!("a_json: {e}")))?;
        let b: rustre_trace_coverage::CoverageRun = serde_json::from_str(b_json)
            .map_err(|e| McpError::InvalidParams(format!("b_json: {e}")))?;
        let merged = rustre_trace_coverage::merge_runs(&a, &b, name);
        Ok(ToolResult::text(
            json!({
                "unique_bbs": merged.unique_bbs(),
                "unique_edges": merged.unique_edges(),
                "run": merged,
                "source": "rustre_trace_coverage::merge_runs",
            })
            .to_string(),
        ))
    }
}

