/// Compute wildcard ratio of a FLIRT initial-byte pattern via `rustre_flirt::FlirtPattern::wildcard_ratio`.

impl FlirtPatternWildcardRatioWireTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "flirt_pattern_wildcard_ratio".to_string(),
            description: "Build a FlirtPattern from a byte-token list ('XX' hex or '..' wildcard) and return its wildcard ratio and hex rendering via rustre_flirt::FlirtPattern.".to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["tokens"],
                "properties": {
                    "tokens": { "type": "array", "items": { "type": "string" } }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for FlirtPatternWildcardRatioWireTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let toks = args.get("tokens").and_then(Value::as_array)
            .ok_or_else(|| McpError::InvalidParams("missing 'tokens'".into()))?;
        let mut bytes: Vec<rustre_flirt::PatternByte> = Vec::with_capacity(toks.len());
        for t in toks {
            let s = t.as_str().ok_or_else(|| McpError::InvalidParams("token not string".into()))?;
            if s == ".." {
                bytes.push(rustre_flirt::PatternByte::Wildcard);
            } else {
                let b = u8::from_str_radix(s, 16)
                    .map_err(|e| McpError::InvalidParams(format!("bad hex token '{s}': {e}")))?;
                bytes.push(rustre_flirt::PatternByte::Exact(b));
            }
        }
        let pat = rustre_flirt::FlirtPattern::new(bytes);
        Ok(ToolResult::text(json!({
            "len": pat.initial_bytes.len(),
            "wildcard_ratio": pat.wildcard_ratio(),
            "pattern_hex": pat.pattern_hex(),
            "source": "rustre_flirt::FlirtPattern::wildcard_ratio",
        }).to_string()))
    }
}

/// Test which named flags are set in a FLIRT file-type bitmask via `rustre_flirt::FlirtFileType::contains`.

impl FlirtFileTypeContainsWireTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "flirt_file_type_contains".to_string(),
            description: "Given a raw FLIRT file_types bitmask u32, report which named flags (PE/ELF/COFF/...) are set via rustre_flirt::FlirtFileType::contains.".to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["bits"],
                "properties": { "bits": { "type": "integer" } }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for FlirtFileTypeContainsWireTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let bits = args.get("bits").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("missing 'bits'".into()))? as u32;
        let ft = rustre_flirt::FlirtFileType::from_u32(bits);
        let named: &[(&str, rustre_flirt::FlirtFileType)] = &[
            ("DOS_EXE", rustre_flirt::FlirtFileType::DOS_EXE),
            ("DOS_COM", rustre_flirt::FlirtFileType::DOS_COM),
            ("BIN", rustre_flirt::FlirtFileType::BIN),
            ("NE", rustre_flirt::FlirtFileType::NE),
            ("LX", rustre_flirt::FlirtFileType::LX),
            ("LE", rustre_flirt::FlirtFileType::LE),
            ("COFF", rustre_flirt::FlirtFileType::COFF),
            ("PE", rustre_flirt::FlirtFileType::PE),
            ("OMF", rustre_flirt::FlirtFileType::OMF),
            ("AR", rustre_flirt::FlirtFileType::AR),
            ("ELF", rustre_flirt::FlirtFileType::ELF),
            ("EXE", rustre_flirt::FlirtFileType::EXE),
        ];
        let matched: Vec<&str> = named.iter()
            .filter(|(_, flag)| ft.contains(*flag))
            .map(|(n, _)| *n)
            .collect();
        Ok(ToolResult::text(json!({
            "bits": bits,
            "flags": matched,
            "source": "rustre_flirt::FlirtFileType::contains",
        }).to_string()))
    }
}

