// â”€â”€â”€ rustre-analysis-cfg wire wrappers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

fn parse_flow_edge_kind(s: &str) -> Result<rustre_analysis_cfg::FlowEdgeKind, McpError> {
    use rustre_analysis_cfg::FlowEdgeKind as K;
    match s {
        "Fallthrough" | "fallthrough" => Ok(K::Fallthrough),
        "Jump" | "jump" => Ok(K::Jump),
        "BranchTaken" | "branch_taken" => Ok(K::BranchTaken),
        "BranchNotTaken" | "branch_not_taken" => Ok(K::BranchNotTaken),
        "Call" | "call" => Ok(K::Call),
        "Return" | "return" => Ok(K::Return),
        "Indirect" | "indirect" => Ok(K::Indirect),
        _ => Err(McpError::InvalidParams(format!("unknown FlowEdgeKind: {s}"))),
    }
}

