pub(crate) fn script_read_helper_new(
    args: &Value,
    call: fn(&[rustre_script::ScriptValue]) -> Result<rustre_script::ScriptValue, rustre_script::ScriptError>,
    name: &str,
) -> Result<(i64, Vec<u8>, i64), McpError> {
    let data = args_to_bytes(args)?;
    let off = args.get("offset").and_then(Value::as_i64).ok_or_else(|| McpError::InvalidParams("missing 'offset'".into()))?;
    let sv = call(&[rustre_script::ScriptValue::Bytes(data.clone()), rustre_script::ScriptValue::Int(off)])
        .map_err(|e| McpError::InvalidParams(e.to_string()))?;
    let value = match sv {
        rustre_script::ScriptValue::Int(n) => n,
        rustre_script::ScriptValue::Address(a) => a as i64,
        other => return Err(McpError::InternalError(format!("{name} returned {}", other.type_name()))),
    };
    Ok((value, data, off))
}





pub(crate) fn script_write_helper_new(
    args: &Value,
    call: fn(&[rustre_script::ScriptValue]) -> Result<rustre_script::ScriptValue, rustre_script::ScriptError>,
    name: &str,
) -> Result<(Vec<u8>, i64), McpError> {
    let data = args_to_bytes(args)?;
    let off = args.get("offset").and_then(Value::as_i64).ok_or_else(|| McpError::InvalidParams("missing 'offset'".into()))?;
    let val = args.get("value").and_then(Value::as_i64).ok_or_else(|| McpError::InvalidParams("missing 'value'".into()))?;
    let sv = call(&[rustre_script::ScriptValue::Bytes(data), rustre_script::ScriptValue::Int(off), rustre_script::ScriptValue::Int(val)])
        .map_err(|e| McpError::InvalidParams(e.to_string()))?;
    match sv { rustre_script::ScriptValue::Bytes(b) => Ok((b, off)), other => Err(McpError::InternalError(format!("{name} returned {}", other.type_name()))) }
}











