pub(crate) fn hp_parse_bytes(v: &Value) -> Result<Vec<u8>, McpError> {
    let arr = v.as_array().ok_or_else(|| McpError::InvalidParams("bytes: not array".into()))?;
    let mut buf = Vec::with_capacity(arr.len());
    for x in arr {
        let n = x.as_u64().ok_or_else(|| McpError::InvalidParams("byte not integer".into()))?;
        buf.push(u8::try_from(n).map_err(|_| McpError::InvalidParams("byte out of u8 range".into()))?);
    }
    Ok(buf)
}

