pub(crate) fn _mem_prov_from_hex(buf_hex: &str, base: u64) -> Result<(rustre_mem::VirtualMemoryProvider, usize), McpError> {
    let buf = crate::hex_decode(buf_hex.trim())?;
    let len = buf.len();
    let mut prov = rustre_mem::VirtualMemoryProvider::new();
    prov.map(
        rustre_core::address::Address::new(base),
        buf,
        rustre_core::permissions::Permissions::READ | rustre_core::permissions::Permissions::WRITE,
    );
    Ok((prov, len))
}

