fn emu_base_parse_arch(s: &str) -> Option<rustre_emu::EmulatorArch> {
    use rustre_emu::EmulatorArch as A;
    Some(match s {
        "x86-16" | "x86_16" => A::X86_16,
        "x86-32" | "x86_32" => A::X86_32,
        "x86-64" | "x86_64" => A::X86_64,
        "arm" => A::Arm,
        "arm-thumb" | "arm_thumb" => A::ArmThumb,
        "arm64" => A::Arm64,
        "mips32" => A::Mips32,
        "mips64" => A::Mips64,
        "mips32el" => A::Mips32El,
        "riscv32" => A::RiscV32,
        "riscv64" => A::RiscV64,
        "sparc32" => A::Sparc32,
        "sparc64" => A::Sparc64,
        _ => return None,
    })
}

