// ─── rustre-analysis-cfg extended MCP wrappers ────────────────────────────
pub(crate) fn ancfg_build_cfg_from_args(args: &Value) -> Result<rustre_analysis_cfg::ControlFlowGraph, McpError> {
    use rustre_analysis_cfg::{BasicBlock, CfgEdge, ControlFlowGraph, DominatorTree, EdgeKind, PostDominatorTree, find_natural_loops};
    use rustre_core::address::Address;
    use std::collections::{HashMap, HashSet};

    let edges_v = args.get("edges").and_then(Value::as_array)
        .ok_or_else(|| McpError::InvalidParams("missing 'edges' array".into()))?;
    let entry_u = args.get("entry").and_then(Value::as_u64)
        .ok_or_else(|| McpError::InvalidParams("missing 'entry' (u64)".into()))?;

    let mut node_set: HashSet<u64> = HashSet::new();
    node_set.insert(entry_u);
    let mut edges: Vec<CfgEdge> = Vec::new();
    for e in edges_v {
        let f = e.get("from").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("edge missing 'from'".into()))?;
        let t = e.get("to").and_then(Value::as_u64)
            .ok_or_else(|| McpError::InvalidParams("edge missing 'to'".into()))?;
        let kind = match e.get("kind").and_then(Value::as_str).unwrap_or("uncond") {
            "true" | "TrueBranch" | "true_branch" => EdgeKind::TrueBranch,
            "false" | "FalseBranch" | "false_branch" => EdgeKind::FalseBranch,
            "fall" | "Fallthrough" | "fallthrough" => EdgeKind::Fallthrough,
            _ => EdgeKind::Unconditional,
        };
        node_set.insert(f);
        node_set.insert(t);
        edges.push(CfgEdge { from: Address::new(f), to: Address::new(t), kind });
    }
    if let Some(extra) = args.get("nodes").and_then(Value::as_array) {
        for n in extra { if let Some(u) = n.as_u64() { node_set.insert(u); } }
    }
    let mut blocks: HashMap<Address, BasicBlock> = HashMap::new();
    for &u in &node_set {
        let a = Address::new(u);
        blocks.insert(a, BasicBlock { start: a, end: a, instructions: vec![] });
    }
    let entry = Address::new(entry_u);
    let dom_tree = DominatorTree::compute(&blocks, &edges, entry);
    let post_dom_tree = PostDominatorTree::compute(&blocks, &edges);
    let mut cfg = ControlFlowGraph { blocks, edges, entry, dom_tree, post_dom_tree, loops: Vec::new() };
    cfg.loops = find_natural_loops(&cfg);
    Ok(cfg)
}

pub(crate) fn ancfg_edges_schema() -> Value {
    json!({
        "type": "object",
        "properties": {
            "entry": {"type": "integer"},
            "edges": {"type": "array", "items": {"type": "object",
                "properties": {"from":{"type":"integer"}, "to":{"type":"integer"}, "kind":{"type":"string"}},
                "required": ["from","to"]}},
            "nodes": {"type": "array", "items": {"type":"integer"}}
        },
        "required": ["entry","edges"]
    })
}

