// ---- rustre-analysis-xref: XrefDatabase / XrefGraph wrappers ----
pub(crate) fn axr_build_db_from_calls(args: &Value) -> rustre_analysis_xref::XrefDatabase {
    use rustre_core::address::Address;
    let mut db = rustre_analysis_xref::XrefDatabase::new();
    if let Some(arr) = args.get("calls").and_then(Value::as_array) {
        for v in arr {
            let from = v.get("from").and_then(Value::as_u64).unwrap_or(0);
            let to = v.get("to").and_then(Value::as_u64).unwrap_or(0);
            let sz = v.get("size").and_then(Value::as_u64).unwrap_or(5) as u8;
            db.add_call(Address::new(from), Address::new(to), sz);
        }
    }
    if let Some(arr) = args.get("jumps").and_then(Value::as_array) {
        for v in arr {
            let from = v.get("from").and_then(Value::as_u64).unwrap_or(0);
            let to = v.get("to").and_then(Value::as_u64).unwrap_or(0);
            let sz = v.get("size").and_then(Value::as_u64).unwrap_or(2) as u8;
            db.add_jump(Address::new(from), Address::new(to), sz);
        }
    }
    if let Some(arr) = args.get("data_reads").and_then(Value::as_array) {
        for v in arr {
            let from = v.get("from").and_then(Value::as_u64).unwrap_or(0);
            let to = v.get("to").and_then(Value::as_u64).unwrap_or(0);
            db.add_data_read(Address::new(from), Address::new(to));
        }
    }
    if let Some(arr) = args.get("strings").and_then(Value::as_array) {
        for v in arr {
            let from = v.get("from").and_then(Value::as_u64).unwrap_or(0);
            let to = v.get("to").and_then(Value::as_u64).unwrap_or(0);
            let content = v.get("content").and_then(Value::as_str).unwrap_or("");
            db.add_string_ref(Address::new(from), Address::new(to), content);
        }
    }
    if let Some(arr) = args.get("imports").and_then(Value::as_array) {
        for v in arr {
            let from = v.get("from").and_then(Value::as_u64).unwrap_or(0);
            let to = v.get("to").and_then(Value::as_u64).unwrap_or(0);
            let name = v.get("name").and_then(Value::as_str).unwrap_or("");
            db.add_import_by_name(Address::new(from), Address::new(to), name);
        }
    }
    db
}

