pub(crate) fn rsymb_v2_val(v: u64, width_bits: u32) -> rustre_symb::symbolic_value::SymbolicValue {
    let w = rustre_symb::symbolic_value::ValueWidth::from_bits(width_bits);
    rustre_symb::symbolic_value::SymbolicValue::constant(v, w)
}

macro_rules! rsymb_v2_binop {
    ($tool:ident, $name:literal, $desc:literal, $func:path, $src:literal) => {
        pub struct $tool;
        impl $tool {
            #[must_use]
            pub fn definition() -> ToolDefinition {
                ToolDefinition {
                    name: $name.to_string(),
                    description: $desc.to_string(),
                    input_schema: json!({"type":"object","required":["lhs","rhs","width"],"properties":{"lhs":{"type":"integer"},"rhs":{"type":"integer"},"width":{"type":"integer"}}}),
                    parameters: Value::Null,
                }
            }
        }
        #[async_trait]
        impl ToolHandler for $tool {
            async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
                let l = args.get("lhs").and_then(Value::as_u64).unwrap_or(0);
                let r = args.get("rhs").and_then(Value::as_u64).unwrap_or(0);
                let w = args.get("width").and_then(Value::as_u64).unwrap_or(64) as u32;
                let out = $func(rsymb_v2_val(l, w), rsymb_v2_val(r, w));
                Ok(ToolResult::text(json!({
                    "result": out.as_concrete(),
                    "is_concrete": out.is_concrete(),
                    "source": $src
                }).to_string()))
            }
        }
    };
}

rsymb_v2_binop!(RustreSymbV2SymbolicAddTool, "rustre_symb_v2_symbolic_add", "Fold constants via rustre_symb::symbolic_add.", rustre_symb::symbolic_value::symbolic_add, "rustre_symb::symbolic_add");
rsymb_v2_binop!(RustreSymbV2SymbolicAndTool, "rustre_symb_v2_symbolic_and", "Fold constants via rustre_symb::symbolic_and.", rustre_symb::symbolic_value::symbolic_and, "rustre_symb::symbolic_and");
rsymb_v2_binop!(RustreSymbV2SymbolicOrTool,  "rustre_symb_v2_symbolic_or",  "Fold constants via rustre_symb::symbolic_or.",  rustre_symb::symbolic_value::symbolic_or,  "rustre_symb::symbolic_or");
rsymb_v2_binop!(RustreSymbV2SymbolicXorTool, "rustre_symb_v2_symbolic_xor", "Fold constants via rustre_symb::symbolic_xor.", rustre_symb::symbolic_value::symbolic_xor, "rustre_symb::symbolic_xor");
rsymb_v2_binop!(RustreSymbV2SymbolicSubTool, "rustre_symb_v2_symbolic_sub", "Fold constants via rustre_symb::symbolic_sub.", rustre_symb::symbolic_value::symbolic_sub, "rustre_symb::symbolic_sub");

