pub(crate) fn arch68k_parse_variant(s: &str) -> Result<rustre_arch_68k::Mc68kVariant, McpError> {
    match s {
        "68000" | "M68000" => Ok(rustre_arch_68k::Mc68kVariant::M68000),
        "68010" | "M68010" => Ok(rustre_arch_68k::Mc68kVariant::M68010),
        "68020" | "M68020" => Ok(rustre_arch_68k::Mc68kVariant::M68020),
        "68030" | "M68030" => Ok(rustre_arch_68k::Mc68kVariant::M68030),
        "68040" | "M68040" => Ok(rustre_arch_68k::Mc68kVariant::M68040),
        "68060" | "M68060" => Ok(rustre_arch_68k::Mc68kVariant::M68060),
        "ColdFire" | "coldfire" => Ok(rustre_arch_68k::Mc68kVariant::ColdFire),
        other => Err(McpError::InvalidParams(format!("unknown variant '{other}'"))),
    }
}

