struct WireToolAdapter {
    name: String,
    inner: Box<dyn rustre_mcp_server::ToolHandler>,
}

impl rustre_mcp_server::McpToolHandler for WireToolAdapter {
    fn name(&self) -> &str {
        &self.name
    }

    fn execute(
        &self,
        params: Value,
    ) -> Result<Value, rustre_mcp_server::McpToolError> {
        let inner = &*self.inner;
        let joined = std::thread::scope(|s| {
            s.spawn(|| {
                let rt = tokio::runtime::Builder::new_current_thread()
                    .enable_all()
                    .build()
                    .map_err(|e| McpError::InternalError(format!(
                        "failed to build wire-tool runtime: {e}"
                    )))?;
                rt.block_on(inner.call(params))
            })
            .join()
        });
        let result = match joined {
            Ok(r) => r,
            Err(panic) => {
                let msg = panic
                    .downcast_ref::<&str>()
                    .map(|s| s.to_string())
                    .or_else(|| panic.downcast_ref::<String>().cloned())
                    .unwrap_or_else(|| "wire-tool worker thread panicked".into());
                return Err(rustre_mcp_server::McpToolError::ExecutionFailed(format!(
                    "tool panicked: {msg}"
                )));
            }
        };
        match result {
            Ok(tr) => {
                if let Some(rustre_mcp_server::ContentBlock::Text { text }) =
                    tr.content.first()
                {
                    if let Ok(v) = serde_json::from_str::<Value>(text) {
                        return Ok(v);
                    }
                    return Ok(Value::String(text.clone()));
                }
                Ok(serde_json::json!({ "is_error": tr.is_error }))
            }
            Err(e) => Err(rustre_mcp_server::McpToolError::ExecutionFailed(
                e.to_string(),
            )),
        }
    }
}

pub fn wire_into_server(server: &mut rustre_mcp_server::RustReMcpServer) {
    for (def, handler) in all_wire_handlers() {
        let catalog = wire_def_to_catalog(&def);
        let adapter = WireToolAdapter {
            name: def.name.clone(),
            inner: handler,
        };
        server.register_external_tool(catalog, Box::new(adapter));
    }
}

// Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ survey_binary Ã¢â‚¬â€ aggregator tool Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬


impl SurveyBinaryTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "survey_binary".to_string(),
            description:
                "One-shot binary triage: load a file and merge results from \
                 the loader, import/section tables, string extraction, function \
                 detection, entropy analysis, and call-target scan into a single \
                 JSON object.  Sub-call failures are recorded per-key rather than \
                 aborting the whole response."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "session_id": {
                        "type": "string",
                        "description": "Reserved: session identifier (unused — pass path instead)"
                    },
                    "path": {
                        "type": "string",
                        "description": "Absolute path to the binary file to survey"
                    }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for SurveyBinaryTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        use rustre_analysis_fn::{
            CallTargetCollector, DetectedArch, MemorySlice, detect_functions,
        };
        use rustre_core::address::Address;
        use rustre_triage::{FileKind, StringHeuristics, analyze_section_entropy, detect_file_kind};

        // Ã¢â€â‚¬Ã¢â€â‚¬ Resolve path Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
        let path = args
            .get("path")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'path'".into()))?;

        // Ã¢â€â‚¬Ã¢â€â‚¬ Load the binary Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
        let load = rustre_decompiler::load_binary(std::path::Path::new(path))
            .map_err(|e| McpError::InternalError(format!("load failed: {e}")))?;

        let data: &[u8] = &load.data;

        // Ã¢â€â‚¬Ã¢â€â‚¬ Detect format Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
        let file_kind = detect_file_kind(data);

        // Ã¢â€â‚¬Ã¢â€â‚¬ loader Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
        // Use RichLoadResult fields (already parsed by rustre_decompiler::load_binary)
        // and augment PE files with extra detail via rustre_loader_pe::PeInfo.
        let loader_val: Value = (|| -> Value {
            let base = json!({
                "kind": format!("{file_kind:?}"),
                "format": load.format,
                "arch": load.arch,
                "bits": load.bits,
                "endian": load.endian,
                "entry_point": load.entry_point,
                "base_address": load.base_address,
                "section_count": load.sections.len(),
                "import_count": load.imports.len(),
                "export_count": load.exports.len(),
            });
            // For PE files, attempt to add richer loader data.
            match file_kind {
                FileKind::Pe32
                | FileKind::Pe64
                | FileKind::Exe
                | FileKind::Dll
                | FileKind::Sys => {
                    match rustre_loader_pe::PeInfo::parse(data) {
                        Ok(info) => json!({
                            "kind": format!("{file_kind:?}"),
                            "format": load.format,
                            "arch": format!("{:?}", info.machine),
                            "bits": load.bits,
                            "endian": "little",
                            "entry_point": info.entry_point,
                            "image_base": info.image_base,
                            "is_dll": info.is_dll(),
                            "is_64bit": info.is_64bit(),
                            "checksum": info.checksum,
                            "section_count": info.sections.len(),
                            "import_count": info.imports.len(),
                            "export_count": info.exports.len(),
                        }),
                        Err(e) => {
                            let mut v = base;
                            v["pe_parse_warning"] = json!(e);
                            v
                        }
                    }
                }
                _ => base,
            }
        })();

        // Ã¢â€â‚¬Ã¢â€â‚¬ imports Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
        let imports_val: Value = (|| -> Value {
            let imports: Vec<Value> = load
                .imports
                .iter()
                .map(|i| {
                    json!({
                        "dll": i.dll,
                        "name": i.name,
                        "addr": i.addr,
                        "ordinal": i.ordinal,
                    })
                })
                .collect();
            // `by_dll` is the same data grouped by importing module — the
            // shape a reader wants ("what does this binary take from
            // kernel32?"). It is derived from the very same list, so the two
            // views cannot disagree. Ordinal-only imports are kept and
            // rendered as `#<ordinal>` rather than dropped or given a made-up
            // name.
            let mut by_dll: std::collections::BTreeMap<String, Vec<String>> =
                std::collections::BTreeMap::new();
            for i in &load.imports {
                // `name` is empty for an ordinal-only import; fall back to the
                // ordinal rather than emitting a blank entry.
                let label = if i.name.is_empty() {
                    i.ordinal.map_or_else(|| "#?".to_string(), |o| format!("#{o}"))
                } else {
                    i.name.clone()
                };
                by_dll.entry(i.dll.clone()).or_default().push(label);
            }
            json!({
                "count": imports.len(),
                "imports": imports,
                "by_dll": by_dll,
                "dll_count": by_dll.len(),
            })
        })();

        // Ã¢â€â‚¬Ã¢â€â‚¬ sections Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
        let sections_val: Value = (|| -> Value {
            let sections: Vec<Value> = load
                .sections
                .iter()
                .map(|s| {
                    json!({
                        "name": s.name,
                        "virtual_addr": s.virtual_addr,
                        "virtual_size": s.virtual_size,
                        "raw_offset": s.raw_offset,
                        "raw_size": s.raw_size,
                        "flags": s.flags,
                    })
                })
                .collect();
            json!({
                "count": sections.len(),
                // `list` is the name the survey specification uses; `sections`
                // is kept so existing readers of this tool keep working. Both
                // are the same array, built once.
                "list": sections.clone(),
                "sections": sections,
            })
        })();

        // Ã¢â€â‚¬Ã¢â€â‚¬ strings_top20 Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
        // Each hit is decorated with the computed virtual address (VA) by
        // resolving its file offset against the section table when one is
        // available; on formats with no section info we fall back to
        // `image_base + offset` so the VA field is always populated.
        let strings_val: Value = (|| -> Value {
            let all = StringHeuristics::extract_strings(data, 6);
            let image_base = load.base_address;
            let sections = &load.sections;
            let off_to_va = |off: u64| -> u64 {
                for s in sections {
                    let raw_off = s.raw_offset;
                    let raw_size = s.raw_size;
                    if off >= raw_off && off < raw_off + raw_size {
                        return image_base + s.virtual_addr + (off - raw_off);
                    }
                }
                image_base + off
            };
            let top: Vec<Value> = all
                .iter()
                .take(20)
                .map(|s| {
                    let off = s.offset as u64;
                    json!({
                        "value": s.value,
                        "offset": s.offset,
                        "va": off_to_va(off),
                        "encoding": format!("{:?}", s.encoding),
                    })
                })
                .collect();
            json!({
                "total": all.len(),
                // Specification names: `count` / `top20`. `total` and
                // `strings_top20` are kept for existing readers; all four are
                // views of one extraction, so they cannot drift.
                "count": all.len(),
                "top20": top.clone(),
                "strings_top20": top,
            })
        })();

        // Ã¢â€â‚¬Ã¢â€â‚¬ function_count Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
        // Function detection is shared by `function_count`, `functions`,
        // `callgraph` and `xrefs`. It used to run once per section — three
        // full passes over the image producing three copies of the same set,
        // which could also disagree if any caller passed a different arch.
        let detected_arch = match &load.arch as &str {
            "x86_64" | "amd64" | "x86-64" => DetectedArch::X86_64,
            "x86" | "i386" | "i686" => DetectedArch::X86_32,
            "arm64" | "aarch64" => DetectedArch::Arm64,
            _ => DetectedArch::Unknown,
        };
        let mem = MemorySlice::new(Address::new(load.base_address), data);
        let detected = detect_functions(detected_arch, &mem);

        // The call graph is built once and consumed by `callgraph`, `xrefs`
        // and `functions.top10_called`.
        let call_graph: Option<rustre_analysis_xref::call_graph_builder::CallGraph> = (|| {
            if !matches!(detected_arch, DetectedArch::X86_64 | DetectedArch::X86_32) {
                return None;
            }
            let base = load.base_address;
            let mut starts: Vec<u64> = detected.functions.iter().map(|f| f.start.as_u64()).collect();
            starts.sort_unstable();
            starts.dedup();
            if starts.is_empty() {
                return None;
            }

            let data_end = base.saturating_add(data.len() as u64);
            let mut builder = rustre_analysis_xref::call_graph_builder::CallGraphBuilder::new();
            for (i, &start) in starts.iter().enumerate() {
                let end = starts.get(i + 1).copied().unwrap_or(data_end);
                let (Ok(lo), Ok(hi)) = (
                    usize::try_from(start.saturating_sub(base)),
                    usize::try_from(end.saturating_sub(base)),
                ) else {
                    continue;
                };
                let hi = hi.min(data.len());
                if lo >= hi {
                    continue;
                }
                builder.scan_x86_calls(start, start, &data[lo..hi]);
            }
            Some(builder.build())
        })();

        let function_count_val: Value = json!({
            "function_count": detected.functions.len(),
            "arch": load.arch,
        });

        // Ã¢â€â‚¬Ã¢â€â‚¬ entropy_top Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
        let entropy_val: Value = (|| -> Value {
            let mut blocks = analyze_section_entropy(data);
            blocks.sort_by(|a, b| b.entropy.partial_cmp(&a.entropy).unwrap_or(std::cmp::Ordering::Equal));
            let top: Vec<Value> = blocks
                .iter()
                .take(10)
                .map(|b| {
                    json!({
                        "name": b.name,
                        "offset": b.offset,
                        "size": b.size,
                        "entropy": b.entropy,
                        "rating": format!("{:?}", b.rating),
                    })
                })
                .collect();
            json!({
                "block_count": blocks.len(),
                "entropy_top": top,
            })
        })();

        // Ã¢â€â‚¬Ã¢â€â‚¬ call_targets_count Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
        let call_targets_val: Value = (|| -> Value {
            let targets = CallTargetCollector::new(detected_arch).collect(&mem);
            json!({ "call_targets_count": targets.len() })
        })();

        // Ã¢â€â‚¬Ã¢â€â‚¬ Merge Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
        // -- exports ------------------------------------------------------
        //
        // Read from the PE export directory. `null` for a non-PE: an empty
        // list would assert "this file exports nothing", which is a different
        // claim from "this format has no PE export directory".
        //
        // An entry is either named or ordinal-only, and forwarders name the
        // target they redirect to — all three are reported as they are, with
        // no synthesised names.
        let exports_val: Value = (|| -> Value {
            let Ok(pe) = rustre_loader_pe::PeInfo::parse(data) else {
                return Value::Null;
            };
            let list: Vec<Value> = pe
                .exports
                .iter()
                .take(1000)
                .map(|e| {
                    json!({
                        "name": e.name,
                        "ordinal": e.ordinal,
                        "address": format!("{:#x}", e.address),
                        "forwarder": e.forwarder,
                    })
                })
                .collect();
            json!({
                "count": pe.exports.len(),
                "returned": list.len(),
                "list": list,
                "source": "rustre_loader_pe::PeInfo::exports",
            })
        })();

        // -- entropy ------------------------------------------------------
        //
        // Whole-file Shannon entropy with the rating the triage crate assigns
        // to it, plus the five highest-entropy blocks. The rating comes from
        // `EntropyRating::from_entropy` rather than a threshold re-implemented
        // here, so the survey and the triage tools cannot disagree about what
        // "High" means.
        let entropy_section_val: Value = (|| -> Value {
            let overall = rustre_triage_entropy::shannon_entropy(data);
            let rating = rustre_triage_entropy::EntropyRating::from_entropy(overall);
            let mut blocks = analyze_section_entropy(data);
            blocks.sort_by(|a, b| {
                b.entropy
                    .partial_cmp(&a.entropy)
                    .unwrap_or(std::cmp::Ordering::Equal)
            });
            let top5: Vec<Value> = blocks
                .iter()
                .take(5)
                .map(|b| {
                    json!({
                        "name": b.name,
                        "offset": b.offset,
                        "size": b.size,
                        "entropy": b.entropy,
                        "rating": format!("{:?}", b.rating),
                    })
                })
                .collect();
            json!({
                "overall": overall,
                "overall_rating": format!("{rating:?}"),
                "block_count": blocks.len(),
                "blocks_top5": top5,
                "source": "rustre_triage_entropy::{shannon_entropy, EntropyRating::from_entropy}",
            })
        })();

        // -- functions ----------------------------------------------------
        //
        // Built from the shared detection above, so `functions.count` can never
        // disagree with `function_count`.
        //
        // `top10_largest` needs a size, which needs an END address: the
        // detector leaves `end` as `None` when it could not determine one, and
        // those functions are EXCLUDED rather than given a guessed size. The
        // count of excluded entries is reported so the list is readable.
        //
        // `top10_called` is `null` when no call graph could be built (non-x86),
        // for the same reason the `callgraph` section is.
        let functions_val: Value = (|| -> Value {
            let named_count = detected
                .functions
                .iter()
                .filter(|f| f.name.as_ref().is_some_and(|n| !n.is_empty()))
                .count();

            let mut sized: Vec<(u64, u64, Option<&String>)> = detected
                .functions
                .iter()
                .filter_map(|f| {
                    let start = f.start.as_u64();
                    let end = f.end?.as_u64();
                    let size = end.checked_sub(start)?;
                    (size > 0).then_some((start, size, f.name.as_ref()))
                })
                .collect();
            let without_size = detected.functions.len() - sized.len();
            sized.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
            let top10_largest: Vec<Value> = sized
                .iter()
                .take(10)
                .map(|(start, size, name)| {
                    json!({ "va": format!("{start:#x}"), "size": size, "name": name })
                })
                .collect();

            let top10_called = call_graph.as_ref().map(|graph| {
                let mut by_callers: Vec<(u64, usize)> = graph
                    .callers
                    .iter()
                    .map(|(f, cs)| (*f, cs.len()))
                    .collect();
                by_callers.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
                by_callers
                    .iter()
                    .take(10)
                    .map(|(f, n)| json!({ "va": format!("{f:#x}"), "callers": n }))
                    .collect::<Vec<Value>>()
            });

            json!({
                "count": detected.functions.len(),
                "named_count": named_count,
                "top10_largest": top10_largest,
                "without_known_size": without_size,
                // null when no call graph exists for this architecture.
                "top10_called": top10_called,
                "source": "rustre_analysis_fn::detect_functions + rustre_analysis_xref::CallGraphBuilder",
            })
        })();

        // -- file ---------------------------------------------------------
        //
        // Identity and provenance of the input. `md5`/`sha256` come from
        // `RichLoadResult`'s own digests (the `sha2` / `md-5` crates), not a
        // re-implementation.
        //
        // `pe_timestamp` and `pdb_path` are PE-only and are `null` for any
        // other format — and `pdb_path` is also `null` for a PE that simply
        // carries no debug directory entry. Both nulls mean "this file does
        // not have one", which is what a caller needs to distinguish from an
        // empty string.
        let file_val: Value = (|| -> Value {
            let pe = rustre_loader_pe::PeInfo::parse(data).ok();
            let bits = pe.as_ref().map_or_else(
                || {
                    if load.arch.contains("64") {
                        64
                    } else {
                        32
                    }
                },
                |info| if info.flags.get(rustre_loader_pe::PeFlags::IS_64BIT) { 64 } else { 32 },
            );
            json!({
                "kind": format!("{file_kind:?}"),
                "size": data.len(),
                "md5": load.md5(),
                "sha256": load.sha256(),
                "image_base": load.base_address,
                "arch": load.arch,
                "bits": bits,
                // PE-only fields: null elsewhere, and null for a PE with no
                // debug directory.
                "pe_timestamp": pe.as_ref().map(|i| i.timestamp),
                "pdb_path": pe.as_ref().and_then(|i| i.pdb_path().map(str::to_owned)),
                "source": "rustre_loader::RichLoadResult + rustre_loader_pe::PeInfo",
            })
        })();

        // -- anti_analysis ------------------------------------------------
        //
        // Five of the six fields come from a real byte-level detector:
        //   anti_debug_found -> rustre_deobf_antianti::AntiDebugDetector
        //   anti_vm_found    -> rustre_deobf_antianti::AntiVmDetector
        //   cff_detected     -> rustre_deobf_cff::CffDispatcherDetector
        //   vm_detected      -> rustre_deobf_vm::VmDetector
        //   smc_detected     -> rustre_deobf_smc::SmcDetector
        //
        // `opaque_predicates` is `null` ON PURPOSE: the only detector for it,
        // `rustre_deobf_opaque::...::detect`, takes a `SimpleBranchCfg` — a
        // per-function control-flow graph, which this whole-file survey does
        // not build. Reporting `false` would claim "no opaque predicates in
        // this binary" when nothing looked for any.
        let anti_analysis_val: Value = (|| -> Value {
            let anti_debug = rustre_deobf_antianti::AntiDebugDetector::new().scan(data);
            let anti_vm = rustre_deobf_antianti::AntiVmDetector::new().scan(data);
            let smc = rustre_deobf_smc::SmcDetector::default().detect(data);
            let vm = rustre_deobf_vm::VmDetector::new().detect(data);
            let vm_detected = !matches!(vm.confidence, rustre_deobf_vm::VmConfidence::None);

            // CFF detection is code-only: run it over executable sections at
            // their real virtual addresses rather than over the whole file.
            let mut cff_count = 0usize;
            for sec in &load.sections {
                if !(sec.name == ".text" || sec.name.starts_with(".text") || sec.name == "__text") {
                    continue;
                }
                let Ok(off) = usize::try_from(sec.raw_offset) else { continue };
                let end = usize::try_from(sec.raw_offset.saturating_add(sec.raw_size))
                    .unwrap_or(data.len())
                    .min(data.len());
                if off >= end {
                    continue;
                }
                cff_count += rustre_deobf_cff::CffDispatcherDetector::detect(
                    &data[off..end],
                    load.base_address + sec.virtual_addr,
                )
                .len();
            }

            json!({
                "anti_debug_found": !anti_debug.is_empty(),
                "anti_debug_count": anti_debug.len(),
                "anti_vm_found": !anti_vm.is_empty(),
                "anti_vm_count": anti_vm.len(),
                "cff_detected": cff_count > 0,
                "cff_dispatcher_count": cff_count,
                "vm_detected": vm_detected,
                "vm_confidence": format!("{:?}", vm.confidence),
                "vm_dispatcher_count": vm.dispatcher_count,
                "smc_detected": !smc.is_empty(),
                "smc_region_count": smc.len(),
                // Requires a per-function CFG this survey does not build.
                "opaque_predicates": Value::Null,
                "opaque_predicates_note":
                    "not computed: needs a per-function control-flow graph, which                      this whole-file survey does not build",
                "source": "rustre_deobf_antianti / _cff / _vm / _smc detectors",
            })
        })();

        // -- flags --------------------------------------------------------
        //
        // Every flag is read from a parser, never inferred:
        //   is_signed / has_tls_callbacks / dotnet -> rustre_loader_pe::PeInfo
        //   has_dynamic_imports                    -> PE delay-load import table
        //   is_packed                              -> rustre_triage_entropy::PackingDetector
        //
        // The whole section is `null` for a file that is not a PE. An object of
        // `false`s would assert "not signed, no TLS callbacks, not .NET" about
        // an ELF nobody asked those questions of.
        let flags_val: Value = (|| -> Value {
            let Ok(pe) = rustre_loader_pe::PeInfo::parse(data) else {
                return Value::Null;
            };
            let indicators =
                rustre_triage_entropy::PackingDetector::detect_packing_indicators(data);
            json!({
                "is_packed": !indicators.is_empty(),
                "packing_indicators": indicators,
                "is_signed": pe.is_signed(),
                "has_tls_callbacks": pe.has_tls_callbacks(),
                // Delay-loaded imports are resolved at first call rather than
                // at load time — the PE-level notion of a dynamic import.
                "has_dynamic_imports": !pe.delay_imports.is_empty(),
                "delay_import_count": pe.delay_imports.len(),
                "dotnet": pe.flags.is_dotnet(),
                "source": "rustre_loader_pe::PeInfo + rustre_triage_entropy::PackingDetector",
            })
        })();

        // -- crypto -------------------------------------------------------
        //
        // Real constant scan via `rustre_crypto_id::ConstantScanner`, the same
        // engine behind `analysis_crypto_scan_path`. Nothing here is inferred
        // from entropy or guessed from section names: every entry is a byte
        // sequence that matched a known crypto constant table.
        //
        // `HIGH_CONFIDENCE` is stated as a constant rather than buried in a
        // comparison so the reported count has a documented meaning.
        let crypto_val: Value = (|| -> Value {
            use rustre_crypto_id::constant_scanner::{ConstSectionInfo, ConstantScanner};
            /// Scanner confidence at or above which a hit is reported as
            /// high-confidence. The scanner emits 0-100.
            const HIGH_CONFIDENCE: u8 = 80;

            let sections: Vec<ConstSectionInfo> = load
                .sections
                .iter()
                .map(|sec| ConstSectionInfo {
                    file_offset: sec.raw_offset,
                    file_size: sec.raw_size,
                    virtual_address: load.base_address + sec.virtual_addr,
                })
                .collect();

            let mut scanner = ConstantScanner::new();
            let hits = scanner.scan_with_sections(data, &sections);

            let mut by_algorithm: std::collections::BTreeMap<String, usize> =
                std::collections::BTreeMap::new();
            for hit in &hits {
                for algo in &hit.algorithms {
                    *by_algorithm.entry(algo.clone()).or_default() += 1;
                }
            }

            // A rename target is a high-confidence hit whose virtual address is
            // known: without a VA there is nothing to rename. The suggested
            // name is derived from the constant that matched, so the caller can
            // see WHY the name is proposed.
            let auto_rename_targets: Vec<Value> = hits
                .iter()
                .filter(|h| h.confidence >= HIGH_CONFIDENCE)
                .filter_map(|h| {
                    let va = h.va?;
                    let slug: String = h
                        .constant_name
                        .chars()
                        .map(|c| if c.is_ascii_alphanumeric() { c } else { '_' })
                        .collect();
                    Some(json!({
                        "va": format!("{va:#x}"),
                        "suggested_name": format!("g_{}", slug.to_ascii_lowercase()),
                        "constant": h.constant_name,
                        "algorithms": h.algorithms,
                        "confidence": h.confidence,
                    }))
                })
                .collect();

            json!({
                "count_high_confidence": hits.iter().filter(|h| h.confidence >= HIGH_CONFIDENCE).count(),
                "high_confidence_threshold": HIGH_CONFIDENCE,
                "count_total": hits.len(),
                "by_algorithm": by_algorithm,
                "auto_rename_targets": auto_rename_targets,
                "source": "rustre_crypto_id::ConstantScanner::scan_with_sections",
            })
        })();

        // -- callgraph + xrefs --------------------------------------------
        //
        // Built with `rustre_analysis_xref::CallGraphBuilder`, attributing each
        // `call rel32` site to the function that CONTAINS it, so the edges are
        // function->function rather than site->target.
        //
        // Both sections are `null` on any architecture other than x86/x86-64:
        // `scan_x86_calls` decodes the x86 `E8` opcode, and running it over ARM
        // or unknown code would yield a confident graph made of coincidences.
        // A null section says "not computed"; an empty one would say "this
        // binary calls nothing", which is a different and false claim.

        let (callgraph_val, xrefs_val): (Value, Value) = call_graph.as_ref().map_or(
            (Value::Null, Value::Null),
            |graph| {
            let function_count = detected.functions.len().max(1);
            let max_fanout = graph
                .callees
                .iter()
                .max_by_key(|(_, cs)| cs.len())
                .map(|(f, cs)| json!({ "func": format!("{f:#x}"), "callees": cs.len() }));

            let mut most_called: Vec<(u64, usize)> =
                graph.callers.iter().map(|(f, cs)| (*f, cs.len())).collect();
            most_called.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
            let top10: Vec<Value> = most_called
                .iter()
                .take(10)
                .map(|(f, n)| json!({ "func": format!("{f:#x}"), "callers": n }))
                .collect();

            // A plain ratio, not a score: direct calls per detected function.
            let density = graph.edges.len() as f64 / function_count as f64;

            (
                json!({
                    "nodes_count": graph.node_count(),
                    "edge_count": graph.edges.len(),
                    "max_fanout_function": max_fanout,
                    "source": "rustre_analysis_xref::CallGraphBuilder::scan_x86_calls",
                }),
                json!({
                    "density": density,
                    "density_unit": "direct calls per detected function",
                    "top10_most_called": top10,
                    "source": "rustre_analysis_xref::CallGraphBuilder::scan_x86_calls",
                }),
            )
        });

        let result = json!({
            "path": path,
            "file_size": data.len(),
            "file_kind": format!("{file_kind:?}"),
            "loader": loader_val,
            "imports": imports_val,
            "sections": sections_val,
            "strings_top20": strings_val.clone(),
            "strings": strings_val,
            "function_count": function_count_val,
            "entropy_top": entropy_val,
            "call_targets_count": call_targets_val,
            // null on non-x86 targets: "not computed", never "nothing found".
            "callgraph": callgraph_val,
            "xrefs": xrefs_val,
            "crypto": crypto_val,
            // null for non-PE inputs: these questions only have answers for a PE.
            "flags": flags_val,
            "anti_analysis": anti_analysis_val,
            "file": file_val,
            "functions": functions_val,
            "exports": exports_val,
            "entropy": entropy_section_val,
        });

        Ok(ToolResult::text(result.to_string()))
    }
}

// Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ analysis_fn_detect_functions_path Ã¢â‚¬â€ path-based wrapper Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬


impl AnalysisFnDetectFunctionsPathTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "analysis_fn_detect_functions_path".to_string(),
            description:
                "Detect function boundaries in a binary on disk.  Loads the \
                 file, infers architecture from the loader report, and runs \
                 the full multi-strategy detector.  Returns a list of \
                 functions with virtual addresses, confidence levels, and \
                 the detection source for each one."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "path": {
                        "type": "string",
                        "description": "Absolute path to the binary file"
                    },
                    "limit": {
                        "type": "integer",
                        "description": "Optional cap on the number of functions returned (default 5000)"
                    }
                },
                "required": ["path"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for AnalysisFnDetectFunctionsPathTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let path = args
            .get("path")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'path'".into()))?;
        let limit = args
            .get("limit")
            .and_then(Value::as_u64)
            .map(|v| v as usize)
            .unwrap_or(5000);

        let load = rustre_decompiler::load_binary(std::path::Path::new(path))
            .map_err(|e| McpError::InternalError(format!("load failed: {e}")))?;

        // The whole-load detector iterates every executable section with the
        // correct VA, merges symbol-table hints, and deduplicates. Calling
        // `detect_functions` on a flat MemorySlice over `load.data` would
        // produce nonsense addresses because raw file offsets are not VAs.
        let boundaries = rustre_decompiler::detect_functions_in_load(&load);

        let total = boundaries.len();
        let funcs: Vec<Value> = boundaries
            .iter()
            .take(limit)
            .map(|f| {
                json!({
                    "start": f.start.as_u64(),
                    "end": f.end.map(|e| e.as_u64()),
                    "confidence": format!("{:?}", f.confidence),
                    "source": format!("{:?}", f.source),
                    "name": f.name,
                })
            })
            .collect();

        let result = json!({
            "path": path,
            "arch": load.arch,
            "image_base": load.base_address,
            "function_count": total,
            "returned": funcs.len(),
            "functions": funcs,
        });
        Ok(ToolResult::text(result.to_string()))
    }
}

// Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ analysis_string_scan_path Ã¢â‚¬â€ path-based wrapper Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬


impl AnalysisStringScanPathTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "analysis_string_scan_path".to_string(),
            description:
                "Scan a binary on disk for ASCII / UTF-8 / UTF-16 strings.  \
                 Walks the loader section table and reports each hit with \
                 its virtual address, encoding, length and value — \
                 equivalent to IDA's strings window."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "path": {
                        "type": "string",
                        "description": "Absolute path to the binary file"
                    },
                    "min_length": {
                        "type": "integer",
                        "description": "Minimum character count for a string to be reported (default 5)"
                    },
                    "limit": {
                        "type": "integer",
                        "description": "Maximum number of strings returned (default 10000)"
                    }
                },
                "required": ["path"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for AnalysisStringScanPathTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        use rustre_analysis_string::{StringScanner, StringScannerConfig};
        use rustre_core::address::Address;

        let path = args
            .get("path")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'path'".into()))?;
        let min_length = args
            .get("min_length")
            .and_then(Value::as_u64)
            .map(|v| v as usize)
            .unwrap_or(5);
        let limit = args
            .get("limit")
            .and_then(Value::as_u64)
            .map(|v| v as usize)
            .unwrap_or(10_000);

        let load = rustre_decompiler::load_binary(std::path::Path::new(path))
            .map_err(|e| McpError::InternalError(format!("load failed: {e}")))?;

        let image_base = load.base_address;
        let mut cfg = StringScannerConfig::default();
        cfg.min_length = min_length;
        let scanner = StringScanner::new(cfg);

        let mut all = Vec::new();
        if load.sections.is_empty() {
            // No section table Ã¢â‚¬â€ fall back to scanning the whole file as
            // one block based at `image_base`.
            all.extend(scanner.scan(Address::new(image_base), &load.data));
        } else {
            for sec in &load.sections {
                let start = usize::try_from(sec.raw_offset).unwrap_or(usize::MAX);
                let size = usize::try_from(sec.raw_size).unwrap_or(0);
                let end = start.saturating_add(size).min(load.data.len());
                if start >= end {
                    continue;
                }
                let va_base = image_base + sec.virtual_addr;
                all.extend(scanner.scan(Address::new(va_base), &load.data[start..end]));
            }
        }
        // Stable order by VA.
        all.sort_by_key(|s| s.address.as_u64());

        let total = all.len();
        let out: Vec<Value> = all
            .into_iter()
            .take(limit)
            .map(|s| {
                json!({
                    "va": s.address.as_u64(),
                    "length": s.length,
                    "encoding": format!("{:?}", s.encoding),
                    "value": s.value,
                })
            })
            .collect();

        let result = json!({
            "path": path,
            "image_base": image_base,
            "total": total,
            "returned": out.len(),
            "strings": out,
        });
        Ok(ToolResult::text(result.to_string()))
    }
}

// Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ analysis_crypto_scan_path Ã¢â‚¬â€ findcrypt with section-resolved VA Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬


impl AnalysisCryptoScanPathTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "analysis_crypto_scan_path".to_string(),
            description:
                "Findcrypt-style scan. Loads the binary, walks every \
                 section, matches against the full crypto-constant table \
                 (LE+BE), and additionally flags BigNum / RSA-modulus \
                 candidates via a zero-block heuristic. Each hit carries \
                 a section-resolved VA suitable for cross-reference with \
                 disassembly."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "path": {
                        "type": "string",
                        "description": "Absolute path to the binary file"
                    },
                    "min_confidence": {
                        "type": "integer",
                        "description": "Filter out constants below this confidence (0..100, default 0)"
                    },
                    "bignum_min_zeros": {
                        "type": "integer",
                        "description": "Minimum run length of zero bytes to flag a BigNum candidate (default 48)"
                    },
                    "limit": {
                        "type": "integer",
                        "description": "Maximum total findings returned (default 5000)"
                    }
                },
                "required": ["path"]
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for AnalysisCryptoScanPathTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        use rustre_crypto_id::constant_scanner::{ConstSectionInfo, ConstantScanner};

        let path = args
            .get("path")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'path'".into()))?;
        let min_conf = args
            .get("min_confidence")
            .and_then(Value::as_u64)
            .map(|v| v as u8)
            .unwrap_or(0);
        let bignum_min_zeros = args
            .get("bignum_min_zeros")
            .and_then(Value::as_u64)
            .map(|v| v as usize)
            .unwrap_or(48);
        let limit = args
            .get("limit")
            .and_then(Value::as_u64)
            .map(|v| v as usize)
            .unwrap_or(5000);

        let load = rustre_decompiler::load_binary(std::path::Path::new(path))
            .map_err(|e| McpError::InternalError(format!("load failed: {e}")))?;

        let sections: Vec<ConstSectionInfo> = load
            .sections
            .iter()
            .map(|s| ConstSectionInfo {
                file_offset: s.raw_offset,
                file_size: s.raw_size,
                virtual_address: load.base_address + s.virtual_addr,
            })
            .collect();

        let mut scanner = ConstantScanner::new();
        scanner.set_min_confidence(min_conf);
        let hits = scanner.scan_with_sections(&load.data, &sections);

        let mut findings: Vec<Value> = hits
            .iter()
            .map(|h| {
                json!({
                    "kind": "constant",
                    "name": h.constant_name,
                    "algorithms": h.algorithms,
                    "constant_type": format!("{:?}", h.constant_type),
                    "endian": format!("{:?}", h.endian),
                    "confidence": h.confidence,
                    "file_offset": h.file_offset,
                    "length": h.length,
                    "va": h.va,
                })
            })
            .collect();

        // BigNum / RSA-modulus heuristic: scan each section for a window
        // that starts with `bignum_min_zeros` consecutive zero bytes
        // immediately preceding a high-entropy Ã¢â€°Â¥64-byte payload. Real RSA
        // moduli embedded as little-endian arrays show exactly this
        // shape; so do DH/ECDH primes encoded with leading zero padding.
        for sec in &load.sections {
            let start = usize::try_from(sec.raw_offset).unwrap_or(usize::MAX);
            let size = usize::try_from(sec.raw_size).unwrap_or(0);
            let end = start.saturating_add(size).min(load.data.len());
            if start >= end { continue; }
            let slice = &load.data[start..end];
            let mut i = 0usize;
            while i + bignum_min_zeros + 64 <= slice.len() {
                if slice[i] != 0 { i += 1; continue; }
                let mut zlen = 0usize;
                while i + zlen < slice.len() && slice[i + zlen] == 0 { zlen += 1; }
                if zlen >= bignum_min_zeros {
                    let tail_start = i + zlen;
                    let tail_end = (tail_start + 256).min(slice.len());
                    let tail = &slice[tail_start..tail_end];
                    // Reject tails that are themselves mostly zero or
                    // low-entropy ascii: count distinct nonzero bytes.
                    let mut seen = [false; 256];
                    let mut distinct = 0usize;
                    for &b in tail { if b != 0 && !seen[b as usize] { seen[b as usize] = true; distinct += 1; } }
                    if distinct >= 24 {
                        let file_off = start + i;
                        let va = load.base_address + sec.virtual_addr + i as u64;
                        findings.push(json!({
                            "kind": "bignum_candidate",
                            "name": "BIGNUM_ZERO_PADDED",
                            "algorithms": ["RSA", "DH", "ECDH"],
                            "constant_type": "FieldPrime",
                            "endian": "Neutral",
                            "confidence": 55,
                            "file_offset": file_off,
                            "length": zlen + tail.len(),
                            "va": va,
                            "zero_run": zlen,
                            "tail_distinct_bytes": distinct,
                        }));
                    }
                    i += zlen.max(1);
                } else {
                    i += zlen.max(1);
                }
            }
        }

        let total = findings.len();
        findings.truncate(limit);

        let result = json!({
            "path": path,
            "image_base": load.base_address,
            "section_count": load.sections.len(),
            "total": total,
            "returned": findings.len(),
            "findings": findings,
        });
        Ok(ToolResult::text(result.to_string()))
    }
}

// Re-export the silenced `hex_encode` helper as `pub use` so it is wired in
// via the wire module (avoids a dead-code warning for the import above when
// no future tool consumes it).
#[allow(dead_code)]
pub(crate) fn _ensure_hex_encode_wired() -> String {
    hex_encode(&[0u8])
}

// Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ forensics_fs artifact detection tools Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬

pub(crate) fn artifact_to_json(a: &rustre_forensics_fs::artifacts::Artifact) -> Value {
    let meta: serde_json::Map<String, Value> = a
        .metadata
        .iter()
        .map(|(k, v)| (k.clone(), Value::String(v.clone())))
        .collect();
    json!({
        "kind": format!("{:?}", a.kind),
        "path": a.path,
        "description": a.description,
        "confidence": a.confidence,
        "severity": format!("{:?}", a.severity),
        "metadata": Value::Object(meta),
    })
}

pub(crate) fn read_path_or_data(args: &Value) -> Result<(String, Vec<u8>), McpError> {
    let path = args
        .get("path")
        .and_then(Value::as_str)
        .ok_or_else(|| McpError::InvalidParams("missing 'path'".into()))?
        .to_string();
    let data: Vec<u8> = if let Some(d) = args.get("data") {
        if d.is_array() {
            extract_byte_array(args, "data", "data_hex")?
        } else if let Some(hex) = d.as_str() {
            let cleaned: String = hex.chars().filter(|c| !c.is_whitespace()).collect();
            if !cleaned.is_ascii() {
                return Err(McpError::InvalidParams("hex must be ASCII".into()));
            }
            (0..cleaned.len()).step_by(2)
                .map(|i| u8::from_str_radix(&cleaned[i..(i+2).min(cleaned.len())], 16)
                    .map_err(|e| McpError::InvalidParams(format!("data hex: {e}"))))
                .collect::<Result<Vec<u8>, _>>()?
        } else {
            Vec::new()
        }
    } else if let Ok(bytes) = std::fs::read(&path) {
        bytes
    } else {
        Vec::new()
    };
    Ok((path, data))
}


