impl DbBaseMigrationsWithDownSqlTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "db_base_migrations_with_down_sql".to_string(),
            description:
                "Return the versions/names of canonical base-schema migrations that \
                 provide a non-empty `down_sql`, from rustre_db::base_migrations()."
                    .to_string(),
            input_schema: json!({ "type": "object", "properties": {} }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for DbBaseMigrationsWithDownSqlTool {
    async fn call(&self, _args: Value) -> Result<ToolResult, McpError> {
        let migs = rustre_db::base_migrations();
        let items: Vec<Value> = migs
            .iter()
            .filter(|m| m.down_sql.as_ref().is_some_and(|s| !s.is_empty()))
            .map(|m| json!({ "version": m.version.0, "name": m.name }))
            .collect();
        Ok(ToolResult::text(
            json!({
                "count":   items.len(),
                "total":   migs.len(),
                "items":   items,
                "source":  "rustre_db::base_migrations",
            })
            .to_string(),
        ))
    }
}


impl DbBaseMigrationsUniqueVersionsTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "db_base_migrations_unique_versions".to_string(),
            description:
                "Return whether all `version` fields across rustre_db::base_migrations() \
                 are unique, plus any duplicate versions found."
                    .to_string(),
            input_schema: json!({ "type": "object", "properties": {} }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for DbBaseMigrationsUniqueVersionsTool {
    async fn call(&self, _args: Value) -> Result<ToolResult, McpError> {
        let migs = rustre_db::base_migrations();
        let mut seen: std::collections::BTreeMap<u32, u32> = std::collections::BTreeMap::new();
        for m in &migs {
            *seen.entry(m.version.0).or_insert(0) += 1;
        }
        let dups: Vec<u32> = seen.iter().filter_map(|(v, c)| if *c > 1 { Some(*v) } else { None }).collect();
        Ok(ToolResult::text(
            json!({
                "count":      migs.len(),
                "unique":     dups.is_empty(),
                "duplicates": dups,
                "source":     "rustre_db::base_migrations",
            })
            .to_string(),
        ))
    }
}


impl DbBaseMigrationsTotalSqlBytesTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "db_base_migrations_total_sql_bytes".to_string(),
            description:
                "Return the total byte lengths of `up_sql` and `down_sql` across all \
                 canonical base-schema migrations from rustre_db::base_migrations()."
                    .to_string(),
            input_schema: json!({ "type": "object", "properties": {} }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for DbBaseMigrationsTotalSqlBytesTool {
    async fn call(&self, _args: Value) -> Result<ToolResult, McpError> {
        let migs = rustre_db::base_migrations();
        let up_bytes: usize = migs.iter().map(|m| m.up_sql.len()).sum();
        let down_bytes: usize = migs.iter().map(|m| m.down_sql.as_ref().map_or(0, String::len)).sum();
        Ok(ToolResult::text(
            json!({
                "count":       migs.len(),
                "up_bytes":    up_bytes,
                "down_bytes":  down_bytes,
                "total_bytes": up_bytes + down_bytes,
                "source":      "rustre_db::base_migrations",
            })
            .to_string(),
        ))
    }
}

