impl DbBaseMigrationsAvgSqlBytesTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "db_base_migrations_avg_sql_bytes".to_string(),
            description:
                "Return the average byte length of `up_sql` across canonical base-schema \
                 migrations from rustre_db::base_migrations()."
                    .to_string(),
            input_schema: json!({ "type": "object", "properties": {} }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for DbBaseMigrationsAvgSqlBytesTool {
    async fn call(&self, _args: Value) -> Result<ToolResult, McpError> {
        let migs = rustre_db::base_migrations();
        let count = migs.len();
        let total: usize = migs.iter().map(|m| m.up_sql.len()).sum();
        #[allow(clippy::cast_precision_loss)]
        let avg = if count == 0 { 0.0 } else { total as f64 / count as f64 };
        Ok(ToolResult::text(
            json!({
                "count":       count,
                "total_bytes": total,
                "avg_bytes":   avg,
                "source":      "rustre_db::base_migrations",
            })
            .to_string(),
        ))
    }
}


