macro_rules! callconv_name_wrapper {
    ($tool:ident, $tool_name:literal, $func:ident, $desc:literal) => {
        pub struct $tool;
        impl $tool {
            #[must_use]
            pub fn definition() -> ToolDefinition {
                ToolDefinition {
                    name: $tool_name.to_string(),
                    description: $desc.to_string(),
                    input_schema: json!({ "type": "object", "properties": {} }),
                    parameters: json!({ "type": "object", "properties": {} }),
                }
            }
        }
        #[async_trait]
        impl ToolHandler for $tool {
            async fn call(&self, _args: Value) -> Result<ToolResult, McpError> {
                let cc = rustre_analysis_callconv::$func();
                Ok(ToolResult::text(json!({
                    "name": cc.name,
                    "max_reg_args": cc.max_reg_args,
                    "stack_alignment": cc.stack_alignment,
                    "caller_cleanup": cc.caller_cleanup,
                    "shadow_space_bytes": cc.shadow_space_bytes,
                    "source": concat!("rustre_analysis_callconv::", stringify!($func)),
                }).to_string()))
            }
        }
    };
}

