pub(crate) fn __vsa_si_from_args(v: &Value, prefix: &str) -> rustre_analysis_vsa::StridedInterval {
    let lo = v.get(&format!("{prefix}lo")).and_then(Value::as_u64).unwrap_or(0);
    let hi = v.get(&format!("{prefix}hi")).and_then(Value::as_u64).unwrap_or(lo);
    let stride = v.get(&format!("{prefix}stride")).and_then(Value::as_u64).unwrap_or(1);
    rustre_analysis_vsa::StridedInterval::new(lo, hi, stride)
}
pub(crate) fn __vsa_vals_arg(v: &Value, key: &str) -> Vec<u64> {
    v.get(key).and_then(Value::as_array).map(|a| a.iter().filter_map(Value::as_u64).collect()).unwrap_or_default()
}
// ── rustre-adb: additional wrappers ─────────────────────────────────────────
pub(crate) fn __adb_state_from_str(s: &str) -> rustre_adb::DeviceState {
    match s {
        "offline" => rustre_adb::DeviceState::Offline,
        "bootloader" => rustre_adb::DeviceState::Bootloader,
        "device" => rustre_adb::DeviceState::Device,
        "host" => rustre_adb::DeviceState::Host,
        "recovery" => rustre_adb::DeviceState::Recovery,
        "no-permissions" | "no permissions" => rustre_adb::DeviceState::NoPermissions,
        "sideload" => rustre_adb::DeviceState::Sideload,
        "unauthorized" => rustre_adb::DeviceState::Unauthorized,
        _ => rustre_adb::DeviceState::Unknown,
    }
}

