macro_rules! dwarf_cast_tool {
    ($t:ident, $name:literal, $desc:literal, $in:ty, $in_as:ident, $call:expr) => {
        pub struct $t;
        impl $t {
            #[must_use]
            pub fn definition() -> ToolDefinition {
                ToolDefinition {
                    name: $name.to_string(),
                    description: $desc.to_string(),
                    input_schema: json!({"type":"object","properties":{"x":{"type":"integer"}},"required":["x"]}),
                    parameters: Value::Null,
                }
            }
        }
        #[async_trait]
        impl ToolHandler for $t {
            async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
                let x = args.get("x").and_then(Value::$in_as)
                    .ok_or_else(|| McpError::InvalidParams("missing 'x'".into()))? as $in;
                let out = ($call)(x);
                Ok(ToolResult::text(json!({"input": x, "output": out, "source": concat!("rustre_symbols_dwarf::casts::", $name)}).to_string()))
            }
        }
    };
}

