pub(crate) fn dwarf_hex_decode(s: &str) -> Result<Vec<u8>, McpError> {
    let clean: String = s.chars().filter(|c| !c.is_whitespace()).collect();
    if clean.len() % 2 != 0 {
        return Err(McpError::InvalidParams("hex length must be even".into()));
    }
    let mut out = Vec::with_capacity(clean.len() / 2);
    let bytes = clean.as_bytes();
    for chunk in bytes.chunks(2) {
        let hi = (chunk[0] as char).to_digit(16).ok_or_else(|| McpError::InvalidParams("bad hex".into()))?;
        let lo = (chunk[1] as char).to_digit(16).ok_or_else(|| McpError::InvalidParams("bad hex".into()))?;
        out.push(((hi << 4) | lo) as u8);
    }
    Ok(out)
}

