pub(crate) fn vmlift_parse_semantic_wl(s: &str) -> rustre_deobf_vmlift::HandlerSemantic {
    use rustre_deobf_vmlift::{HandlerSemantic, BinOpKind, PushSrc, PopDst};
    match s.to_ascii_lowercase().as_str() {
        "push_const" => HandlerSemantic::Push(PushSrc::Constant(0)),
        "push_reg" => HandlerSemantic::Push(PushSrc::VirtualReg(0)),
        "push_mem" => HandlerSemantic::Push(PushSrc::Memory),
        "pop_reg" => HandlerSemantic::Pop(PopDst::VirtualReg(0)),
        "pop_mem" => HandlerSemantic::Pop(PopDst::Memory),
        "add" => HandlerSemantic::BinOp(BinOpKind::Add),
        "sub" => HandlerSemantic::BinOp(BinOpKind::Sub),
        "mul" => HandlerSemantic::BinOp(BinOpKind::Mul),
        "div" => HandlerSemantic::BinOp(BinOpKind::Div),
        "and" => HandlerSemantic::BinOp(BinOpKind::And),
        "or" => HandlerSemantic::BinOp(BinOpKind::Or),
        "xor" => HandlerSemantic::BinOp(BinOpKind::Xor),
        "shl" => HandlerSemantic::BinOp(BinOpKind::Shl),
        "shr" => HandlerSemantic::BinOp(BinOpKind::Shr),
        "load" => HandlerSemantic::Load(4),
        "store" => HandlerSemantic::Store(4),
        "cmp" => HandlerSemantic::Cmp,
        "branch" => HandlerSemantic::Branch,
        "call" => HandlerSemantic::Call,
        "ret" => HandlerSemantic::Ret,
        "halt" => HandlerSemantic::Halt,
        "ipadvance" => HandlerSemantic::IpAdvance(4),
        _ => HandlerSemantic::Unknown,
    }
}

/// Decode a caller-supplied hex payload, refusing what is not hex.
///
/// Feeds `vmlift_lift_instruction_count` and `vmlift_disassemble_to_text`,
/// which MEASURE rather than compare: a dropped byte misaligns the decode and
/// the instruction count comes back different and equally plausible. That is
/// the silent end of this family.
pub(crate) fn vmlift_hex_to_bytes_wl(h: &str) -> Result<Vec<u8>, McpError> { crate::hex_decode(h) }

pub(crate) fn parse_sym_kind_str_v2(s: &str) -> rustre_symbols::SymKind {
    match s {
        "Data" => rustre_symbols::SymKind::Data,
        "Label" => rustre_symbols::SymKind::Label,
        "Section" => rustre_symbols::SymKind::Section,
        _ => rustre_symbols::SymKind::Function,
    }
}

pub(crate) fn parse_symbols_array_v2(args: &Value) -> Vec<rustre_symbols::Symbol> {
    let mut syms = Vec::new();
    if let Some(arr) = args.get("symbols").and_then(Value::as_array) {
        for it in arr {
            let name = it.get("name").and_then(Value::as_str).unwrap_or("").to_string();
            let addr = it.get("address").and_then(Value::as_u64).unwrap_or(0);
            let kind_s = it.get("kind").and_then(Value::as_str).unwrap_or("Function");
            syms.push(rustre_symbols::Symbol::new(name, addr, parse_sym_kind_str_v2(kind_s)));
        }
    }
    syms
}

pub(crate) fn wire_def_to_catalog(def: &rustre_mcp_server::ToolDefinition) -> rustre_mcp_server::McpToolDef {
    rustre_mcp_server::McpToolDef::new(
        def.name.clone(),
        def.description.clone(),
        def.input_schema.clone(),
        rustre_mcp_server::ToolCategory::Analysis,
    )
}

// ─── analysis_basic_blocks_path / analysis_trace_data_flow_path ──────────────
//
// Two path-based wrappers that were referenced by `tests/bb_path_smoke.rs` and
// `tests/trace_data_flow.rs` but no longer existed, leaving both integration
// test targets unable to compile (and therefore silently not running). They
// are reinstated here on top of the analysis crates rather than re-adding a
// bespoke implementation:
//
//   * basic blocks — decoded with `iced-x86`, leaders taken from real branch
//     targets and fall-throughs, so `preds`/`succs` are genuine CFG edges
//     rather than a linear split. (`AnalyzeCfgTool` in `lib.rs` splits on a
//     hand-written opcode table and reports no edges at all.)
//   * data flow — call edges recovered with `rustre_analysis_xref`, then
//     walked by `rustre_analysis_dataflow::{trace_callers_backward,
//     trace_callees_forward}`.

/// Map a virtual address to the loaded file bytes that back it.
///
/// Returns the byte slice from `va` to the end of its containing section,
/// clamped to the data actually present in the file image. `None` when no
/// section covers `va` — callers must not fall back to file-offset
/// arithmetic, which yields nonsense addresses for any mapped image.
fn wt_bytes_at_va(load: &rustre_decompiler::RichLoadResult, va: u64) -> Option<&[u8]> {
    for s in &load.sections {
        let start = s.virtual_addr;
        let end = start.saturating_add(s.virtual_size);
        if va < start || va >= end {
            continue;
        }
        let delta = va - start;
        let off = usize::try_from(s.raw_offset.saturating_add(delta)).ok()?;
        if off >= load.data.len() {
            return None;
        }
        let raw_end = usize::try_from(s.raw_offset.saturating_add(s.raw_size))
            .unwrap_or(load.data.len())
            .min(load.data.len());
        if raw_end <= off {
            return None;
        }
        return Some(&load.data[off..raw_end]);
    }
    None
}

/// Parse an address given either as a JSON integer or as a `0x`-prefixed
/// string (the tests use both forms).
fn wt_addr_arg(args: &Value, key: &str) -> Option<u64> {
    match args.get(key) {
        Some(Value::Number(n)) => n.as_u64(),
        Some(Value::String(s)) => {
            let t = s.trim();
            t.strip_prefix("0x")
                .or_else(|| t.strip_prefix("0X"))
                .map_or_else(|| t.parse::<u64>().ok(), |h| u64::from_str_radix(h, 16).ok())
        }
        _ => None,
    }
}

pub struct AnalysisBasicBlocksPathTool;

impl AnalysisBasicBlocksPathTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "analysis_basic_blocks_path".to_string(),
            description:
                "Recover the basic blocks of one function in a binary on disk. \
                 Decodes the function's bytes, splits on real branch targets \
                 and fall-throughs, and returns each block with its address \
                 range plus its predecessor and successor blocks."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["path", "function_address"],
                "properties": {
                    "path": { "type": "string", "description": "Absolute path to the binary file" },
                    "function_address": {
                        "type": ["string", "integer"],
                        "description": "Virtual address of the function entry (0x… or decimal)"
                    },
                    "max_bytes": {
                        "type": "integer",
                        "description": "Upper bound on bytes decoded (default 65536)"
                    }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for AnalysisBasicBlocksPathTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        use std::collections::{BTreeMap, BTreeSet};

        let path = args
            .get("path")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'path'".into()))?;
        let entry = wt_addr_arg(&args, "function_address").ok_or_else(|| {
            McpError::InvalidParams("missing or unparseable 'function_address'".into())
        })?;
        let max_bytes = args
            .get("max_bytes")
            .and_then(Value::as_u64)
            .and_then(|v| usize::try_from(v).ok())
            .unwrap_or(64 * 1024);

        let load = rustre_decompiler::load_binary(std::path::Path::new(path))
            .map_err(|e| McpError::InternalError(format!("load failed: {e}")))?;

        let bytes = wt_bytes_at_va(&load, entry).ok_or_else(|| {
            McpError::InvalidParams(format!(
                "address {entry:#x} is not inside any mapped section of {path}"
            ))
        })?;
        let bytes = &bytes[..bytes.len().min(max_bytes)];

        // Decode linearly from the entry, stopping at the first return so a
        // single function is covered rather than the rest of the section.
        let bits = if load.arch.contains("32") { 32 } else { 64 };
        let mut decoder =
            iced_x86::Decoder::with_ip(bits, bytes, entry, iced_x86::DecoderOptions::NONE);
        let mut instrs: Vec<(u64, u64, Option<u64>, bool, bool)> = Vec::new(); // ip,next,target,is_cond,ends
        while decoder.can_decode() {
            let ins = decoder.decode();
            if ins.is_invalid() {
                break;
            }
            let ip = ins.ip();
            let next = ins.next_ip();
            use iced_x86::FlowControl as FC;
            let flow = ins.flow_control();
            let target = matches!(
                flow,
                FC::UnconditionalBranch | FC::ConditionalBranch
            )
            .then(|| ins.near_branch_target())
            .filter(|t| *t != 0);
            let is_cond = matches!(flow, FC::ConditionalBranch);
            let ends = matches!(flow, FC::Return | FC::UnconditionalBranch);
            instrs.push((ip, next, target, is_cond, ends));
            if matches!(flow, FC::Return) {
                break;
            }
        }
        if instrs.is_empty() {
            return Err(McpError::InternalError(format!(
                "no instruction decoded at {entry:#x}"
            )));
        }

        let lo = entry;
        let hi = instrs.last().map_or(entry, |i| i.1);
        let in_range = |a: u64| a >= lo && a < hi;

        // Leaders: the entry, every branch target inside the function, and the
        // instruction after every branch.
        let mut leaders: BTreeSet<u64> = BTreeSet::new();
        leaders.insert(entry);
        for &(_, next, target, is_cond, ends) in &instrs {
            if let Some(t) = target {
                if in_range(t) {
                    leaders.insert(t);
                }
            }
            if (is_cond || ends) && in_range(next) {
                leaders.insert(next);
            }
        }

        // Assign each instruction to its block, and record the edges leaving
        // the block it terminates.
        let leader_vec: Vec<u64> = leaders.iter().copied().collect();
        let block_of = |a: u64| -> Option<usize> {
            match leader_vec.binary_search(&a) {
                Ok(i) => Some(i),
                Err(0) => None,
                Err(i) => Some(i - 1),
            }
        };
        let mut succs: BTreeMap<usize, BTreeSet<usize>> = BTreeMap::new();
        let mut preds: BTreeMap<usize, BTreeSet<usize>> = BTreeMap::new();
        let mut block_end: BTreeMap<usize, u64> = BTreeMap::new();

        for &(ip, next, target, is_cond, ends) in &instrs {
            let Some(b) = block_of(ip) else { continue };
            block_end.insert(b, next);
            let mut add = |from: usize, to: u64| {
                if let Some(t) = block_of(to) {
                    if to == leader_vec[t] {
                        succs.entry(from).or_default().insert(t);
                        preds.entry(t).or_default().insert(from);
                    }
                }
            };
            if let Some(t) = target {
                if in_range(t) {
                    add(b, t);
                }
            }
            // Fall-through: conditional branches keep it, unconditional ones
            // and returns do not.
            if !ends && in_range(next) {
                add(b, next);
            }
        }

        let blocks: Vec<Value> = leader_vec
            .iter()
            .enumerate()
            .map(|(i, &start)| {
                json!({
                    "id": i,
                    "start": start,
                    "start_hex": format!("{start:#x}"),
                    "end": block_end.get(&i).copied().unwrap_or(start),
                    "preds": preds.get(&i).map(|s| s.iter().copied().collect::<Vec<_>>()).unwrap_or_default(),
                    "succs": succs.get(&i).map(|s| s.iter().copied().collect::<Vec<_>>()).unwrap_or_default(),
                })
            })
            .collect();

        let result = json!({
            "path": path,
            "function_address": entry,
            "instruction_count": instrs.len(),
            "block_count": blocks.len(),
            "blocks": blocks,
            "source": "iced-x86 decode + leader/edge reconstruction",
        });
        Ok(ToolResult::text(result.to_string()))
    }
}

pub struct AnalysisTraceDataFlowPathTool;

impl AnalysisTraceDataFlowPathTool {
    #[must_use]
    pub fn definition() -> ToolDefinition {
        ToolDefinition {
            name: "analysis_trace_data_flow_path".to_string(),
            description:
                "Trace call flow to or from an address in a binary on disk. \
                 Recovers direct call edges with rustre_analysis_xref, then \
                 walks them with rustre_analysis_dataflow's bounded backward / \
                 forward tracers. Returns the reached addresses and their count."
                    .to_string(),
            input_schema: json!({
                "type": "object",
                "required": ["path", "address"],
                "properties": {
                    "path": { "type": "string", "description": "Absolute path to the binary file" },
                    "address": {
                        "type": ["string", "integer"],
                        "description": "Virtual address to trace from (0x… or decimal)"
                    },
                    "direction": {
                        "type": "string",
                        "enum": ["backward", "forward"],
                        "description": "backward = callers of the address, forward = callees"
                    },
                    "max_depth": { "type": "integer", "description": "Hop limit (default 4)" }
                }
            }),
            parameters: Value::Null,
        }
    }
}

#[async_trait]
impl ToolHandler for AnalysisTraceDataFlowPathTool {
    async fn call(&self, args: Value) -> Result<ToolResult, McpError> {
        let path = args
            .get("path")
            .and_then(Value::as_str)
            .ok_or_else(|| McpError::InvalidParams("missing 'path'".into()))?;
        let addr = wt_addr_arg(&args, "address")
            .ok_or_else(|| McpError::InvalidParams("missing or unparseable 'address'".into()))?;
        let direction = args
            .get("direction")
            .and_then(Value::as_str)
            .unwrap_or("backward");
        if direction != "backward" && direction != "forward" {
            return Err(McpError::InvalidParams(format!(
                "'direction' must be \"backward\" or \"forward\", got {direction:?}"
            )));
        }
        let max_depth = args
            .get("max_depth")
            .and_then(Value::as_u64)
            .and_then(|v| usize::try_from(v).ok())
            .unwrap_or(4);

        let load = rustre_decompiler::load_binary(std::path::Path::new(path))
            .map_err(|e| McpError::InternalError(format!("load failed: {e}")))?;

        // Direct `call rel32` edges over every executable section. The call
        // site itself is the "caller" — attributing it to an enclosing
        // function would require function bounds this tool does not claim.
        let mut edges: Vec<(u64, u64)> = Vec::new();
        for s in &load.sections {
            if !(s.name == ".text" || s.name.starts_with(".text") || s.name == "__text") {
                continue;
            }
            let Ok(off) = usize::try_from(s.raw_offset) else { continue };
            if off >= load.data.len() {
                continue;
            }
            let end = usize::try_from(s.raw_offset.saturating_add(s.raw_size))
                .unwrap_or(load.data.len())
                .min(load.data.len());
            if end <= off {
                continue;
            }
            let bytes = &load.data[off..end];
            let base = s.virtual_addr;
            let mut i = 0usize;
            while i + 4 < bytes.len() {
                if bytes[i] == 0xE8 {
                    let rel =
                        i32::from_le_bytes([bytes[i + 1], bytes[i + 2], bytes[i + 3], bytes[i + 4]]);
                    let site = base.wrapping_add(i as u64);
                    let next_ip = site.wrapping_add(5);
                    let target = next_ip.wrapping_add(rel as i64 as u64);
                    edges.push((site, target));
                    i += 5;
                } else {
                    i += 1;
                }
            }
        }

        let (levels, total) = if direction == "backward" {
            let t = rustre_analysis_dataflow::trace_callers_backward(addr, max_depth, &edges);
            (t.levels, t.total)
        } else {
            let t = rustre_analysis_dataflow::trace_callees_forward(addr, max_depth, &edges);
            (t.levels, t.total)
        };
        let reached: Vec<Value> = levels
            .iter()
            .enumerate()
            .flat_map(|(hop, nodes)| {
                nodes.iter().map(move |n| {
                    json!({ "hop": hop + 1, "addr": n.addr, "name": n.name })
                })
            })
            .collect();

        let result = json!({
            "path": path,
            "address": addr,
            "direction": direction,
            "max_depth": max_depth,
            "edge_count": edges.len(),
            "count": total,
            "reached": reached,
            "source": "rustre_analysis_dataflow::trace_callers_backward / trace_callees_forward",
        });
        Ok(ToolResult::text(result.to_string()))
    }
}
